window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-2/neuro-musculo-squelettique","titre":"Neuro-musculo-squelettique","sources":[{"t":"Introduction à la FTCNM","q":"cours-01-introduction-ftcnm/quiz.html","f":"cours-01-introduction-ftcnm/fiche.html"},{"t":"Syndrome de la lésion du neurone moteur supérieur","q":"cours-02-slnms/quiz.html","f":"cours-02-slnms/fiche.html"},{"t":"Altérations sensorielles","q":"cours-03-alterations-sensorielles/quiz.html","f":"cours-03-alterations-sensorielles/fiche.html"},{"t":"Altérations cognitives","q":"cours-04-alterations-cognitives/quiz.html","f":"cours-04-alterations-cognitives/fiche.html"},{"t":"Dysfonctions cérébelleuses","q":"cours-05-dysfonctions-cerebelleuses/quiz.html","f":"cours-05-dysfonctions-cerebelleuses/fiche.html"},{"t":"Dysfonctions des noyaux gris centraux","q":"cours-06-noyaux-gris-centraux/quiz.html","f":"cours-06-noyaux-gris-centraux/fiche.html"},{"t":"Lésions médullaires I — syndromes et classification","q":"cours-07-lesions-medullaires-1/quiz.html","f":"cours-07-lesions-medullaires-1/fiche.html"},{"t":"Lésions médullaires II — phases, complications et kinésithérapie","q":"cours-08-lesions-medullaires-2/quiz.html","f":"cours-08-lesions-medullaires-2/fiche.html"},{"t":"Dysfonctions neurodégénératives et post-infectieuses","q":"cours-09-neurodegeneratives/quiz.html","f":"cours-09-neurodegeneratives/fiche.html"},{"t":"Instruments de mesure","q":"instruments-de-mesure/quiz.html","f":"instruments-de-mesure/fiche.html"}],"questions":[{"q":"Quelle était la logique dominante de la kinésithérapie neurologique dans la première moitié du XXᵉ siècle ?","o":["Récupérer au plus vite sans souci de qualité","Rechercher la qualité du mouvement avant toute chose","Immobiliser de façon prolongée et systématique","Agir de façon exclusivement cognitive"],"r":0,"e":"On visait la vitesse de récupération sans se soucier de sa qualité, en misant sur les compensations.","s":0},{"q":"Quelle conséquence avait la stratégie fondée sur les compensations ?","o":["Des déséquilibres, y compris du côté « sain »","Une récupération complète et symétrique, des deux côtés","Aucune conséquence mesurable, à long terme","Une meilleure qualité du mouvement"],"r":0,"e":"Elle entraînait des conséquences graves tant du côté le plus affecté que du côté « sain ». Ces déséquilibres touchent le mouvement et la posture.","s":0},{"q":"Quel est le point commun déterminant des approches apparues dans les années 40-50 ?","o":["La qualité de la performance du mouvement","L'usage systématique des orthèses","Le recours exclusif à l'électrothérapie, en séance","La suppression totale des compensations"],"r":0,"e":"Bien que différentes entre elles, elles visaient toutes une plus grande « normalité » du mouvement et de la posture.","s":0},{"q":"Quel est le focus permanent de l'intervention en FTCNM ?","o":["Influencer le système nerveux par la périphérie","Agir directement sur le tissu cérébral lésé","Renforcer seulement les muscles épargnés","Immobiliser le segment atteint, au repos"],"r":0,"e":"Le focus de l'intervention est toujours d'influencer le système nerveux via le stimulus en périphérie. On passe par un stimulus en périphérie.","s":0},{"q":"Pourquoi l'analyse du mouvement ne suffit-elle pas ?","o":["Un même comportement peut avoir des causes distinctes","Le mouvement des patients n'est pas mesurable de façon fiable","L'analyse du mouvement est trop coûteuse","Les patients neurologiques ne bougent pas"],"r":0,"e":"Il faut tenir compte de ce qui se cache derrière l'« output moteur » : des origines distinctes appellent des approches distinctes.","s":0},{"q":"Quelle structure ne figure PAS dans la liste des localisations lésionnelles à envisager ?","o":["Le système endocrinien","Le cervelet","La jonction neuromusculaire","Le tronc cérébral"],"r":0,"e":"Les localisations citées : cerveau, cervelet, tronc cérébral, moelle épinière, nerfs périphériques, jonction neuromusculaire.","s":0},{"q":"Quel mécanisme lésionnel ne figure PAS dans la liste du cours ?","o":["La surcharge mécanique répétée","La démyélinisation, des fibres nerveuses","L'accident vasculaire, cérébral","L'infection, virale ou bactérienne"],"r":0,"e":"Les mécanismes cités : démyélinisation, dégénérescence, traumatisme, accident vasculaire, tumeur, infection.","s":0},{"q":"Que devient la capacité neuroplastique après une lésion nerveuse ?","o":["Elle augmente, pour aider ou pour perturber","Elle disparaît, de façon définitive","Elle reste inchangée, quelle que soit la lésion","Elle diminue de moitié, au moins"],"r":0,"e":"Après une lésion nerveuse, la capacité neuroplastique augmente ; elle peut être utilisée au profit de la récupération ou devenir perturbatrice. Elle peut servir la récupération ou devenir perturbatrice.","s":0},{"q":"Comment définit-on l'évaluation en FTCNM ?","o":["Le recueil systématique d'informations pertinentes","La mesure isolée de la force, au dynamomètre","Un examen radiologique complet, avec IRM","Un questionnaire standardisé, unique et validé"],"r":0,"e":"Elle permet au clinicien de créer un tableau compréhensif des capacités et problèmes du patient. Les informations sont pertinentes et significatives.","s":0},{"q":"De quoi l'évaluation dépend-elle ?","o":["Du thérapeute, du patient, de l'environnement","Uniquement du patient, et de son diagnostic","Uniquement du matériel disponible, en cabinet","Uniquement du diagnostic médical posé"],"r":0,"e":"Ces trois dimensions sont explicitement citées dans le cours. Ce sont les caractéristiques du kinésithérapeute, du patient et de l'environnement.","s":0},{"q":"Comment l'évaluation doit-elle être menée ?","o":["Spécifique et globale, en cherchant les causes","Uniquement analytique, segment par segment","Uniquement globale, par l'observation de la fonction","Uniquement quantitative, par des scores"],"r":0,"e":"L'évaluation doit être aussi spécifique que globale, avec un effort pour chercher des relations de causalité dans le contexte du patient. On cherche des relations de causalité dans le contexte du patient.","s":0},{"q":"Quelle rubrique ne fait PAS partie de l'examen subjectif ?","o":["Le bilan articulaire analytique","L'histoire socio-familiale et du logement","Les attentes du patient quant à l'intervention","Les principaux problèmes rapportés par le patient"],"r":0,"e":"Le bilan articulaire relève de l'examen objectif ; l'examen subjectif comprend 7 rubriques dont l'histoire socio-familiale et les attentes.","s":0},{"q":"Quels sont les trois gestes de l'examen objectif ?","o":["Observation, palpation, mobilisation","Inspection, percussion, auscultation","Testing, goniométrie, palpation","Observation, testing, imagerie"],"r":0,"e":"L'examen objectif s'organise autour de l'observation, de la palpation et de la mobilisation.","s":0},{"q":"Que cherche-t-on à l'observation de la manière dont le patient se présente ?","o":["La base de support, la gravité, le poids","La force musculaire, segment par segment","Les réflexes ostéo-tendineux, aux quatre membres","La sensibilité discriminative, aux mains et aux pieds"],"r":0,"e":"Ce sont les quatre éléments cités pour « comment se présente-t-il ? ». On observe la relation avec la base de support et la gravité, la distribution du poids et la relation entre segments.","s":0},{"q":"Que cherche-t-on à l'observation de la manière dont le patient se meut ?","o":["Schéma, séquence, sélectivité, effort, compensations","L'amplitude articulaire seule, au goniomètre","La vitesse d'exécution seule, chronométrée sur dix mètres","La force développée seule, au dynamomètre"],"r":0,"e":"Ce sont les sept éléments listés pour « comment se meut-il ? ». On observe aussi la quantité de mouvement et les réactions associées.","s":0},{"q":"Que cherche-t-on par la palpation en FTCNM ?","o":["Viscoélasticité, tension, alignement des fibres","Les points gâchettes seuls, myofasciaux","Les pulsations artérielles, distales","La température cutanée, comparée au côté opposé sain"],"r":0,"e":"Ce sont les quatre éléments cités pour la palpation. La contraction est aussi palpée.","s":0},{"q":"Quel signe recherche-t-on spécifiquement à la mobilisation ?","o":["Des signes d'hyperréflexie","Une crépitation articulaire","Un épanchement","Une dysmétrie"],"r":0,"e":"À la mobilisation on évalue liberté des segments, participation au mouvement, activité stabilisatrice et signes d'hyperréflexie.","s":0},{"q":"Devant un patient qui ne bouge pas un segment, quelle démarche est correcte ?","o":["Chercher la cause : recrutement, tâche, consigne","Conclure aussitôt : paralysie, sans autre test","Augmenter l'intensité : stimulus trop faible, à renforcer","Passer au segment suivant : pas de réponse, on avance"],"r":0,"e":"Le cours insiste sur l'analyse causale : absence de recrutement moteur, incapacité à organiser la tâche, ou non-compréhension de la consigne. La cause peut être une absence de recrutement moteur, une incapacité à organiser la tâche ou une consigne mal comprise.","s":0},{"q":"Qui doit être inclus dans l'équipe multidisciplinaire ?","o":["Le patient lui-même","Uniquement les professionnels de santé","Uniquement le médecin et le kinésithérapeute","Uniquement la famille"],"r":0,"e":"Le cours précise explicitement que l'équipe multidisciplinaire inclut le patient lui-même.","s":0},{"q":"À quelle approche correspond le nom de Voss, Knott et Kabat (1954) ?","o":["La facilitation neuromusculaire proprioceptive","Le concept Bobath, ou neurodéveloppemental","Le réapprentissage moteur, programmé","L'approche de Brunnstrom, par synergies"],"r":0,"e":"Voss, Knott et Kabat (1954) sont à l'origine du PNF. C'est le PNF.","s":0},{"q":"Qui a développé le programme de réapprentissage moteur en 1982 ?","o":["Carr & Shepherd","Bobath","Margaret Rood","Margaret Johnstone"],"r":0,"e":"Carr & Shepherd (1982) — Programme de Réapprentissage Moteur.","s":0},{"q":"En quelle année le concept Bobath a-t-il été formalisé selon le cours ?","o":["1969","1954","1982","1989"],"r":0,"e":"Rood 1954, Voss/Knott/Kabat 1954, Brunnstrom 1956, Bobath 1969, Carr & Shepherd 1982, Johnstone 1989.","s":0},{"q":"Que démontre la comparaison des différentes approches neurologiques ?","o":["Aucune n'est supérieure, toutes battent le placebo","Le concept Bobath est supérieur aux autres","Le PNF est supérieur à toutes les autres","Aucune n'a d'effet démontré, même face au placebo seul"],"r":0,"e":"Toutes ont un effet positif supérieur à l'absence de traitement ou au placebo, sans supériorité de l'une sur l'autre. Toutes font aussi mieux que l'absence de traitement.","s":0},{"q":"Sur quoi l'intervention doit-elle se fonder, quelle que soit la philosophie retenue ?","o":["Le raisonnement clinique","Le protocole institutionnel","La préférence du thérapeute","La demande de la famille"],"r":0,"e":"Indépendamment des philosophies de traitement, l'intervention doit se fonder sur le raisonnement clinique.","s":0},{"q":"Comment définit-on la neuroplasticité ?","o":["La capacité des neurones à se modifier selon l'usage","La régénération complète des axones sectionnés","La création d'un nouvel hémisphère, après une lésion grave","La capacité des muscles à s'hypertrophier"],"r":0,"e":"C'est la capacité des neurones de modifier leur fonction, structure et profil chimique (nombre et type de neurotransmetteurs) selon l'utilisation qui leur est donnée. Les neurones modifient leur fonction, leur structure et leur profil chimique.","s":0},{"q":"Qui a établi les 10 principes de la neuroplasticité dépendante de l'expérience ?","o":["Kleim & Jones (2008)","Bobath (1969)","Shumway-Cook & Woollacott (2011)","Gracies (2005)"],"r":0,"e":"Kleim & Jones (2008) — ces principes sont la base de l'opérationnalisation de l'intervention.","s":0},{"q":"Que fait-on quand la plasticité est exploitable ?","o":["On la potentialise, pour guider la réorganisation","On propose aussitôt des aides techniques, pour compenser","On limite les stimulations, pour la protéger","On immobilise le segment, pour le protéger"],"r":0,"e":"Potentialiser la plasticité permet de guider la réorganisation du système nerveux. Il s'agit de la réorganisation du système nerveux.","s":0},{"q":"Que fait-on quand la plasticité est limitée ?","o":["On propose des alternatives, pour optimiser la fonction","On arrête la rééducation, faute de récupération possible","On augmente l'intensité, jusqu'à la récupération","On attend une récupération spontanée"],"r":0,"e":"Si la plasticité est limitée : alternatives fonctionnelles → optimiser la fonction → augmenter la capacité fonctionnelle. Les alternatives sont fonctionnelles.","s":0},{"q":"Dans la boucle de la plasticité, que suit l'altération de l'usage du système musculo-squelettique ?","o":["Une altération de la structure musculo-squelettique","La guérison spontanée, sans traitement","L'arrêt complet de la neuroplasticité, chez l'adulte","La restauration de l'information nerveuse"],"r":0,"e":"La boucle est : information nerveuse → structure/fonction du SN → usage du système musculo-squelettique → structure/fonction du système musculo-squelettique. La structure et la fonction du système musculo-squelettique sont altérées.","s":0},{"q":"À quel moment l'évaluation a-t-elle lieu ?","o":["Tout au long du contact avec la personne","Uniquement à la première séance","Uniquement en fin de prise en charge, au bilan final","Une fois par mois, à date fixe"],"r":0,"e":"Elle a lieu tout au long du processus : identification des problèmes, interrelations, hypothèses, planification de l'intervention.","s":0},{"q":"Pourquoi la stratégie des compensations produisait-elle des conséquences graves du côté « sain » ?","o":["Le report d'usage sur ce côté y crée des déséquilibres","Le côté sain perdait son innervation, par contagion","La lésion se propageait au côté opposé","L'immobilisation touchait les deux côtés"],"r":0,"e":"En misant tout sur les structures et muscles épargnés, on installait des déséquilibres importants du mouvement et de la posture, avec des conséquences graves tant du côté lésé que du côté « sain ».","s":0},{"q":"Pourquoi ne croyait-on pas à la récupération avant les années 40-50 ?","o":["On visait la vitesse de récupération, pas sa qualité","La neuroplasticité était jugée impossible, preuves à l'appui","Les patients refusaient les soins, par crainte","La kinésithérapie n'existait pas encore"],"r":0,"e":"La logique dominante était la rapidité au détriment de la qualité, avec un usage mis en avant des compensations : on ne croyait pas à la récupération. On misait sur les compensations.","s":0},{"q":"Quelles localisations lésionnelles faut-il envisager face à une pathologie neuromusculaire ?","o":["Le cerveau et le cervelet","Le tronc cérébral","La moelle épinière","Les nerfs et la jonction neuromusculaire","Le muscle strié lui-même"],"r":[0,1,2,3],"e":"Cerveau, cervelet, tronc cérébral, moelle épinière, nerfs périphériques et jonction neuromusculaire. Les nerfs concernés sont périphériques.","s":0},{"q":"Quels mécanismes lésionnels faut-il identifier ?","o":["Démyélinisation et dégénérescence","Traumatisme et accident vasculaire","Tumeur et infection","Leur évolution dans le temps","Une carence martiale, en fer"],"r":[0,1,2,3],"e":"Le mécanisme comprend sa nature (démyélinisation, dégénérescence, traumatisme, AVC, tumeur, infection) et sa dynamique (progressif ou non, temps d'installation et d'évolution). On précise si le mécanisme est progressif ou non, et son temps d'installation et d'évolution.","s":0},{"q":"Quelles questions poser face au comportement moteur observé ?","o":["Conséquences ou adaptations ?","Comment était-ce avant la lésion ?","Comment cela a-t-il évolué ?","Quel est le score musculaire ?"],"r":[0,1,2],"e":"Trois questions : distinguer conséquences et adaptations, connaître l'état antérieur et retracer l'évolution. Il s'agit de distinguer ce qui relève des conséquences et ce qui relève des adaptations.","s":0},{"q":"Pourquoi deux patients au comportement moteur semblable peuvent-ils relever d'approches différentes ?","o":["Un même comportement peut avoir des origines distinctes","Les protocoles varient selon les services","L'âge impose des techniques différentes","Les approches ne sont pas comparables, faute d'études fiables"],"r":0,"e":"C'est un principe central du cours : un comportement moteur semblable peut avoir des origines distinctes et bénéficier d'approches distinctes — d'où la primauté du raisonnement clinique.","s":0},{"q":"Quelles sont les quatre étapes du cercle de la plasticité ?","o":["Altération de l'information nerveuse","Altérations de la structure et de la fonction du système nerveux","Altération de l'usage du système musculo-squelettique","Altération de la structure et de la fonction du système musculo-squelettique","Altération de la vascularisation périphérique"],"r":[0,1,2,3],"e":"La boucle enchaîne information nerveuse → structure/fonction du SN → usage du système musculo-squelettique → structure/fonction du système musculo-squelettique, puis revient au départ.","s":0},{"q":"À quoi le système nerveux s'adapte-t-il constamment ?","o":["À ce que nous faisons, et là où nous le faisons","Uniquement à l'âge, au fil des années","Uniquement aux traitements médicamenteux","À rien, il reste figé une fois la croissance achevée"],"r":0,"e":"Le système nerveux s'adapte en permanence à nos activités et à leur contexte — ce qui fonde l'exploitation thérapeutique de la neuroplasticité.","s":0},{"q":"Quelles questions le kinésithérapeute doit-il se poser sur lui-même avant d'évaluer ?","o":["Suis-je expert dans le domaine ?","Ai-je besoin d'un tutorat ou d'un partenariat ?","Dois-je orienter le patient ?","Quel est mon salaire horaire ?"],"r":[0,1,2],"e":"L'évaluation dépend des caractéristiques du kinésithérapeute : expertise, besoin de tutorat ou de partenariat, nécessité d'orienter.","s":0},{"q":"Quelles questions concernent les caractéristiques de l'environnement dans l'évaluation ?","o":["Quelles ressources ?","Combien de temps ?","Quel est mon rôle dans l'institution ?","Quel est son moral ?"],"r":[0,1,2],"e":"Ressources, temps et rôle institutionnel relèvent de l'environnement. Les conditions physiques et psychologiques relèvent du patient. Les conditions physiques et psychologiques relèvent des caractéristiques du patient.","s":0},{"q":"Quelle est la séquence du processus d'évaluation ?","o":["Problèmes → interrelations → hypothèses → planification","Hypothèses → problèmes → planification → bilan","Planification → évaluation des capacités → hypothèses → problèmes","Palpation → observation → mobilisation → tests"],"r":0,"e":"L'évaluation, présente tout au long du contact, enchaîne identification des problèmes, recherche d'interrelations, formulation d'hypothèses et planification. La planification porte sur l'intervention.","s":0},{"q":"Quelles rubriques composent l'examen subjectif en FTCNM ?","o":["Données personnelles et cliniques","Histoire clinique actuelle et antérieure","Histoire socio-familiale et logement","Problèmes rapportés et attentes","Résultats des examens d'imagerie"],"r":[0,1,2,3],"e":"Sept rubriques : données personnelles, données cliniques, histoire actuelle, histoire antérieure, histoire socio-familiale et du logement, problèmes rapportés et attentes.","s":0},{"q":"Que cherche-t-on lorsqu'on observe comment le patient se présente ?","o":["Sa relation avec la base de support","Sa relation avec la gravité","La distribution du poids et la symétrie","La relation entre les différents segments","La séquence d'activation musculaire"],"r":[0,1,2,3],"e":"Base de support, gravité, distribution du poids et symétrie, relation entre segments. La séquence d'activation s'observe quand le patient se meut.","s":0},{"q":"Que cherche-t-on lorsqu'on observe comment le patient se meut ?","o":["Quantité de mouvement et schéma","Séquence d'activation et sélectivité","Effort et compensations","Réactions associées","Alignement des fibres musculaires"],"r":[0,1,2,3],"e":"Quantité, schéma, séquence d'activation, sélectivité, effort, compensations et réactions associées. L'alignement des fibres relève de la palpation.","s":0},{"q":"Que recherche-t-on par la palpation en FTCNM ?","o":["La viscoélasticité","La tension musculaire","L'alignement des fibres","La contraction","L'hyperréflexie"],"r":[0,1,2,3],"e":"Propriétés viscoélastiques, tension musculaire, alignement des fibres et contraction. L'hyperréflexie se recherche à la mobilisation. Il s'agit des propriétés viscoélastiques du muscle.","s":0},{"q":"Que cherche-t-on lors de la mobilisation en FTCNM ?","o":["La liberté des segments","La participation au mouvement","L'activité stabilisatrice","Les signes d'hyperréflexie","La viscoélasticité du muscle"],"r":[0,1,2,3],"e":"La mobilisation, passive ou active, explore la liberté des segments, la participation au mouvement, l'activité stabilisatrice et les signes d'hyperréflexie.","s":0},{"q":"Quelles hypothèses envisager devant un patient qui ne bouge pas un segment ?","o":["Il n'a pas de recrutement moteur","Il ne parvient pas à organiser la tâche","Il ne comprend pas la consigne","Il refuse délibérément de coopérer"],"r":[0,1,2],"e":"Trois hypothèses à explorer : absence de recrutement moteur, incapacité à organiser la tâche, ou incompréhension de la consigne.","s":0},{"q":"À quelles approches correspondent les noms de Margaret Rood et de Margaret Johnstone ?","o":["Rood : 1954 · Johnstone : 1989","Rood : 1969 · Johnstone : 1982","Rood : PNF · Johnstone : concept Bobath","Rood : 1982 · Johnstone : 1956"],"r":0,"e":"Margaret Rood en 1954 et Margaret Johnstone en 1989. Le PNF est de Voss, Knott et Kabat (1954), le concept Bobath de 1969.","s":0},{"q":"Sur quoi porte la neuroplasticité selon la définition du cours ?","o":["La fonction des neurones","La structure des neurones","Le profil chimique des neurones","Le nombre initial de neurones"],"r":[0,1,2],"e":"La neuroplasticité est la capacité des neurones à modifier leur fonction, leur structure et leur profil chimique selon l'usage qui leur est donné. Le profil chimique comprend le nombre et le type de neurotransmetteurs.","s":0},{"q":"Pourquoi les principes de la neuroplasticité sont-ils dits « transversaux à toute l'équipe » ?","o":["Ils guident l'intervention de toute l'équipe","Ils sont enseignés dans toutes les filières universitaires","Ils concernent uniquement le médecin","Ils n'ont aucune application clinique"],"r":0,"e":"La neuroplasticité est l'un des grands fondements de la réhabilitation après lésion du SNC, et ses principes valent pour toute l'équipe, dont le patient fait partie. Ils fondent l'opérationnalisation de l'intervention de tous les intervenants, pas seulement du kinésithérapeute.","s":0},{"q":"Quelle est la conséquence directe d'une lésion du neurone moteur supérieur ?","o":["Une faiblesse, par défaut de recrutement","Une destruction immédiate du muscle, par dénervation","Une perte de la seule sensibilité profonde","Une augmentation de la force musculaire"],"r":0,"e":"La lésion du NMS entraîne une perte d'excitabilité du NMI, donc un défaut de recrutement musculaire : la faiblesse. L'excitabilité du NMI (neurone moteur inférieur) diminue.","s":1},{"q":"Que contrôle le système dorsolatéral (voies motrices directes) ?","o":["Le contrôle volontaire des muscles distaux","Le contrôle automatique des muscles proximaux","La régulation du tonus musculaire, de façon globale","Les réflexes végétatifs, viscéraux"],"r":0,"e":"Système dorsolatéral = contrôle volontaire des muscles distaux controlatéraux. Les muscles sont controlatéraux.","s":1},{"q":"Que contrôle le système ventromédial ?","o":["Les muscles proximaux, en automatique, et le tonus","Les muscles distaux, en commande volontaire","La sensibilité thermo-algique, du tronc","La coordination fine, des doigts et de la main dominante"],"r":0,"e":"Les voies indirectes du système ventromédial assurent le contrôle automatique des muscles proximaux (bilatéraux et ipsilatéraux) et la régulation du tonus.","s":1},{"q":"Comment se définit la parésie spastique ?","o":["Une commande perdue, avec une activité tonique exacerbée","Une simple faiblesse musculaire, isolée","Une rigidité constante sur toute l'amplitude, dans tous les sens","Une hypotonie permanente, flasque et durable"],"r":0,"e":"Elle combine la perte du contrôle volontaire et automatique des muscles et une activité tonique exacerbée. La commande perdue est à la fois volontaire et automatique.","s":1},{"q":"À quoi correspondent les signes positifs du SLNMS ?","o":["Une activité motrice excessive ou inadéquate","Un déficit de performance, en deçà de la normale","Des signes uniquement sensitifs, cutanés","Des altérations osseuses, tardives"],"r":0,"e":"Signes positifs = activité motrice excessive ou inadéquate ; signes négatifs = activité en deçà de la normale.","s":1},{"q":"Quel signe est un signe NEURAL ?","o":["L'hyperréflexie","Un raccourcissement musculaire","Une tendinite","Une déformation osseuse"],"r":0,"e":"Les signes neuraux (parésie, hypoesthésie, hypotonie, hyperréflexie) sont la conséquence directe de la lésion ou de l'adaptation neuroplastique.","s":1},{"q":"Quel signe est un signe NON NEURAL ?","o":["Un raccourcissement musculaire","Une hyperréflexie vive","Une parésie distale","Une hypoesthésie tactile"],"r":0,"e":"Les signes non neuraux sont des adaptations ou lésions du système musculo-squelettique : raccourcissements, tendinites, déformations osseuses.","s":1},{"q":"Qu'est-ce que la compensation motrice ?","o":["Des unités de substitution et des fixations","Le recrutement de synapses silencieuses","L'introduction d'aides techniques adaptées","La neurogenèse, dans l'hippocampe"],"r":0,"e":"Compensation motrice = recrutement d'unités de substitution et développement de fixations, à distinguer de la compensation neurale et fonctionnelle. On recrute des unités de substitution et on développe des fixations.","s":1},{"q":"Qu'est-ce que la compensation neurale ?","o":["La réorganisation du système nerveux lui-même","L'usage d'une canne, au quotidien","Le recrutement d'unités de substitution","L'apprentissage d'une stratégie cognitive de remplacement"],"r":0,"e":"La compensation neurale regroupe les processus de réorganisation du système nerveux. Elle passe par les synapses silencieuses, le bourgeonnement axonal et la « neurogenèse ».","s":1},{"q":"Qu'est-ce que la compensation fonctionnelle ?","o":["Des aides techniques ou des stratégies cognitives","La réorganisation synaptique, spontanée","Le développement de fixations, au tronc et aux ceintures","L'augmentation du tonus, pour se tenir"],"r":0,"e":"C'est une approche spécifique et objective visant à favoriser la fonctionnalité. Elles favorisent la fonctionnalité.","s":1},{"q":"La lésion de quelle aire aboutit spécifiquement à la parésie ?","o":["Le cortex moteur primaire","Le cortex préfrontal","Le cortex visuel primaire","L'hippocampe"],"r":0,"e":"Toute aire centrale lésée peut affecter le mouvement, mais ce sont les lésions du cortex moteur primaire (exécution) qui aboutissent à la parésie.","s":1},{"q":"Quel changement des motoneurones médullaires est cité comme cause de difficulté de recrutement ?","o":["L'augmentation du seuil d'excitabilité","La diminution du seuil d'excitabilité","La perte totale de la myéline","Une hypertrophie neuronale"],"r":0,"e":"Les changements directs des propriétés des MN médullaires, par exemple l'augmentation du seuil d'excitabilité.","s":1},{"q":"Quelle est la différence entre immobilité et non-usage ?","o":["L'immobilité est périphérique, le non-usage central","L'immobilité est centrale, le non-usage périphérique et local","Ce sont deux synonymes, sans nuance","Le non-usage ne concerne que la sensibilité"],"r":0,"e":"Immobilité = situation périphérique de manque de mouvements passifs ou actifs ; non-usage = comportement central de manque de commande volontaire. L'immobilité est un manque de mouvement ; le non-usage, un manque de commande volontaire.","s":1},{"q":"Quelle est la conséquence fonctionnelle d'un allongement structurel du muscle ?","o":["Une incapacité à produire assez de force","Une incapacité à initier le mouvement","Une hypertonie majeure, en flexion","Une hyperréflexie isolée, à l'étirement"],"r":0,"e":"Raccourcissement structurel → incapacité à initier le mouvement ; allongement structurel → incapacité à produire une force appropriée.","s":1},{"q":"Quels récepteurs informent la moelle lorsque le muscle est allongé ?","o":["Les fuseaux neuromusculaires","Les organes tendineux de Golgi uniquement","Les corpuscules de Pacini","Les nocicepteurs"],"r":0,"e":"Les fuseaux neuromusculaires informent la moelle épinière et les motoneurones α sont activés pour se contracter.","s":1},{"q":"Quelle voie réticulo-spinale a une influence inhibitrice ?","o":["La réticulo-spinale latérale (bulbaire)","La réticulo-spinale médiale (pontique)","La vestibulo-spinale","La rubro-spinale"],"r":0,"e":"La réticulo-spinale latérale ou bulbaire a une influence inhibitrice ; c'est celle qui reçoit le plus d'influence du cortex.","s":1},{"q":"Quelle voie réticulo-spinale a une influence excitatrice ?","o":["La réticulo-spinale médiale (pontique)","La réticulo-spinale latérale (bulbaire)","La cortico-spinale latérale","La spino-thalamique"],"r":0,"e":"La réticulo-spinale médiale ou pontique a une influence excitatrice.","s":1},{"q":"Que se passe-t-il sans inhibition pré-synaptique au niveau de la corne postérieure ?","o":["Une hyperréflexie se déclenche alors","Le tonus s'effondre, de façon durable","La sensibilité disparaît, en distal","La force augmente, par facilitation"],"r":0,"e":"Sans modulation de l'information sensorielle afférente, l'hyperréflexie se déclenche (proprioceptive, cutanée, nociceptive). Elle peut être proprioceptive, cutanée ou nociceptive.","s":1},{"q":"Quelle manifestation n'appartient PAS aux signes positifs du SLNMS ?","o":["L'hypotonie","Le clonus","Le signe de Babinski","Les réactions associées"],"r":0,"e":"L'hypotonie est un signe négatif. Les signes positifs reposent sur l'hyperexcitabilité des réflexes médullaires.","s":1},{"q":"Comment s'objective le tonus musculaire ?","o":["Par la résistance à l'étirement passif continu","Par la force maximale volontaire, au dynamomètre","Par l'amplitude articulaire passive, au goniomètre","Par la vitesse de contraction, mesurée en électromyographie"],"r":0,"e":"Le tonus est l'état de « préparation » des tissus contractiles, objectivé par la résistance à l'étirement passif continu.","s":1},{"q":"Quelle est la source d'une variation NON pathologique du tonus ?","o":["Les propriétés viscoélastiques du muscle","La contraction réflexe, à l'étirement","La perte d'inhibition réciproque","L'hyperexcitabilité du motoneurone alpha, médullaire"],"r":0,"e":"La variation non pathologique tient aux propriétés viscoélastiques du muscle ; la variation pathologique à la tension installée par la contraction réflexe.","s":1},{"q":"Selon le groupe SPASM (Pandyan, 2005), la spasticité est :","o":["Une activation involontaire, intermittente ou maintenue","Une hypertonie constante, quelle que soit la vitesse","Une faiblesse musculaire isolée, sans aucune activité réflexe","Une rétraction tendineuse, fixée et indolore"],"r":0,"e":"C'est la définition retenue dans le cours, en précisant qu'elle résulte d'une lésion du 1ᵉʳ neurone. Elle traduit une dysfonction du contrôle sensori-moteur, après une lésion du 1ᵉʳ neurone.","s":1},{"q":"Quelle altération neurale aboutit à une co-contraction agoniste/antagoniste ?","o":["La perte d'inhibition réciproque","La perte de l'inhibition non réciproque","L'hyperexcitabilité du MNα","La diminution de la fréquence de décharge"],"r":0,"e":"La perte d'inhibition réciproque aboutit à la co-contraction ; la perte d'inhibition non réciproque (OTG) aboutit à l'hypertonie.","s":1},{"q":"Quelle altération non neurale contribue à la spasticité ?","o":["Le nombre de sarcomères, donc la longueur du muscle","La perte d'inhibition pré-synaptique, médullaire","L'hyperexcitabilité du motoneurone alpha","L'hyperréflexie cutanée, plantaire"],"r":0,"e":"Les altérations non neurales incluent le nombre de sarcomères, le type de fibre, le tissu conjonctif et la rétraction articulaire.","s":1},{"q":"Quel est le statut des altérations non neurales dans la spasticité ?","o":["Elles sont jugées déterminantes dans le tableau","Elles sont négligeables, au second plan","Elles sont exclusivement tardives, après plusieurs années","Elles n'ont jamais été étudiées, à ce jour"],"r":0,"e":"Il n'y a pas assez de littérature pour attribuer l'activité anormale aux seules altérations neurales : les non neurales sont déterminantes.","s":1},{"q":"Qu'est-ce que le clonus ?","o":["Un mouvement rythmique involontaire, réflexe","Une contraction volontaire répétée, rapide","Une rétraction musculaire fixée, chronique","Un tremblement de repos, parkinsonien"],"r":0,"e":"Il résulte aussi du manque de commande supérieure pour son arrêt. Le réflexe d'étirement reste continuellement excitable.","s":1},{"q":"Comment définit-on les réactions associées ?","o":["L'activation de muscles qui ne participent pas au geste","Une contraction volontaire du côté sain","Un réflexe cutané plantaire, en extension, type Babinski","Une co-contraction physiologique, utile"],"r":0,"e":"Ce sont des activations d'unités motrices ou de muscles qui ne participent normalement pas au mouvement réalisé.","s":1},{"q":"Quel élément ne déclenche PAS les réactions associées ?","o":["Le repos complet en décubitus","L'effort (toux, éternuement)","L'émotion (peur, stress)","Les stimuli nocifs"],"r":0,"e":"Les déclencheurs cités sont l'instabilité posturale, l'effort, l'émotion et les stimuli nocifs.","s":1},{"q":"Quelle est la différence entre co-contraction spastique et co-contraction involontaire normale ?","o":["La spastique gêne les agonistes, la normale stabilise","La normale limite le mouvement, la spastique le libère","La spastique améliore la dextérité, la normale non","Aucune différence, les deux étant involontaires et utiles"],"r":0,"e":"La co-contraction normale permet une plus grande stabilité d'un segment pour plus de dextérité ; la spastique perturbe la fonction des agonistes. La stabilité apportée par la co-contraction normale sert la dextérité.","s":1},{"q":"Quel est l'effet du non-usage chronique ?","o":["Il altère le système nerveux et aggrave la parésie","Il protège le muscle, en évitant la fatigue et les lésions","Il diminue la spasticité, durablement","Il n'a aucun effet sur le système central"],"r":0,"e":"Le non-usage chronique réduit encore la capacité à recruter volontairement les unités motrices : il aggrave la parésie.","s":1},{"q":"Pourquoi le cortex influence-t-il aussi les voies motrices issues du tronc cérébral ?","o":["Ces voies régulent le tonus musculaire","Ces voies commandent la sensibilité, cutanée et profonde","Ces voies remplacent le corticospinal","Ces voies ne règlent que les muscles distaux"],"r":0,"e":"Le cortex module les voies motrices d'origine bulbo-pontique, fondamentales pour la régulation du tonus — d'où la parésie spastique quand cette modulation disparaît. Ce sont les voies d'origine bulbo-pontique.","s":1},{"q":"Que contrôlent les voies motrices indirectes ?","o":["Le contrôle automatique des muscles proximaux ipsilatéraux","La régulation du tonus musculaire","Le contrôle volontaire des muscles distaux controlatéraux","La sensibilité épicritique"],"r":[0,1],"e":"Les voies indirectes assurent le contrôle automatique des muscles proximaux ipsilatéraux et la régulation du tonus. Le contrôle volontaire distal controlatéral revient au système dorsolatéral.","s":1},{"q":"De quelles lésions le SLNMS peut-il résulter ?","o":["Lésions cérébrales","Lésions du tronc cérébral","Lésions médullaires","Lésions du nerf périphérique"],"r":[0,1,2],"e":"Le SLNMS décrit une fonction motrice anormale pouvant résulter de lésions cérébrales, du tronc cérébral ou médullaires — pas d'une atteinte périphérique.","s":1},{"q":"Quels signes sont des signes neuraux du SLNMS ?","o":["Parésie","Hypoesthésie","Hypotonie","Hyperréflexie","Tendinite"],"r":[0,1,2,3],"e":"Parésie, hypoesthésie, hypotonie et hyperréflexie sont neuraux. Les déformations osseuses, comme les raccourcissements et tendinites, sont non neurales. Les déformations osseuses, raccourcissements et tendinites sont non neuraux.","s":1},{"q":"Quels processus relèvent de la compensation neurale ?","o":["Le recrutement de synapses silencieuses","Le bourgeonnement axonal","La « neurogenèse »","L'introduction d'aides techniques"],"r":[0,1,2],"e":"Synapses silencieuses, bourgeonnement axonal et « neurogenèse » sont neuraux. Les aides techniques relèvent de la compensation fonctionnelle.","s":1},{"q":"Quel est le statut scientifique de la classification des compensations ?","o":["Une classification conceptuelle, d'usage clinique","Une classification internationale, validée","Une échelle de mesure, standardisée","Une norme ISO, publiée et révisée tous les cinq ans"],"r":0,"e":"La fiche précise que cette classification est conceptuelle et d'usage clinique, et qu'elle ne correspond pas à une taxonomie scientifique standardisée. Elle ne repose pas sur une taxonomie scientifique standardisée.","s":1},{"q":"Quelle est la séquence des événements initiaux de la cascade physiopathologique (Gracies, 2005) ?","o":["Lésion → recrutement perdu → parésie → non-usage","Spasticité → parésie → lésion → immobilité","Immobilité → lésion du SNC → parésie → spasticité tardive","Hyperréflexie → parésie → compensation"],"r":0,"e":"Les événements initiaux enchaînent lésion du SNC, perte de recrutement moteur, parésie, puis immobilité et non-usage central. Il s'agit d'une lésion du SNC, puis immobilité et non-usage central.","s":1},{"q":"Quelles manifestations d'hyperactivité musculaire résultent de la réorganisation du SNC ?","o":["Spasticité","Dystonie spastique","Co-contraction","Hypotonie"],"r":[0,1,2],"e":"Spasticité, dystonie spastique et co-contraction, auxquelles s'ajoutent les altérations plastiques du muscle (raccourcissements, contractures).","s":1},{"q":"Quel est le trajet décrit menant de la lésion corticale à l'hémiplégie ?","o":["Cortex moteur → corticospinal latéral → moelle → nerfs","Cervelet → tronc cérébral → moelle → muscle","Noyaux gris centraux → cortex → moelle → muscle","Nerf périphérique → moelle → cortex moteur → tronc cérébral"],"r":0,"e":"Cortex moteur primaire → corticospinal latéral → moelle → nerfs périphériques. Sans excitation périphérique : hémiparésie, hémiplégie et hypotonie de l'hémicorps controlatéral. Le cortex est le cortex moteur primaire ; les nerfs sont périphériques.","s":1},{"q":"Quelles altérations expliquent la difficulté de recrutement des motoneurones ?","o":["Une fréquence de décharge réduite","Une fatigue centrale et périphérique","Une faiblesse liée au non-usage","Des tissus contractiles remaniés","Des fuseaux neuromusculaires dégénérés"],"r":[0,1,2,3],"e":"Les quatre mécanismes sont cités, et aboutissent à plus d'effort neural pour générer de la force et à une perte de sélectivité. La faiblesse est non neurale ; le remaniement porte sur la quantité, l'alignement, la longueur et le type d'unités motrices.","s":1},{"q":"Quelle est la conséquence fonctionnelle d'un raccourcissement structurel du muscle ?","o":["Une incapacité à initier le mouvement","Une force produite insuffisante","Une hyperréflexie, à l'étirement","Un clonus inépuisable, à la cheville"],"r":0,"e":"Fibres maintenues en raccourcissement → raccourcissement structurel → incapacité à initier le mouvement. L'allongement structurel donne, lui, une incapacité à produire une force appropriée. L'allongement structurel donne, lui, une force insuffisante.","s":1},{"q":"Quelle voie réticulo-spinale reçoit le plus d'influence du cortex, et avec quelle conséquence si elle est lésée ?","o":["La latérale, inhibitrice : l'excitation n'est plus freinée","La médiale, excitatrice : le tonus s'effondre","La latérale, excitatrice : une hypotonie s'installe","La médiale, inhibitrice : une parésie flasque s'installe vite"],"r":0,"e":"La réticulo-spinale latérale (bulbaire) est inhibitrice et la plus influencée par le cortex. Sa lésion laisse s'exprimer l'activité excitatrice de la voie médiale pontique. La latérale est bulbaire ; l'excitation est celle de la voie médiale pontique.","s":1},{"q":"Quelles conséquences corticales accompagnent l'hémiparésie controlatérale ?","o":["Altérations du schéma moteur","Perte de dextérité","Précision et vitesse altérées","Sensibilité thermique perdue"],"r":[0,1,2],"e":"Altérations du schéma moteur, perte de dextérité et altérations de la précision et de la vitesse. La dextérité est la flexibilité pour s'adapter à la tâche.","s":1},{"q":"Quels types d'hyperréflexie peuvent se déclencher en l'absence d'inhibition pré-synaptique ?","o":["Proprioceptive","Cutanée","Nociceptive","Vestibulaire"],"r":[0,1,2],"e":"Sans modulation de l'information afférente à la corne postérieure, des hyperréflexies proprioceptive, cutanée et nociceptive se déclenchent.","s":1},{"q":"Quelles altérations neurales participent à la spasticité ?","o":["Perte d'inhibition pré-synaptique","Hyperexcitabilité du motoneurone alpha","Perte d'inhibition réciproque","Perte d'inhibition non réciproque","Nombre de sarcomères modifié"],"r":[0,1,2,3],"e":"Les quatre premiers mécanismes sont neuraux. L'altération du nombre de sarcomères est non neurale. La perte d'inhibition pré-synaptique du MNα donne l'hyperréflexie ; l'inhibition réciproque perdue mène à la co-contraction ; l'OTG n'inhibe plus la contraction excessive.","s":1},{"q":"Quelles altérations non neurales contribuent à la spasticité ?","o":["Sarcomères et longueur du muscle","Type de fibre musculaire","Tissu conjonctif et viscoélasticité","Rétraction articulaire et adhérences","Inhibition pré-synaptique perdue"],"r":[0,1,2,3],"e":"Les quatre sont non neurales, et la fiche souligne qu'elles sont considérées comme déterminantes. La rétraction articulaire s'accompagne d'altérations du cartilage et d'une désorganisation ligamentaire.","s":1},{"q":"Décrivez la boucle du clonus.","o":["Étirement → contraction réflexe → nouvel étirement","Raccourcissement → allongement spontané → repos","OTG inhibe → OTG excite → inhibition à nouveau","Commande volontaire → arrêt → nouvelle commande"],"r":0,"e":"Le clonus naît d'une excitabilité continue du réflexe d'étirement et du manque de commande supérieure pour l'arrêter : la résistance étire, la contraction réflexe répond, et la boucle se perpétue. La résistance appliquée étire le muscle, la contraction réflexe dirige le segment contre elle, et ainsi de suite.","s":1},{"q":"Quelle est l'évolution en trois temps des réactions associées ?","o":["Signes initiaux dans l'hémicorps lésé","Réponse compensatoire en tâche exigeante","Schéma involontaire et stéréotypé","Disparition spontanée après six mois"],"r":[0,1,2],"e":"Trois temps : signes initiaux, réponse compensatoire dans les tâches exigeantes, puis schéma involontaire et stéréotypé. La réponse est involontaire ; le recrutement devient plus fréquent.","s":1},{"q":"Quelles caractéristiques accompagnent les réactions associées ?","o":["Séquence de recrutement altérée","Tonus accru, amplitudes inadéquates","Précision et efficience diminuées","Effort accru pendant le mouvement","Tonus musculaire diminué, flasque"],"r":[0,1,2,3],"e":"Les quatre caractéristiques sont citées.","s":1},{"q":"Sur quoi l'intervention doit-elle porter pour interrompre le cercle vicieux du SLNMS ?","o":["Le maintien de l'intégrité ostéo-articulaire","La récupération de la fonction motrice « normale »","Uniquement la réduction de la spasticité","Uniquement le renforcement du côté sain"],"r":[0,1],"e":"L'intervention doit porter à la fois sur le maintien de l'intégrité ostéo-articulaire et sur la récupération de la fonction motrice « normale ».","s":1},{"q":"Que désigne le feedforward dans le contrôle moteur ?","o":["Des mécanismes anticipatoires, avant le mouvement","L'information sur l'état du système, après coup","Un réflexe médullaire, déclenché par l'étirement du fuseau","La correction d'erreur, en fin de trajectoire"],"r":0,"e":"Feedforward = mécanismes anticipatoires activés avant le mouvement pour le préparer ; feedback = information sur l'état du système.","s":2},{"q":"Quelle est l'opportunité principale offerte au kinésithérapeute par les systèmes sensoriels ?","o":["Influencer la neuroplasticité","Mesurer la force musculaire","Évaluer la densité osseuse","Réduire la spasticité par étirement"],"r":0,"e":"C'est à travers les systèmes sensoriels que le kinésithérapeute peut influencer la neuroplasticité.","s":2},{"q":"Quelle conséquence n'est PAS attribuée aux altérations sensorielles ?","o":["Une atrophie musculaire directe par dénervation","Une difficulté à organiser les inputs pour le contrôle postural","Une moindre capacité d'adaptation aux exigences de l'environnement","Un développement imprécis des modèles corporels internes"],"r":0,"e":"Les trois conséquences citées sont l'organisation des inputs posturaux, l'adaptation et les modèles corporels internes.","s":2},{"q":"Que discriminent les aires sensorielles primaires ?","o":["L'intensité et la qualité de chaque type d'input","La seule localisation du stimulus, sur la peau","Le sens des objets, par association","Les émotions associées, par le système limbique"],"r":0,"e":"Chaque aire sensorielle primaire discrimine différentes intensités et qualités de chaque type d'input.","s":2},{"q":"Quelle est la conséquence d'une lésion des aires sensorielles primaires ?","o":["Une moindre discrimination d'intensité et de qualité","Une agnosie visuelle, pour les objets courants","Une prosopagnosie, pour les visages familiers","Une héminégligence de l'espace gauche, visuel"],"r":0,"e":"Elle interfère sévèrement avec la capacité d'utiliser les sensations. Les agnosies relèvent des aires d'association.","s":2},{"q":"Quel est le rôle du cortex d'association sensorielle ?","o":["Donner du sens à l'input sensoriel reçu","Recevoir directement les afférences de la périphérie","Générer la commande motrice, volontaire","Réguler le tonus musculaire, au repos"],"r":0,"e":"Il analyse l'input sensoriel provenant tant du thalamus que des aires sensorielles primaires, en lui donnant du sens. Il analyse l'input provenant du thalamus et des aires primaires.","s":2},{"q":"Quelle est la principale conséquence d'une lésion des aires d'association sensorielle ?","o":["Les agnosies","La parésie","Le clonus","L'hypotonie"],"r":0,"e":"Au-delà de l'atteinte de la performance motrice, les agnosies sont les principales conséquences.","s":2},{"q":"Qu'est-ce que l'astéréognosie ?","o":["L'incapacité à reconnaître des objets par le toucher","L'incapacité à reconnaître des visages familiers","L'incapacité à reconnaître les couleurs des objets","Une perte de la sensibilité thermique des mains"],"r":0,"e":"L'astéréognosie est l'incapacité à reconnaître des objets par le toucher.","s":2},{"q":"Qu'est-ce que la prosopagnosie ?","o":["Ne plus reconnaître les visages, sans trouble de la vue","Ne plus savoir nommer les objets usuels","Perdre la vision périphérique, des deux côtés","Ne plus reconnaître les couleurs, par agnosie chromatique"],"r":0,"e":"Dans les cas graves, la personne peut même ne pas reconnaître son reflet.","s":2},{"q":"Comment une personne prosopagnosique reconnaît-elle les gens ?","o":["Surtout grâce aux indices de l'environnement","Uniquement par la voix, au téléphone ou de près","Par la reconnaissance des couleurs","Elle ne reconnaît jamais personne"],"r":0,"e":"La reconnaissance des personnes se fait surtout par les indices fournis par l'environnement.","s":2},{"q":"Comment appelle-t-on l'incapacité à reconnaître les couleurs ?","o":["L'agnosie chromatique","L'astéréognosie","La prosopagnosie","L'anosognosie"],"r":0,"e":"L'agnosie chromatique fait partie des agnosies visuelles.","s":2},{"q":"La reconnaissance des visages a-t-elle le même traitement que celle des objets ?","o":["Non, son traitement visuel semble différent","Oui, exactement le même traitement","Non, elle dépend uniquement du toucher","Non, elle dépend du système vestibulaire, et de lui seul"],"r":0,"e":"Le cours souligne que la reconnaissance des visages semble avoir un traitement visuel différent de celui des objets.","s":2},{"q":"Quelle est la première étape du cercle vicieux sensori-moteur ?","o":["Le non-usage moteur","La réorganisation corticale","L'hyperesthésie","La diminution de l'activation corticale"],"r":0,"e":"Non-usage moteur → diminution du stimulus sensoriel → diminution de l'activation corticale → réorganisation corticale.","s":2},{"q":"Qu'est-ce qui explique l'hyperesthésie dans ce cercle vicieux ?","o":["Le système cherche à capter plus d'information","Les zones corticales servent à d'autres fonctions","Une hypertonie musculaire, par spasticité associée","Une lésion du thalamus, postérieure"],"r":0,"e":"Hyperesthésie : le système cherche à capter plus d'information. Hypoesthésie : les zones corticales servent à d'autres fonctions.","s":2},{"q":"Que se passe-t-il quand l'individu n'est pas stimulé à bouger ?","o":["Il reconnaît moins les stimuli, l'aire régresse","Sa sensibilité s'affine, par compensation centrale","Son tonus augmente, par excès d'activité réflexe","Ses réflexes disparaissent, tous à la fois"],"r":0,"e":"Il reçoit peu ou pas d'information des récepteurs de la peau, du muscle et des articulations. L'aire corticale correspondante diminue.","s":2},{"q":"Quelle intervention est indiquée en cas d'hyperesthésie ?","o":["La désensibilisation","L'immobilisation stricte","L'augmentation de l'intensité du stimulus","L'arrêt de toute stimulation"],"r":0,"e":"Le cours insiste sur l'importance de la désensibilisation en cas d'hyperesthésie.","s":2},{"q":"Quels systèmes contribuent au schéma corporel ?","o":["Plusieurs systèmes, pas le seul somatosensoriel","Le seul système somatosensoriel, par la proprioception","Le seul système visuel, par l'image du corps","Le seul système vestibulaire, par la tête"],"r":0,"e":"Il faut considérer la vision (qui peut être déstabilisante) et le système vestibulaire (position de la tête et gravité).","s":2},{"q":"Quels paramètres faut-il considérer pendant la stimulation sensorielle ?","o":["Modalité et localisation, intensité, durée","L'intensité seule, réglée au maximum toléré","La durée seule, comptée en minutes","La fréquence seule, comme en électrothérapie"],"r":0,"e":"Ces quatre paramètres sont cités, avec l'importance de la sommation et de l'intégration.","s":2},{"q":"Quel est le lieu de traitement inconscient et non somatosensoriel ?","o":["Le cervelet","Le cortex somatosensoriel primaire","Le thalamus","L'hippocampe"],"r":0,"e":"Il y a plusieurs lieux de traitement : le cortex (conscient) et le cervelet (inconscient, non somatosensoriel).","s":2},{"q":"Quel type d'environnement stimule l'apprentissage ?","o":["Un environnement multisensoriel","Un environnement totalement neutre","Un environnement sans indice visuel","Un environnement silencieux et sombre"],"r":0,"e":"Le cours indique qu'un environnement multisensoriel stimule l'apprentissage.","s":2},{"q":"À quelle lésion le syndrome de Pusher est-il associé ?","o":["Une lésion des noyaux thalamiques postéro-latéraux","Une lésion du cortex visuel primaire, occipital","Une lésion cérébelleuse, vermienne et hémisphérique droite","Une lésion médullaire cervicale, haute"],"r":0,"e":"Le syndrome de Pusher est associé à une lésion des noyaux thalamiques postéro-latéraux.","s":2},{"q":"Comment se comporte un patient présentant un syndrome de Pusher ?","o":["Il se pousse avec ses membres sains vers le côté lésé","Il se pousse vers le côté sain, avec ses membres lésés","Il reste parfaitement immobile, sans aucun appui latéral","Il se penche uniquement en avant, vers ses genoux"],"r":0,"e":"Il se pousse constamment avec les membres sains vers le côté lésé, d'où la perte du contrôle postural.","s":2},{"q":"Quelle est la perception du patient avec syndrome de Pusher ?","o":["Il se sent droit alors qu'il penche vers le côté lésé","Il se sait incliné, mais ne peut pas se corriger","Il perçoit correctement la verticale","Il ne perçoit plus du tout son corps"],"r":0,"e":"Il existe une altération de la perception de la posture corporelle par rapport à la verticalité.","s":2},{"q":"Quel système reste intègre dans le syndrome de Pusher ?","o":["Le système visuel","Le système vestibulaire","Le système proprioceptif","Le système auditif"],"r":0,"e":"Il semble exister une intégrité du système visuel, d'où l'usage de stratégies visuelles pour l'organisation de l'équilibre.","s":2},{"q":"Quel est l'enjeu thérapeutique dans le syndrome de Pusher ?","o":["Indices visuels ou stimulation de la proprioception","Renforcer seulement le côté sain, en force","Immobiliser le tronc dans un corset rigide","Supprimer tout indice visuel, les yeux bandés"],"r":0,"e":"C'est précisément le débat posé par le cours. L'enjeu est d'arbitrer entre ces deux options.","s":2},{"q":"Quelles aires assurent le traitement spatial et l'orientation égocentrique ?","o":["Les aires pariéto-temporales","Le cortex moteur primaire","Le cortex auditif primaire","Le cervelet"],"r":0,"e":"Les aires pariéto-temporales assurent les capacités perceptives, constructives, l'organisation du schéma corporel et l'orientation égocentrique.","s":2},{"q":"Pour quoi les aires de traitement spatial sont-elles essentielles ?","o":["Au planning des mouvements et au contrôle postural","À la mémoire épisodique, des événements","À la régulation du tonus musculaire","À la production du langage, oral et écrit, à gauche"],"r":0,"e":"Elles sont essentielles au planning des mouvements et au contrôle postural.","s":2},{"q":"Que peut conditionner une atteinte du thalamus ?","o":["Le fonctionnement des capacités perceptives","La force musculaire distale uniquement","La consolidation osseuse","La conduction périphérique"],"r":0,"e":"Des atteintes au niveau du thalamus et/ou du cortex d'association sensorielle peuvent conditionner les capacités perceptives.","s":2},{"q":"Pour quelle raison faut-il impliquer la main dans les positionnements et les tâches ?","o":["Pour maintenir le stimulus et éviter la réorganisation","Pour augmenter la seule force de préhension","Pour prévenir l'ostéoporose du membre","Pour améliorer la circulation veineuse et éviter l'œdème"],"r":0,"e":"C'est la contre-mesure directe du cercle vicieux non-usage → moins de stimulus → réorganisation corticale. La réorganisation corticale serait défavorable.","s":2},{"q":"Quelle est la conséquence de la privation motrice sur la sensibilité ?","o":["Elle réduit l'information reçue des récepteurs","Elle n'a aucun effet sur la sensibilité","Elle augmente la discrimination tactile","Elle ne touche que la sensibilité thermique"],"r":0,"e":"Au-delà des conséquences motrices, la privation motrice a aussi un impact direct sur la sensibilité. Les récepteurs sont cutanés, musculaires et articulaires.","s":2},{"q":"Que désigne le feedback dans le contrôle moteur ?","o":["L'information sur l'état du « système »","Les mécanismes anticipatoires activés avant le mouvement","La commande volontaire corticale","Le tonus musculaire de repos"],"r":0,"e":"Le feedback informe sur l'état du système ; le feedforward regroupe les mécanismes moteurs anticipatoires activés avant le mouvement pour le préparer.","s":2},{"q":"Quelles conséquences les altérations sensorielles entraînent-elles ?","o":["Elles gênent la sélection des inputs posturaux","Elles gênent l'adaptation à l'environnement","Elles faussent les modèles corporels internes","Elles abolissent la commande volontaire"],"r":[0,1,2],"e":"Trois conséquences : organisation/sélection des inputs posturaux, adaptation à l'environnement et développement des modèles corporels internes. Elles conditionnent l'organisation et la sélection des inputs pour le contrôle postural, et l'adaptation aux changements de la fonction.","s":2},{"q":"Pour quels types de sensation existe-t-il des aires sensorielles primaires distinctes ?","o":["Somatosensorielle","Visuelle","Vestibulaire","Auditive","Gustative"],"r":[0,1,2,3],"e":"Il existe une aire primaire pour chaque modalité : somatosensorielle, visuelle, vestibulaire et auditive, situées dans des régions différentes.","s":2},{"q":"D'où provient l'input analysé par le cortex d'association sensorielle ?","o":["Du thalamus","Des aires sensorielles primaires","Des motoneurones médullaires","Du cervelet uniquement"],"r":[0,1],"e":"Le cortex d'association analyse l'input venant du thalamus et des aires sensorielles primaires, et lui donne du sens.","s":2},{"q":"Quelles formes d'agnosie visuelle sont citées ?","o":["Agnosie pour les objets","Prosopagnosie","Agnosie chromatique","Astéréognosie"],"r":[0,1,2],"e":"L'agnosie visuelle recouvre les objets, les visages (prosopagnosie) et les couleurs (agnosie chromatique). L'astéréognosie est tactile.","s":2},{"q":"Que peut-on observer dans les cas graves de prosopagnosie ?","o":["Ne pas reconnaître son propre reflet","Perdre la vision centrale","Ne plus reconnaître les objets","Perdre la parole, en totalité"],"r":0,"e":"Dans les formes graves, la personne peut ne pas reconnaître son reflet ; elle identifie les autres surtout grâce aux indices fournis par l'environnement.","s":2},{"q":"Quelles capacités les aires pariéto-temporales assurent-elles ?","o":["Les capacités perceptives et constructives","L'organisation du schéma corporel","L'orientation égocentrique","La production du langage parlé"],"r":[0,1,2],"e":"Ce sont des aires de traitement spatial : capacités perceptives et constructives, schéma corporel et orientation égocentrique, essentielles au planning moteur et au contrôle postural.","s":2},{"q":"Quelle est la troisième étape du cercle vicieux sensori-moteur ?","o":["La diminution de l'activation corticale","Le non-usage moteur","La diminution du stimulus sensoriel","La réorganisation corticale"],"r":0,"e":"Non-usage moteur → diminution du stimulus sensoriel → diminution de l'activation corticale → réorganisation corticale.","s":2},{"q":"Qu'est-ce qui explique l'hypoesthésie dans le cercle vicieux sensori-moteur ?","o":["Les zones corticales servent à d'autres fonctions","Le système cherche à capter plus d'information","Les récepteurs cutanés disparaissent","Le thalamus est détruit, en partie"],"r":0,"e":"Hypoesthésie : les zones corticales sont réaffectées à d'autres fonctions. Hyperesthésie : le système cherche au contraire à capter davantage d'information.","s":2},{"q":"De quels récepteurs l'individu privé de mouvement reçoit-il peu ou pas d'information ?","o":["De la peau","Du muscle","Des articulations","De la rétine"],"r":[0,1,2],"e":"Peau, muscle et articulations : sans mouvement, leur information se tarit, la reconnaissance des stimuli diminue et l'aire corticale correspondante se réduit.","s":2},{"q":"Quelles implications pratiques découlent des altérations sensorielles ?","o":["Utiliser la main au quotidien","L'impliquer dans les positions et tâches","Désensibiliser en cas d'hyperesthésie","Un environnement multisensoriel","Immobiliser le membre atteint"],"r":[0,1,2,3],"e":"Usage de la main dans les AVQ, implication dans les positionnements et les tâches, désensibilisation en cas d'hyperesthésie et environnement multisensoriel qui stimule l'apprentissage. L'usage de la main se fait dans les AVQ quand c'est possible.","s":2},{"q":"Pourquoi la vision est-elle qualifiée de « parfois déstabilisante » dans la construction du schéma corporel ?","o":["Elle peut entrer en conflit avec les autres systèmes","Elle est toujours défaillante après une lésion","Elle supprime la proprioception, en la remplaçant","Elle n'intervient jamais dans l'équilibre"],"r":0,"e":"De multiples systèmes contribuent au schéma corporel, pas seulement le somatosensoriel : il faut considérer la vision, qui peut être déstabilisante, et le système vestibulaire (position de la tête et gravité). Elle contribue au schéma corporel au même titre que d'autres systèmes.","s":2},{"q":"Quels paramètres considérer lors d'une stimulation sensorielle ?","o":["La modalité et sa localisation","L'intensité du stimulus","La durée du stimulus","La sommation et l'intégration","La température de la peau"],"r":[0,1,2,3],"e":"Modalité et localisation, intensité, durée, avec l'importance de la sommation et de l'intégration.","s":2},{"q":"Où se situent les deux lieux de traitement de l'information sensorielle cités ?","o":["Le cortex, de façon consciente","Le cervelet, de façon inconsciente","La moelle, de façon réflexe","Le nerf périphérique, en chemin"],"r":[0,1],"e":"Deux lieux : le cortex (traitement conscient) et le cervelet (inconscient, non somatosensoriel). Le traitement cérébelleux n'est pas somatosensoriel.","s":2},{"q":"Quelle est la conséquence posturale du syndrome de Pusher ?","o":["Une perte du contrôle postural et de l'équilibre","Une hypotonie généralisée, des quatre membres","Une abolition des réflexes, ostéo-tendineux","Une hyperesthésie du côté sain, au moindre contact cutané"],"r":0,"e":"Le patient se pousse avec les membres sains vers le côté lésé, ce qui entraîne une perte du contrôle postural et de l'équilibre.","s":2},{"q":"Comment le patient avec syndrome de Pusher perçoit-il sa posture ?","o":["Il se sent droit mais penche vers le côté lésé","Il se sent penché alors qu'il se tient droit","Il ne perçoit plus du tout son propre corps","Il perçoit correctement son inclinaison réelle"],"r":0,"e":"Il existe une altération de la perception de la posture par rapport à la verticalité : le patient se sent droit alors qu'il est incliné vers le côté lésé.","s":2},{"q":"Sur quoi repose l'enjeu thérapeutique du syndrome de Pusher ?","o":["L'arbitrage entre indices visuels et proprioception","Le choix de l'antalgique, selon la douleur du patient","La durée d'immobilisation au lit, stricte","La chirurgie thalamique, stéréotaxique"],"r":0,"e":"Le système visuel restant intègre, on peut utiliser des stratégies visuelles pour organiser l'équilibre — d'où l'arbitrage entre indices visuels et stimulation proprioceptive.","s":2},{"q":"Pourquoi une lésion des aires sensorielles primaires interfère-t-elle sévèrement avec l'usage des sensations ?","o":["Elle diminue la discrimination d'intensité et de qualité","Elle abolit toute sensation, de façon complète","Elle détruit les récepteurs périphériques","Elle empêche la conduction, le long des nerfs périphériques"],"r":0,"e":"La sensation persiste, mais la discrimination de son intensité et de sa qualité est altérée — ce qui suffit à rendre les sensations inutilisables pour le contrôle moteur.","s":2},{"q":"Quel rôle le système vestibulaire joue-t-il dans le schéma corporel ?","o":["Il renseigne sur la position de la tête et la gravité","Il assure la discrimination tactile fine","Il commande la contraction musculaire","Il traite les couleurs et les formes, avec le cortex visuel"],"r":0,"e":"Le système vestibulaire contribue au schéma corporel en renseignant sur la position de la tête et la gravité.","s":2},{"q":"Qu'est-ce qui distingue l'hypoesthésie de l'hyperesthésie dans la réorganisation corticale post-lésionnelle ?","o":["Zones réaffectées pour l'une, recherche d'information pour l'autre","L'hypoesthésie touche la peau, l'hyperesthésie le muscle","L'hypoesthésie est précoce, l'hyperesthésie tardive","Aucune, les deux ayant exactement le même mécanisme de réorganisation"],"r":0,"e":"Les deux résultent du même cercle vicieux : soit les zones corticales sont utilisées pour d'autres fonctions (hypoesthésie), soit le système cherche à capter davantage d'information (hyperesthésie). L'hypoesthésie vient de la réaffectation des zones corticales, l'hyperesthésie de la recherche de plus d'information par le système.","s":2},{"q":"Quelle affirmation résume la place de la cognition en kinésithérapie neurologique ?","o":["Motricité et cognition sont indissociables","La cognition ne concerne que le neuropsychologue","La cognition n'influence pas le mouvement","Seule la motricité doit être évaluée"],"r":0,"e":"Les domaines cognitifs doivent être intégrés tant dans l'évaluation que dans l'intervention du kinésithérapeute.","s":3},{"q":"Dans quel hémisphère les fonctions linguistiques sont-elles latéralisées ?","o":["L'hémisphère gauche","L'hémisphère droit","Les deux de façon égale","Le cervelet"],"r":0,"e":"La latéralisation des fonctions linguistiques se fait dans l'hémisphère gauche.","s":3},{"q":"Quel élément du langage relève de l'hémisphère droit ?","o":["La prosodie, les métaphores et l'humour","La production grammaticale fine, et la syntaxe complexe","La conjugaison des verbes, irréguliers","La répétition de mots, isolés"],"r":0,"e":"L'hémisphère droit gère la prosodie linguistique et émotionnelle et intervient dans la reconnaissance des métaphores et de l'humour. La prosodie est linguistique et émotionnelle.","s":3},{"q":"Comment l'hémisphère droit lit-il un mot ?","o":["Globalement, en extrayant un sens parfois approximatif","Lettre par lettre, en déchiffrant chaque syllabe lentement","Il ne lit pas, il ne fait que voir le mot","Uniquement les verbes, pas les noms"],"r":0,"e":"Il comprend surtout les noms d'objets écrits ; la compréhension des verbes est plus rudimentaire. Il comprend surtout les noms d'objets écrits.","s":3},{"q":"Combien de types d'aphasie sont bien décrits ?","o":["8","3","5","12"],"r":0,"e":"Broca, Wernicke, globale, conduction, anomique, transcorticale sensorielle, transcorticale motrice, transcorticale mixte.","s":3},{"q":"Quelle est la caractéristique de l'aphasie de Broca ?","o":["Discours non fluent avec compréhension maintenue","Discours fluent avec compréhension affectée","Compréhension et discours normaux","Absence totale de langage écrit"],"r":0,"e":"Broca : discours non fluent, altération de la répétition et de la dénomination, compréhension maintenue.","s":3},{"q":"Quelle est la caractéristique de l'aphasie de Wernicke ?","o":["Un discours fluent, une compréhension altérée","Un discours non fluent, compréhension gardée","Une absence totale de discours, mutisme","Une répétition intacte, sans autre trouble"],"r":0,"e":"Wernicke : discours fluent, altération de la répétition et de la dénomination, compréhension affectée.","s":3},{"q":"À quoi correspond l'aphasie globale ?","o":["Des lésions étendues à tout l'hémisphère gauche","Une lésion isolée de l'aire de Broca, dans le lobe frontal","Une lésion étendue de l'hémisphère droit","Une lésion cérébelleuse, bilatérale"],"r":0,"e":"L'aphasie globale résulte de lésions étendues dans tout l'hémisphère gauche.","s":3},{"q":"Quelles sont les quatre étapes de la mémoire ?","o":["Acquisition, codage, stockage, récupération","Perception, attention, décision, action","Encodage, tri, oubli, rappel","Alerte, orientation, contrôle, exécution"],"r":0,"e":"Acquisition (captation), codage (organisation/traitement), stockage, récupération (spontanée, indicée, reconnaissance).","s":3},{"q":"À qui doit-on le modèle modal de la mémoire (1968) ?","o":["Atkinson et Shiffrin","Posner et Petersen","Bisiach et Luzzatti","Logan et Gordon"],"r":0,"e":"Le modèle modal est celui d'Atkinson et Shiffrin (1968).","s":3},{"q":"Qu'est-ce que la mémoire procédurale ?","o":["L'information sur comment on fait les choses","L'information factuelle sur les choses","La connaissance générale du monde","Le rappel d'événements datés"],"r":0,"e":"Mémoire non déclarative/implicite ou procédurale : faire du vélo, se brosser les dents, ouvrir des boîtes.","s":3},{"q":"Qu'est-ce que la mémoire sémantique ?","o":["Les concepts, les faits et les règles du monde","Les souvenirs personnels, datés et situés","Les gestes appris, comme faire du vélo","Les informations tenues en tête, pendant le raisonnement"],"r":0,"e":"La mémoire sémantique regroupe les connaissances qui nous permettent de nous relier fonctionnellement au monde. C'est la connaissance générale du monde.","s":3},{"q":"Qu'est-ce que la mémoire épisodique ?","o":["Le rappel d'événements passés, situés dans le temps","La connaissance des règles de grammaire","La capacité à refaire du vélo, même après des années","La coordination des informations en cours"],"r":0,"e":"Elle est dépendante de nos expériences et intègre les aspects spatio-temporels. Elle intègre les aspects spatio-temporels.","s":3},{"q":"Qu'est-ce que la mémoire de travail ?","o":["Une centrale qui coordonne l'information en cours","Un stockage à très long terme, illimité","La mémoire des gestes automatiques, appris dans l'enfance","La mémoire des visages, familiers"],"r":0,"e":"C'est la composante de la mémoire à court terme décrite dans le cours. Cette centrale exécutive sert au raisonnement et à la décision.","s":3},{"q":"Comment se caractérise l'amnésie rétrograde ?","o":["Un trouble d'évocation des souvenirs d'avant l'événement","Un trouble de rétention des faits survenus après la lésion","Une perte de la mémoire implicite, des gestes et des habitudes","Une baisse globale du niveau d'intelligence"],"r":0,"e":"L'amnésie rétrograde est un trouble d'évocation, qui peut obéir à la loi de Ribot.","s":3},{"q":"Que dit la loi de Ribot ?","o":["Les souvenirs récents se perdent avant les anciens","Les souvenirs récents sont toujours conservés","La mémoire implicite est perdue en premier","L'amnésie touche d'abord l'attention, puis le langage"],"r":0,"e":"La loi de Ribot s'applique à l'amnésie rétrograde. La perte survient dans l'ordre inverse de l'acquisition.","s":3},{"q":"Comment met-on en évidence une amnésie antérograde ?","o":["Par des faits récents et un apprentissage nouveau","Par les souvenirs d'enfance, lointains","Par la mesure du quotient intellectuel, sur une échelle","Par la mémoire procédurale, des gestes"],"r":0,"e":"C'est un trouble de rétention : « qu'avez-vous mangé au petit déjeuner ? » et apprentissage de matériel verbal ou visuel nouveau. Exemple : « qu'avez-vous mangé au petit déjeuner ? » ; le matériel nouveau est verbal ou visuel.","s":3},{"q":"Qu'est-ce qui reste normal dans l'amnésie ?","o":["L'intelligence, l'attention et la mémoire implicite","Le langage seul, oral et écrit, dans tous ses aspects","La motricité seule, fine et globale, des membres","Rien, toutes les fonctions sont touchées"],"r":0,"e":"Niveau d'intelligence normal, niveaux d'attention normaux, mémoire implicite sans altérations.","s":3},{"q":"Quelle est la différence entre orientation et navigation spatiales ?","o":["La navigation est plus large, d'un lieu à un autre","L'orientation est plus large que la navigation","Ce sont deux synonymes, sans différence","La navigation ne concerne que la vision"],"r":0,"e":"L'orientation relie corps et espace ; la navigation implique changements de direction et prises de décision menant à une destination. Elle implique changements de direction et prises de décision ; l'orientation relie le corps à l'espace.","s":3},{"q":"Comment appelle-t-on les altérations de l'orientation ?","o":["La désorientation topographique","L'anosognosie des troubles","L'apraxie idéatoire, gestuelle","La somatoparaphrénie, du corps propre"],"r":0,"e":"Elles sont très hétérogènes : égocentriques, allocentriques ou de reconnaissance de points de repère.","s":3},{"q":"Quelle structure a le rôle principal dans le contrôle des fonctions exécutives ?","o":["Le lobe frontal","L'hippocampe","Le cervelet","Le thalamus"],"r":0,"e":"Le lobe frontal, région privilégiée qui communique avec tout l'encéphale — mais il ne fonctionne pas seul.","s":3},{"q":"Avec quelles structures les lobes frontaux interagissent-ils pour les fonctions exécutives ?","o":["L'hippocampe, le cervelet, les noyaux gris centraux","Le thalamus seul, par ses noyaux antérieurs","La moelle épinière seule, au niveau cervical","L'amygdale seule, dans le lobe temporal médial"],"r":0,"e":"Chacune au service d'aspects spécifiques des fonctions exécutives.","s":3},{"q":"Quelles structures constituent les centres émotionnels ?","o":["L'amygdale et le cortex préfrontal","Le cervelet et le tronc cérébral, en arrière","La moelle épinière et le thalamus","Les noyaux gris centraux, seuls"],"r":0,"e":"Amygdale pour le limbique, cortex préfrontal pour le néocortical. L'amygdale appartient au système limbique, le cortex préfrontal aux centres néocorticaux.","s":3},{"q":"Quels sont les trois réseaux attentionnels ?","o":["État d'alerte, attention orientée, contrôle exécutif","Attention sélective, divisée et soutenue, alternée","Réseaux bottom-up, top-down et latéral","Attention visuelle, auditive et tactile"],"r":0,"e":"Ce sont les trois réseaux cités dans le cours.","s":3},{"q":"Que constate-t-on lorsqu'on demande une attention divisée sur plusieurs tâches ?","o":["Une baisse drastique de la performance","Une amélioration de la performance","Aucun effet sur la performance","Un gain, chez le sujet jeune seulement"],"r":0,"e":"Logan & Gordon (2001) : la capacité à faire coexister un focus sur plus d'une chose est discutable et la performance chute. Faire coexister plusieurs focus reste discutable (Logan & Gordon, 2001).","s":3},{"q":"Comment définit-on l'héminégligence ?","o":["Une moindre détection des stimuli controlatéraux","Une paralysie d'un hémicorps, controlatérale","Une perte de la vision, d'un seul côté","Une perte de la sensibilité tactile, sur tout l'hémicorps"],"r":0,"e":"Définition de Mesulam (1999) ; la lésion est normalement de l'hémisphère droit. Elle survient même sans déficit sensorimoteur.","s":3},{"q":"Quel est un exemple d'héminégligence personnelle ?","o":["Se raser à moitié ou enfiler la moitié d'une veste","Ne manger que d'une moitié de l'assiette","Ignorer l'entrée d'une personne dans la salle","Négliger le côté gauche d'un objet dessiné"],"r":0,"e":"L'héminégligence personnelle concerne le corps ; la péripersonnelle le péri-espace ; l'extrapersonnelle l'espace éloigné.","s":3},{"q":"Qu'est-ce que l'héminégligence représentationnelle ?","o":["Un côté de l'espace négligé, même imaginé","Une négligence du corps, de l'hémicorps","Une négligence de l'assiette, à table","Une extinction tactile, aux deux mains"],"r":0,"e":"Décrite par Bisiach & Luzzatti (1979). La perte attentionnelle touche un côté de l'espace même simplement représenté mentalement.","s":3},{"q":"Qu'est-ce que l'anosognosie ?","o":["L'incapacité à reconnaître ses propres déficits","La négation de la propriété d'un membre","L'incapacité à reconnaître les objets","La perte de la mémoire récente, immédiate"],"r":0,"e":"La somatoparaphrénie, elle, est la négation de la propriété d'un membre avec confabulations élaborées.","s":3},{"q":"Quelle est la différence entre apraxie idéatoire et idéomotrice ?","o":["L'idéatoire perd l'idée, l'idéomotrice l'exécution sur demande","L'idéomotrice empêche toute idée, l'idéatoire toute exécution","L'idéatoire ne touche que la main, l'idéomotrice le pied et la jambe","Aucune différence, les deux termes désignant le même trouble"],"r":0,"e":"L'apraxie idéatoire est une perte de connaissance conceptuelle ; dans l'idéomotrice, le patient peut utiliser l'objet en contexte mais pas sur demande. Dans l'idéomotrice, l'objet est utilisé en contexte mais pas sur demande.","s":3},{"q":"Quels domaines cognitifs doivent être intégrés à l'évaluation et à l'intervention du kinésithérapeute ?","o":["Émotions, mémoire et orientation","Langage et fonctions exécutives","Motivation et attention","Cognition motrice","Uniquement la force musculaire"],"r":[0,1,2,3],"e":"Émotions, mémoire, orientation, langage, fonctions exécutives, motivation, attention et cognition motrice : il est impossible de dissocier habiletés motrices et cognitives.","s":3},{"q":"Quels types d'aphasie sont bien décrits, au-delà de Broca, Wernicke et globale ?","o":["De conduction","Anomique","Transcorticale sensorielle","Transcorticales motrice et mixte","Cérébelleuse"],"r":[0,1,2,3],"e":"Huit types au total : Broca, Wernicke, globale, de conduction, anomique, transcorticale sensorielle, transcorticale motrice et transcorticale mixte.","s":3},{"q":"Qu'ont en commun les aphasies de Broca et de Wernicke ?","o":["Une répétition et une dénomination altérées","Un discours non fluent, laborieux","Une compréhension maintenue, intacte","Des lésions étendues à tout l'hémisphère gauche"],"r":0,"e":"Les deux altèrent répétition et dénomination. Broca : discours non fluent, compréhension maintenue. Wernicke : discours fluent, compréhension affectée.","s":3},{"q":"Quelles sont les trois modalités de récupération en mémoire ?","o":["Spontanée","Indicée","Par reconnaissance","Par répétition"],"r":[0,1,2],"e":"La récupération peut être spontanée, indicée ou par reconnaissance — quatrième étape après acquisition, codage et stockage.","s":3},{"q":"Quels exemples relèvent de la mémoire déclarative ?","o":["La capitale de la France","Son premier anniversaire","Le goût du café","Savoir faire du vélo"],"r":[0,1,2],"e":"La mémoire déclarative porte sur les choses (faits, événements, qualités sensorielles mémorisées). Faire du vélo relève de la mémoire procédurale, non déclarative. La texture du ciment en est un autre exemple.","s":3},{"q":"Pourquoi la mémoire est-elle nécessaire aux autres domaines cognitifs ?","o":["Elle sert à tous les autres domaines, comme le langage","Elle remplace l'attention, quand celle-ci fait défaut","Elle est localisée dans le seul lobe frontal","Elle contrôle toute la motricité, volontaire et automatique"],"r":0,"e":"La mémoire est immergée dans tous les domaines cognitifs : le langage, par exemple, nécessite de stocker le sens des mots. Le langage exige par exemple de stocker le sens des mots.","s":3},{"q":"Que peuvent favoriser les altérations sévères de la mémoire ?","o":["Des épisodes de confabulations","Une hyperréflexie, vive","Une spasticité, des membres","Une héminégligence, gauche"],"r":0,"e":"Les altérations peuvent être légères et impacter toutes les performances, ou évidentes en cas d'amnésie, et favoriser des épisodes de confabulations.","s":3},{"q":"Quels sont les deux cadres de référence de l'orientation spatiale ?","o":["Égocentrique","Allocentrique","Périphérique","Vestibulaire"],"r":[0,1],"e":"Orientation égocentrique et orientation allocentrique sont les deux cadres de référence.","s":3},{"q":"À quelles autres altérations la désorientation topographique est-elle fréquemment associée ?","o":["Aux habiletés constructives","Au schéma corporel","À la spasticité des membres","Au clonus de cheville"],"r":[0,1],"e":"Elle s'associe souvent à d'autres altérations du traitement spatial : habiletés constructives et schéma corporel.","s":3},{"q":"Que permettent les fonctions exécutives ?","o":["Le contrôle top-down des actions","Un plan d'action fondé sur l'expérience","Des actions flexibles et adaptatives","La régulation du tonus de repos"],"r":[0,1,2],"e":"Contrôle top-down, formulation d'un plan d'action à partir des expériences et des exigences de l'environnement, et actions flexibles et adaptatives. Le plan d'action tient compte des demandes de l'environnement ; les actions sont parfois contrôlées à chaque étape.","s":3},{"q":"Quelles sont les fonctions des émotions ?","o":["Préparation à l'action","Préparation de la conduite","Apprentissage émotionnel","Régulation de l'interaction","Commande motrice volontaire"],"r":[0,1,2,3],"e":"Les quatre fonctions sont citées, les émotions ayant un rôle actif dans la régulation interne et constante du corps. L'émotion catalyse le lien entre le milieu et la conduite ; l'apprentissage émotionnel sert aux situations futures.","s":3},{"q":"Quel est l'enjeu clinique lié à la motivation ?","o":["Arbitrer entre récompense et banalisation","Choisir le renforcement négatif, par principe","Supprimer toute récompense, d'emblée","Donner seulement des consignes verbales"],"r":0,"e":"L'impulsion motivationnelle se module selon les états internes et l'environnement ; l'enjeu clinique est l'arbitrage entre récompense et banalisation de la récompense.","s":3},{"q":"De quelles influences dépend le fonctionnement de l'attention (Posner & Petersen, 1990) ?","o":["D'influences externes « bottom-up »","D'influences internes « top-down »","De la seule volonté consciente du sujet","Du tonus musculaire de repos"],"r":[0,1],"e":"L'attention dépend d'influences externes bottom-up et internes top-down. Elle résulte de l'interface entre l'information captée et le choix limité de ce à quoi on est attentif.","s":3},{"q":"Qu'est-ce que l'attention sélective ?","o":["Retenir certains stimuli, malgré les distracteurs","Alterner entre plusieurs tâches en compétition","Maintenir un état d'alerte prolongé, sur des heures","Diriger le regard vers un objet précis"],"r":0,"e":"L'attention sélective permet la détection préférentielle, l'identification et la reconnaissance de certains stimuli parmi de multiples sources, malgré les distracteurs.","s":3},{"q":"Quel test classique explore l'héminégligence ?","o":["L'Albert cancellation test","Le test de Phalen modifié","L'échelle de Borg révisée","Le test d'Adams, en flexion"],"r":0,"e":"L'Albert cancellation test est le test classique de l'héminégligence.","s":3},{"q":"Quelle est la différence entre héminégligence égocentrique et allocentrique sur l'axe horizontal ?","o":["Égocentrique : à gauche de soi ; allocentrique : à gauche des objets","Égocentrique : à gauche des objets ; allocentrique : à gauche de soi","Égocentrique : en haut ; allocentrique : en bas, sur l'axe vertical","Les deux sont identiques : tout ce qui est à gauche est ignoré"],"r":0,"e":"Égocentrique : diminution de l'attention à tout ce qui se trouve à gauche de soi. Allocentrique : négligence du côté gauche de chaque objet, indépendamment de sa localisation. L'allocentrique concerne le côté gauche de chaque objet, quelle que soit sa position.","s":3},{"q":"Quel exemple illustre une héminégligence péripersonnelle ?","o":["Ne manger que d'une moitié de l'assiette","Enfiler la moitié d'une veste","Ignorer l'entrée d'une personne dans la salle","Ne pas reconnaître son reflet"],"r":0,"e":"Péripersonnelle : négligence du péri-espace, comme ne manger que d'une moitié de l'assiette. Personnelle : se raser à moitié. Extrapersonnelle : ignorer une personne qui entre.","s":3},{"q":"Qu'est-ce que le phénomène d'extinction ?","o":["Rater le stimulus controlésionnel s'il y en a deux","La disparition progressive de l'héminégligence","L'abolition d'un réflexe, cutané ou tendineux","La perte totale de la sensibilité, d'un côté"],"r":0,"e":"L'extinction est l'échec à rapporter un stimulus controlésionnel quand un stimulus ipsilésionnel concurrent est présenté brièvement en même temps. L'autre stimulus, ipsilésionnel, est présenté brièvement en même temps.","s":3},{"q":"Qu'est-ce que la somatoparaphrénie ?","o":["Nier qu'un membre vous appartient, avec des confabulations","Ne pas reconnaître ses propres déficits, ni leur gravité réelle","Ne pas reconnaître les objets, par le toucher","Perdre le langage, oral et écrit, d'un coup"],"r":0,"e":"La somatoparaphrénie est rare : le sujet nie la propriété d'un membre ou d'un hémicorps et produit des confabulations élaborées, même face à une preuve indéniable. L'anosognosie, elle, est l'incapacité à reconnaître ses déficits. C'est une illusion rare, qui peut toucher tout un côté du corps.","s":3},{"q":"Quelles sont les quatre phases de la cognition motrice ?","o":["Phase idéative","Planification motrice","Phase d'exécution","Feedback et adaptation","Consolidation mnésique"],"r":[0,1,2,3],"e":"Idéative, planification motrice, exécution, puis feedback et adaptation. L'idéation conceptualise la tâche, la planification organise la séquence motrice, le feedback prépare les actions futures.","s":3},{"q":"Quel est le rapport entre input et output du cervelet ?","o":["Il a 40 fois plus d'input que d'output","Il a autant d'input que d'output","Il a 40 fois plus d'output que d'input","Il n'a pas d'afférences"],"r":0,"e":"Le cervelet reçoit 40 fois plus d'input (feedback interne et externe) que d'output.","s":4},{"q":"Par quelle structure le cervelet est-il connecté au tronc cérébral ?","o":["Les pédoncules cérébelleux","Le corps calleux","La capsule interne","Les noyaux vestibulaires"],"r":0,"e":"Le cervelet est situé en arrière du tronc cérébral et y est connecté par les pédoncules cérébelleux.","s":4},{"q":"Quel module cérébelleux assure la planification des mouvements complexes et rapides ?","o":["Le cérébrocervelet","Le spinocervelet","Le vestibulocervelet","Le noyau fastigial"],"r":0,"e":"Le cérébrocervelet agit surtout sur la musculature distale, avec output par le noyau denté.","s":4},{"q":"Quel est l'output principal du cérébrocervelet ?","o":["Le noyau denté","Le noyau fastigial","Les noyaux vestibulaires","Le noyau globuleux"],"r":0,"e":"Noyau denté → thalamus → cortex moteur, et noyau rouge parvocellulaire → thalamus → cortex moteur.","s":4},{"q":"Quel module cérébelleux gère la posture et le tonus ?","o":["Le spinocervelet","Le cérébrocervelet","Le vestibulocervelet","Le lobe flocculo-nodulaire seul"],"r":0,"e":"Le spinocervelet agit surtout sur la musculature proximale, avec output par les noyaux globuleux, emboliforme et fastigial.","s":4},{"q":"Quelle portion du noyau rouge est reliée au spinocervelet ?","o":["La portion magnocellulaire","La portion parvocellulaire","Aucune","Les deux de façon égale"],"r":0,"e":"Spinocervelet → noyau rouge magnocellulaire → voie rubrospinale. Cérébrocervelet → portion parvocellulaire.","s":4},{"q":"Quel module cérébelleux gère l'équilibre et la stabilité oculaire ?","o":["Le vestibulocervelet","Le spinocervelet","Le cérébrocervelet","Le noyau denté"],"r":0,"e":"Output par les noyaux vestibulaires vers la voie vestibulospinale et les noyaux oculomoteurs.","s":4},{"q":"Quel syndrome cérébelleux se caractérise par un déséquilibre axial statique et un nystagmus ?","o":["Le syndrome flocculo-nodulaire","Le syndrome hémisphérique","Le syndrome du lobe antérieur","Le syndrome pancérébelleux"],"r":0,"e":"Syndrome flocculo-nodulaire (vermien postérieur) : déséquilibre axial, oscillations du tronc et de la tête, altérations du RVO, nystagmus.","s":4},{"q":"Quel syndrome cérébelleux donne une ataxie homolatérale à prédominance distale ?","o":["Le syndrome hémisphérique","Le syndrome flocculo-nodulaire","Le syndrome du lobe antérieur","Le syndrome pancérébelleux"],"r":0,"e":"Syndrome hémisphérique : ataxie homolatérale distale et des mouvements fins, retard à l'initiation, dysarthrie.","s":4},{"q":"Quel syndrome cérébelleux affecte principalement les membres inférieurs avec une base très élargie ?","o":["Le syndrome du lobe antérieur","Le syndrome hémisphérique","Le syndrome flocculo-nodulaire","Le syndrome pancérébelleux"],"r":0,"e":"Syndrome du lobe antérieur (vermien antérieur) : difficulté des corrections et ajustements posturaux pendant le mouvement.","s":4},{"q":"De quoi est composé le syndrome cérébelleux ?","o":["D'ataxie et d'hypotonie","De spasticité et d'hyperréflexie","De parésie et d'atrophie","De rigidité et de bradykinésie"],"r":0,"e":"Ataxie + hypotonie, avec des séquelles homolatérales à l'hémicervelet lésé.","s":4},{"q":"Les séquelles d'une lésion cérébelleuse sont :","o":["Homolatérales à l'hémicervelet lésé","Controlatérales à la lésion","Toujours bilatérales, symétriques","Sans latéralisation, diffuses à tout le corps"],"r":0,"e":"Les séquelles sont homolatérales à l'hémicervelet lésé.","s":4},{"q":"Comment s'explique l'hypotonie cérébelleuse ?","o":["Moins d'output des noyaux, donc moins de facilitation","Une lésion du motoneurone inférieur, périphérique","Une atrophie musculaire, par non-usage prolongé du membre","Une rétraction tendineuse, fixée et ancienne"],"r":0,"e":"Elle aboutit à un tonus insuffisant et à une difficulté à maintenir la posture ; elle est plus évidente dans les lésions aiguës. Il s'agit des noyaux cérébelleux ; la facilitation porte sur le cortex moteur et le tronc.","s":4},{"q":"Qu'est-ce que la dysmétrie ?","o":["Une erreur de distance au cours du mouvement","Une incapacité à alterner rapidement les mouvements","Une difficulté d'articulation de la parole","Un retard au début de l'action volontaire"],"r":0,"e":"La dysmétrie est une erreur d'estimation de la distance.","s":4},{"q":"Quand survient le tremblement intentionnel ?","o":["Pendant le mouvement, surtout près de la cible","Au repos complet, le membre relâché sur un appui","Pendant le sommeil, seulement","En position debout, seulement"],"r":0,"e":"C'est ce qui le distingue du tremblement de repos parkinsonien.","s":4},{"q":"Qu'est-ce que l'asynergie ?","o":["Ne plus coordonner les groupes musculaires","Une erreur de distance, au mouvement","Un retard de chronométrage, au départ","Une incapacité aux mouvements alternés et rapides"],"r":0,"e":"Elle aboutit à des actions motrices segmentées, désorganisées et inefficaces. Le mouvement n'est plus harmonieux.","s":4},{"q":"Qu'est-ce que la dyschronométrie ?","o":["Un mauvais timing d'activation et d'inhibition","Une erreur d'amplitude, en fin de mouvement","Un tremblement de repos, distal et lent","Une hypotonie, du côté de la lésion"],"r":0,"e":"Elle aboutit à des retards au début ou à la fin de l'action. L'activation et l'inhibition des muscles sont mal chronométrées pendant le mouvement.","s":4},{"q":"Qu'est-ce que la dysdiadococinésie ?","o":["Ne pas réussir les mouvements rapides et alternés","Une difficulté à articuler les mots, à parler","Une erreur de distance, en approchant la cible","Une oscillation posturale, en station debout"],"r":0,"e":"Aussi appelée adiadococinésie.","s":4},{"q":"Comment se manifeste la dysarthrie cérébelleuse ?","o":["Une parole traînante, entrecoupée, peu claire","Une aphasie de compréhension, sévère","Une perte totale de la voix, par atteinte laryngée","Un bégaiement isolé, au début des mots"],"r":0,"e":"Elle est causée par une altération de la coordination des muscles de la phonation.","s":4},{"q":"Quelle altération oculomotrice appartient au syndrome cérébelleux ?","o":["Des saccades et une poursuite lente altérées","Une cécité corticale, bilatérale","Une héminégligence visuelle, gauche","Une agnosie visuelle, des objets et des formes"],"r":0,"e":"On observe aussi un nystagmus, une altération du RVO et plus rarement une diplopie.","s":4},{"q":"Que teste la rotation alternée et successive du tronc ?","o":["La passivité du membre supérieur, qui oscille trop","La force des muscles du tronc, en rotation contre résistance","L'amplitude articulaire lombaire, en rotation","La sensibilité proprioceptive, du bras"],"r":0,"e":"Le membre supérieur lésé présente des oscillations exagérées. Les oscillations exagérées touchent le côté lésé.","s":4},{"q":"Que montre l'épreuve des bras tendus dans une lésion cérébelleuse ?","o":["La main du côté atteint tombe en plus grande flexion","Les deux mains tombent de la même façon, symétrique","La main atteinte reste rigide, en extension","Aucun signe n'apparaît, d'un côté comme de l'autre"],"r":0,"e":"On demande de maintenir les membres supérieurs verticaux en laissant les mains tomber librement.","s":4},{"q":"Quel est le résultat du test de Stewart-Holmes chez un sujet sain ?","o":["La flexion s'arrête à quelques centimètres et revient","Le mouvement continue, sans pouvoir s'arrêter","Le bras tombe complètement, sans retenue","Aucun mouvement ne se produit, le bras reste figé"],"r":0,"e":"Chez un patient cérébelleux, le mouvement continue par incapacité à l'arrêter efficacement. Le coude revient à sa position initiale.","s":4},{"q":"Quel test consiste à faire glisser le talon le long du tibia opposé ?","o":["Le test talon-genou","Le test doigt-nez","Le test index-index","Le wrist tapping"],"r":0,"e":"C'est un test classique de coordination du membre inférieur.","s":4},{"q":"Que révèle la diadococinésie passive du côté lésé ?","o":["Les mouvements sont plus faciles","Les mouvements sont bloqués","Aucune différence avec le côté sain","Une douleur intense, au poignet"],"r":0,"e":"On exécute des mouvements passifs alternés de pronation-supination : ils sont plus facilités du côté lésé. Les mouvements passifs alternés de pronation-supination sont plus facilités du côté lésé.","s":4},{"q":"Pourquoi n'attend-on pas de faiblesse neurale dans une lésion cérébelleuse ?","o":["Il n'a pas d'efférences directes vers la périphérie","Il ne contrôle que la sensibilité, et jamais la motricité","La faiblesse est toujours compensée","Il est bilatéral, donc toujours protégé"],"r":0,"e":"Sans efférences directes vers la périphérie, on n'attend ni faiblesse musculaire neurale ni signes d'hyperactivité.","s":4},{"q":"Quel principe d'intervention est spécifique de la rééducation cérébelleuse ?","o":["Laisser l'erreur se produire, pour qu'elle se corrige","Éviter toute erreur d'exécution, dès le début","Répéter un mouvement unique et stéréotypé","Immobiliser le tronc, pour mieux stabiliser les membres"],"r":0,"e":"Le cervelet a un rôle central dans l'apprentissage moteur et la correction du mouvement.","s":4},{"q":"Quelle stratégie compensatoire est fréquente dans les lésions cérébelleuses ?","o":["Une fixation des structures du cou et du tronc","Une hyperextension des genoux uniquement","Une flexion cervicale permanente","Une rotation de bassin"],"r":0,"e":"Le cervelet influence la musculature axiale : la fixation compense le manque de stabilité — d'où le débat stabilité vs fixation.","s":4},{"q":"Quels sont les quatre axes de l'intervention cérébelleuse ?","o":["Apprentissage, coordination, contrôle postural, cognition","Force, souplesse, endurance et vitesse d'exécution","Mobilité, flexibilité, force musculaire et pliométrie","Sensibilité, motricité, réflexes, tonus musculaire de repos"],"r":0,"e":"Ces quatre axes sont articulés autour de l'information sensorielle. L'apprentissage et la coordination sont moteurs ; le tout s'articule autour de l'information sensorielle.","s":4},{"q":"Quelle caractéristique définit l'ataxie statique ?","o":["Une difficulté à tenir la posture, surtout debout","Une difficulté à saisir un objet, en le visant de loin","Un tremblement à l'approche de la cible","Une dysarthrie, avec une parole lente"],"r":0,"e":"L'ataxie statique donne une base élargie et des tremblements lors du maintien d'une position ; la cinétique concerne les mouvements volontaires. L'équilibre est perturbé, avec une base élargie.","s":4},{"q":"Où se situe le cervelet et comment se connecte-t-il au reste du système nerveux ?","o":["En arrière du tronc cérébral, par les pédoncules","En avant du tronc cérébral, relié par le thalamus","Au-dessus du cortex, relié par le corps calleux","Dans la moelle épinière, au niveau cervical"],"r":0,"e":"Le cervelet est situé en arrière du tronc cérébral et lui est connecté par les pédoncules cérébelleux.","s":4},{"q":"Quelle musculature le vestibulocervelet contrôle-t-il ?","o":["La musculature axiale","La musculature distale","La musculature proximale","Les muscles de la phonation"],"r":0,"e":"Vestibulocervelet : musculature axiale, pour l'équilibre et la stabilité oculaire. Le spinocervelet gère la proximale, le cérébrocervelet la distale.","s":4},{"q":"Quels sont les outputs du vestibulocervelet ?","o":["Noyaux vestibulaires → voie vestibulospinale","Noyaux vestibulaires → noyaux oculomoteurs","Noyau denté → thalamus → cortex prémoteur","Noyau fastigial → cortex moteur primaire"],"r":[0,1],"e":"Le vestibulocervelet projette vers les noyaux vestibulaires, puis vers la voie vestibulospinale et vers les noyaux oculomoteurs.","s":4},{"q":"Quels noyaux constituent l'output du spinocervelet ?","o":["Noyaux globuleux et emboliforme","Noyau rouge magnocellulaire","Noyau fastigial","Noyau denté, latéral"],"r":[0,1,2],"e":"Spinocervelet : noyaux globuleux et emboliforme vers le thalamus, noyau rouge magnocellulaire vers la voie rubrospinale, formation réticulée vers la voie réticulo-spinale, et noyau fastigial vers les noyaux vestibulaires. Le noyau denté appartient au cérébrocervelet.","s":4},{"q":"Quel syndrome cérébelleux associe dysfonctions bilatérales, marche très altérée et dysarthrie ?","o":["Le syndrome pancérébelleux","Le syndrome hémisphérique","Le syndrome flocculo-nodulaire","Le syndrome du lobe antérieur"],"r":0,"e":"Le syndrome pancérébelleux associe dysfonctions bilatérales, grandes altérations du tronc et des membres, marche très altérée, dysarthrie et altération des mouvements oculaires.","s":4},{"q":"Quelles caractéristiques appartiennent au syndrome hémisphérique ?","o":["Ataxie homolatérale distale, des gestes fins","Retard à l'initiation du mouvement","Dysarthrie, parole scandée","Nystagmus et réflexe vestibulaire altéré"],"r":[0,1,2],"e":"Ataxie homolatérale distale, retard d'initiation et dysarthrie. Le nystagmus et l'atteinte du réflexe vestibulo-oculomoteur caractérisent le syndrome flocculo-nodulaire.","s":4},{"q":"Quels aspects de la coordination sont altérés dans le syndrome cérébelleux ?","o":["Le séquençage","L'intensité","La durée","Le rythme","La force pure"],"r":[0,1,2,3],"e":"Les altérations de coordination portent sur le séquençage, l'intensité, la durée et le rythme.","s":4},{"q":"Comment se manifeste l'ataxie cinétique ?","o":["Difficulté à réaliser des mouvements précis comme saisir un objet ou écrire","Tremblements pendant l'exécution d'un mouvement","Erreurs dans le contrôle de l'amplitude","Base de sustentation élargie en position debout"],"r":[0,1,2],"e":"L'ataxie cinétique concerne les mouvements volontaires : imprécision, tremblement d'exécution, erreurs d'amplitude. La base élargie relève de l'ataxie statique.","s":4},{"q":"Quand l'hypotonie cérébelleuse est-elle la plus évidente ?","o":["Dans les lésions aiguës","Dans les lésions chroniques","Pendant le sommeil","À l'effort"],"r":0,"e":"L'hypotonie centrale est plus évidente dans les lésions aiguës ; elle résulte de la diminution de l'output des noyaux cérébelleux.","s":4},{"q":"Quelles altérations oculomotrices accompagnent le syndrome cérébelleux ?","o":["Saccades et poursuite lente altérées","Un nystagmus","Réflexe vestibulo-oculaire mal contrôlé","Diplopie, convergence altérée","Une cécité corticale bilatérale"],"r":[0,1,2,3],"e":"Les quatre altérations sont citées, la diplopie et les troubles de convergence étant moins fréquents. La diplopie et les troubles de convergence sont moins fréquents.","s":4},{"q":"Que montre le shaking passif de la main ou du pied en cas de lésion cérébelleuse ?","o":["Des amplitudes exagérées du côté lésé","Une résistance accrue du côté lésé","Une absence totale de mouvement","Un tremblement à 3-5 Hz"],"r":0,"e":"Contact manuel distal, mouvements vigoureux passifs en laissant osciller librement : les amplitudes sont exagérées du côté lésé, reflet de l'hypotonie.","s":4},{"q":"Que montre le wrist tapping avec bras tendus du côté affecté ?","o":["Des oscillations exagérées, jusqu'à l'arrêt","Une chute immédiate du membre, sans freinage","Une rigidité en roue dentée, au poignet","Une absence de réponse, le membre restant figé"],"r":0,"e":"Épaules à 90° de flexion, percussion rapide sur les poignets : le membre affecté présente des oscillations exagérées jusqu'à l'arrêt.","s":4},{"q":"Quel est le résultat du test de Stewart-Holmes en cas de lésion cérébelleuse ?","o":["Le mouvement continue : pas de freinage","La flexion s'arrête : retour au départ","Aucun mouvement : le bras reste figé","Le membre tremble : oscillations à 3-5 Hz"],"r":0,"e":"Chez le sujet sain, la flexion du coude s'interrompt à quelques centimètres et revient. En cas de lésion cérébelleuse, le mouvement continue faute de freinage.","s":4},{"q":"Quels tests explorent la coordination des membres supérieurs en pathologie cérébelleuse ?","o":["Doigt-nez","Index-index","Opposition des doigts","Pronation-supination","Talon-genou"],"r":[0,1,2,3],"e":"Doigt-nez, index-index, opposition des doigts et pronation/supination alternées explorent le membre supérieur. Talon-genou explore le membre inférieur. L'opposition des doigts se fait en « pianotant ».","s":4},{"q":"En quoi consiste l'épreuve index-index ?","o":["Toucher l'index de l'examinateur, qui peut bouger","Toucher son nez avec l'index, yeux fermés","Opposer rapidement le pouce à chacun des autres doigts","Glisser le talon le long du tibia opposé"],"r":0,"e":"Index-index : le patient touche l'index de l'examinateur, placé devant lui et dont la position peut changer — ce qui teste l'adaptation à une cible mobile. L'index de l'examinateur est placé devant le patient.","s":4},{"q":"Autour de quoi s'articulent les quatre cibles de l'intervention cérébelleuse ?","o":["L'information sensorielle","La force musculaire","L'amplitude articulaire","La pharmacothérapie"],"r":0,"e":"Les quatre cibles — apprentissage moteur, coordination motrice, contrôle postural et cognition — s'articulent autour de l'information sensorielle.","s":4},{"q":"Quels sont les leviers de l'intervention cérébelleuse ?","o":["Offrir l'opportunité d'une gestion sensorielle","Explorer le mouvement complexe et varié","Offrir l'opportunité de se tromper","Explorer des tâches à exigence posturale","Tenir compte des exigences cognitives","Immobiliser le tronc pour limiter les oscillations"],"r":[0,1,2,3,4],"e":"Cinq leviers, sans oublier la préparation des structures.","s":4},{"q":"Pourquoi le cervelet est-il central dans l'apprentissage moteur ?","o":["Il coordonne le mouvement, l'apprend et le corrige","Il génère la commande motrice, volontaire","Il contrôle la force musculaire, directement","Il commande directement la périphérie, seul"],"r":0,"e":"Le cervelet est un coordinateur, central dans l'apprentissage moteur et la correction du mouvement — d'où la nécessité de laisser l'erreur se produire pour que la correction advienne.","s":4},{"q":"Pourquoi observe-t-on souvent une fixation du cou et du tronc en pathologie cérébelleuse ?","o":["C'est une compensation du manque de stabilité","C'est une conséquence directe de la spasticité","C'est un effet de l'hyperréflexie, au cou et au dos","C'est une rétraction capsulaire, ancienne"],"r":0,"e":"Le cervelet influence la musculature axiale ; la fixation du cou et du tronc est une stratégie compensatoire face au manque de stabilité — d'où l'arbitrage stabilité contre fixation. Le cervelet influence la musculature axiale.","s":4},{"q":"Que signifie « le cervelet est un comparateur, pas un générateur de commande » ?","o":["Il reçoit bien plus qu'il n'émet, et ajuste le mouvement","Il produit la commande motrice volontaire, à chaque geste","Il remplace le cortex moteur, en cas de lésion","Il n'a aucun rôle dans le mouvement, ni dans l'équilibre"],"r":0,"e":"Avec 40 fois plus d'input (feedback interne et externe) que d'output, le cervelet compare et ajuste le mouvement sans en être l'initiateur. Il reçoit 40 fois plus d'input que d'output.","s":4},{"q":"Pourquoi les noyaux gris centraux sont-ils qualifiés de « système accessoire » ?","o":["Ils n'ont aucune connexion directe avec les neurones moteurs","Ils sont facultatifs dans le mouvement volontaire","Ils ne reçoivent aucune afférence, ni du cortex ni de la moelle","Ils sont situés hors du système nerveux central"],"r":0,"e":"Ils ne fonctionnent pas seuls et n'ont pas de connexions directes avec les neurones moteurs.","s":5},{"q":"Quel type d'habiletés les noyaux gris centraux contrôlent-ils ?","o":["Les habiletés automatiques et très apprises","Les mouvements réflexes, médullaires","La sensibilité discriminative, fine et tactile","La régulation cardiaque, au repos"],"r":0,"e":"Ils sont impliqués dans le contrôle de schémas complexes et spécialisés de l'activité motrice. Elles sont aussi répétitives.","s":5},{"q":"Que contrôlent les noyaux gris centraux en contextualisant le mouvement ?","o":["La « quantité » de mouvement","La force maximale","La sensibilité proprioceptive","La vitesse de conduction nerveuse"],"r":0,"e":"Recevant l'input de diverses aires du cortex, ils contextualisent le mouvement en contrôlant la quantité de mouvement.","s":5},{"q":"Quel est le rôle de la voie directe ?","o":["Facilitateur de mouvement — elle désinhibe","Inhibiteur de mouvement — elle supprime","Elle module la sensibilité","Elle contrôle le tonus vasculaire"],"r":0,"e":"Voie directe = facilitatrice (désinhibe) ; voie indirecte = inhibitrice (supprime).","s":5},{"q":"Quel neurotransmetteur module le circuit des noyaux gris centraux ?","o":["La dopamine, de la substance noire compacte","L'acétylcholine, issue du tronc cérébral","La sérotonine, issue des noyaux du raphé","La noradrénaline, issue du locus coeruleus"],"r":0,"e":"La substance noire compacte fournit la dopamine au putamen/striatum.","s":5},{"q":"À quelle catégorie appartient la maladie de Huntington ?","o":["Les troubles hyperkinétiques","Les troubles hypokinétiques","Les parkinsonismes","Les syndromes cérébelleux"],"r":0,"e":"Huntington figure parmi les troubles hyperkinétiques, avec dystonies, chorée, athétose, myoclonie, ballisme, Tourette et dyskinésies.","s":5},{"q":"Quel trouble ne fait PAS partie des parkinsonismes cités ?","o":["La maladie de Huntington","La paralysie supranucléaire progressive","La démence à corps de Lewy","Le parkinsonisme vasculaire"],"r":0,"e":"Huntington est un trouble hyperkinétique ; les autres sont des parkinsonismes.","s":5},{"q":"Pourquoi n'attend-on pas de parésie dans un syndrome hypokinétique ?","o":["Aucun neurone moteur n'a pour origine ces noyaux","La force est toujours compensée par le cortex","La parésie ne survient qu'en phase tardive","La dopamine protège le muscle de toute faiblesse durable"],"r":0,"e":"Malgré l'absence de parésie, la performance motrice est affectée : initiation, sélection, pauvreté et ralentissement du mouvement.","s":5},{"q":"Quelle conséquence NON motrice est attendue dans les syndromes hypokinétiques ?","o":["Des déficits attentionnels et motivationnels","Une hypoesthésie distale, en gants","Une aphasie de Broca, non fluente","Une héminégligence, de l'espace gauche"],"r":0,"e":"On attend aussi une altération des fonctions exécutives, surtout une diminution de la flexibilité cognitive.","s":5},{"q":"Quelle est la fréquence du tremblement de repos parkinsonien ?","o":["3 à 5 Hz","8 à 12 Hz","1 Hz","15 à 20 Hz"],"r":0,"e":"Mouvements oscillatoires à 3-5 Hz, principalement aux mains, membres inférieurs, lèvres et menton.","s":5},{"q":"Où débute tendanciellement le tremblement parkinsonien ?","o":["Aux mains","Aux pieds","À la mâchoire","Au tronc"],"r":0,"e":"Il est tendanciellement latéralisé aux phases initiales et débute aux mains.","s":5},{"q":"Que devient le tremblement de repos pendant le sommeil ?","o":["Il disparaît","Il s'aggrave","Il reste identique","Il devient bilatéral"],"r":0,"e":"Il peut être supprimé au début d'une action et disparaît durant le sommeil et le relâchement complet.","s":5},{"q":"Dans quelles situations le tremblement parkinsonien augmente-t-il ?","o":["Avec le stress et pendant la marche","Au repos complet, uniquement","Pendant le sommeil profond","Lors du relâchement musculaire, après l'effort"],"r":0,"e":"Il tend à augmenter en situations de stress et pendant la marche.","s":5},{"q":"Pourquoi observe-t-on une micrographie dans la maladie de Parkinson ?","o":["Pour éviter de trembler en écrivant","À cause de la rigidité axiale, du tronc","À cause d'une atteinte cérébelleuse","À cause d'un déficit visuel"],"r":0,"e":"La micrographie est décrite comme une stratégie adaptative face au tremblement. C'est une stratégie adaptative face au tremblement.","s":5},{"q":"Quel test peut objectiver la bradykinésie ?","o":["Les tests de diadococinésie","Le test de la roue dentée","Le test de Romberg","Le test doigt-nez"],"r":0,"e":"Les tests de diadococinésie sont utiles à l'identification et à l'objectivation de la bradykinésie.","s":5},{"q":"La bradykinésie inclut également :","o":["L'expression faciale","La sensibilité tactile","Les réflexes ostéo-tendineux","La vision périphérique"],"r":0,"e":"La lenteur inclut l'expression faciale (hypomimie), avec un impact sur s'habiller, s'alimenter et l'hygiène.","s":5},{"q":"Comment la rigidité parkinsonienne se distribue-t-elle ?","o":["Égale sur agonistes et antagonistes, constante","Sur les fléchisseurs seulement, en distal","Variable selon la vitesse d'étirement","En fin d'amplitude seulement, de façon très brutale"],"r":0,"e":"C'est ce qui la différencie de la spasticité, dépendante de la vitesse. Elle est constante sur toute l'amplitude.","s":5},{"q":"Quel test identifie la rigidité parkinsonienne ?","o":["Le test de la roue dentée","Le test de Stewart-Holmes","Le test de Phalen","Le squeeze test"],"r":0,"e":"Le test de la roue dentée est la ressource utile citée dans le cours.","s":5},{"q":"À quoi la rigidité du SLNMS est-elle normalement due ?","o":["À des altérations plastiques, non neurales, du muscle","À la perte des neurones dopaminergiques","À une lésion cérébelleuse, du vermis et des hémisphères","À une atteinte du noyau subthalamique"],"r":0,"e":"Dans le SLNMS elle est causée par des altérations plastiques du muscle secondaires aux raccourcissements et rétractions. Elles font suite aux raccourcissements et rétractions.","s":5},{"q":"Quelle est la combinaison à l'origine de la marche parkinsonienne ?","o":["Bradykinésie et rigidité","Ataxie et hypotonie","Spasticité et clonus","Chorée et dystonie"],"r":0,"e":"La marche parkinsonienne combine bradykinésie et rigidité.","s":5},{"q":"Quelle caractéristique appartient à la marche parkinsonienne ?","o":["Des pas courts, lents, pieds traînant au sol","Une base de sustentation très élargie, instable","Un steppage bilatéral, avec pied tombant","Un fauchage du membre inférieur"],"r":0,"e":"Avec des membres supérieurs près du corps en semi-flexion et une difficulté à l'initiation et au changement de direction.","s":5},{"q":"Comment la marche parkinsonienne s'améliore-t-elle ?","o":["Avec un rythme donné par des indices externes","Avec une augmentation de la charge portée","En supprimant tout indice externe, visuel","Avec une orthèse cheville-pied, rigide"],"r":0,"e":"Les indices externes remplacent le contrôle automatique perdu. Les indices sont visuels et verbaux.","s":5},{"q":"Qu'est-ce que la festination ?","o":["Des pas rapides, le centre de masse projeté en avant","Un arrêt soudain de la marche, sans raison","Une sensation de pieds collés au sol","Un élargissement de la base de support, pour se stabiliser"],"r":0,"e":"La festination est un schéma de pas rapides avec projection du centre de masse vers l'avant.","s":5},{"q":"Dans quelles situations survient typiquement le freezing ?","o":["Obstacles, passages étroits, demi-tours","En terrain plat et bien dégagé, à vitesse constante","Uniquement au repos, en position assise","Uniquement en montée, dans les escaliers"],"r":0,"e":"Le freezing se caractérise par un arrêt soudain ou une difficulté à initier/poursuivre la marche, avec sensation de pieds collés au sol. Les demi-tours sont des changements de direction ; les pieds semblent collés au sol.","s":5},{"q":"Quelle position corporelle caractérise la paralysie supranucléaire progressive ?","o":["Une hyperextension, à l'inverse du Parkinson","Une flexion globale marquée, du tronc","Une inclinaison latérale, du tronc","Une rotation du tronc, avec une épaule avancée"],"r":0,"e":"La position en hyperextension contraste avec la position fléchie de la maladie de Parkinson. La maladie de Parkinson donne une position fléchie.","s":5},{"q":"Quelle est l'atteinte oculomotrice de la paralysie supranucléaire progressive ?","o":["Le regard vertical volontaire est atteint","Le regard horizontal seul est paralysé","Un nystagmus permanent, horizontal","Une cécité corticale, bilatérale et brutale"],"r":0,"e":"Le regard réflexe est relativement préservé ; d'où la rétropulsion de la tête pour compenser l'incapacité d'élever les yeux. Les mouvements verticaux de l'œil sont difficiles ; le regard réflexe est relativement préservé.","s":5},{"q":"Quelle est la survie moyenne dans la paralysie supranucléaire progressive ?","o":["Environ 10 ans après les premiers signes","Environ 2 ans après les tout premiers signes","Environ 25 ans après les premiers signes","Elle ne réduit pas la survie, au total"],"r":0,"e":"Les individus meurent des conséquences de l'immobilité, en moyenne 10 ans après les premiers symptômes.","s":5},{"q":"Quel tableau de l'atrophie multisystématisée associe hypotension orthostatique et parkinsonisme ?","o":["Le syndrome de Shy-Drager","L'atrophie olivo-ponto-cérébelleuse","La dégénérescence nigro-striée","La démence à corps de Lewy"],"r":0,"e":"Shy-Drager : hypotension orthostatique, parkinsonisme et/ou ataxie.","s":5},{"q":"Quelle est la caractéristique de la chorée ?","o":["Des mouvements brefs, continus, non rythmés","Des mouvements lents et sinueux, des mains","Des secousses généralisées, brutales","Des mouvements rapides, des seules racines"],"r":0,"e":"Les mouvements choréiques peuvent converger imperceptiblement vers des mouvements intentionnels, ce qui rend leur identification difficile. Ils touchent les mains, les pieds et le visage.","s":5},{"q":"À quelle structure l'hémiballisme est-il associé ?","o":["Le noyau subthalamique","Le noyau caudé","La substance noire","Le globus pallidus interne"],"r":0,"e":"Le ballisme, plus communément l'hémiballisme, est associé à des dysfonctions du noyau subthalamique.","s":5},{"q":"Dans quels aspects du mouvement les noyaux gris centraux sont-ils impliqués ?","o":["Les mouvements séquentiels","La régulation de la force musculaire","L'initiation, la fin et l'alternance","L'exécution automatique des programmes moteurs appris","La conduction de la commande vers le muscle"],"r":[0,1,2,3],"e":"Mouvements séquentiels, régulation de la force, initiation/fin/alternance et exécution automatique des programmes appris. Ils n'ont aucune connexion directe avec les neurones moteurs.","s":5},{"q":"À quelle capacité d'apprentissage les noyaux gris centraux sont-ils liés ?","o":["Sélectionner un mouvement adapté parmi plusieurs","Mémoriser le vocabulaire d'une langue","Discriminer les textures, au toucher","Réguler le sommeil et l'alternance veille-sommeil"],"r":0,"e":"Ils permettent de choisir un mouvement parmi plusieurs alternatives selon le contexte — d'où leur lien avec l'apprentissage. Le choix se fait selon le contexte.","s":5},{"q":"Quelles fonctions l'aire d'association préfrontale apporte-t-elle en lien avec les noyaux gris centraux ?","o":["L'objectif","L'anticipation des conséquences","Le comportement guidé par l'émotion","La motivation","Le tonus de repos"],"r":[0,1,2,3],"e":"Objectif, anticipation des conséquences, comportement guidé par l'émotion et motivation.","s":5},{"q":"Quel est le circuit des noyaux gris centraux ?","o":["Cortex → striatum → pallidum → thalamus → cortex","Cortex → cervelet → thalamus → moelle épinière","Thalamus → cortex moteur → muscle → moelle → cervelet","Moelle → noyaux gris → cortex → muscle"],"r":0,"e":"Le circuit va du cortex au cortex frontal en passant par le striatum, les pallidums, le noyau subthalamique et le thalamus, sous influence dopaminergique de la substance noire compacte. Le noyau subthalamique y participe ; la substance noire compacte apporte la dopamine.","s":5},{"q":"Quels parkinsonismes figurent parmi les « autres » cités ?","o":["Paralysie supranucléaire progressive","Démence à corps de Lewy","Atrophie multisystématisée","Parkinsonisme vasculaire","Maladie de Huntington"],"r":[0,1,2,3],"e":"Ces quatre s'ajoutent à la maladie de Parkinson et au parkinsonisme médicamenteux. Huntington est un trouble hyperkinétique.","s":5},{"q":"Quelles altérations de la performance motrice observe-t-on dans les syndromes hypokinétiques ?","o":["Difficulté à initier le mouvement","Difficulté à sélectionner entre les mouvements","Pauvreté et ralentissement du mouvement","Tremblement et mouvement involontaire","Altérations de la stabilité posturale avec rigidité","Perte de la sensibilité profonde"],"r":[0,1,2,3,4],"e":"Les cinq altérations sont citées, sans parésie puisque les noyaux gris centraux n'ont pas de neurones moteurs propres.","s":5},{"q":"Quelle fonction exécutive est particulièrement diminuée dans les syndromes hypokinétiques ?","o":["La flexibilité cognitive","La mémoire procédurale","La discrimination sensorielle","Le langage"],"r":0,"e":"Les conséquences non motrices comprennent des déficits attentionnels et motivationnels, et une altération des fonctions exécutives, surtout de la flexibilité cognitive.","s":5},{"q":"Dans quelles circonstances le tremblement de repos parkinsonien est-il supprimé ?","o":["Au début d'une action","Pendant le sommeil","Lors du relâchement complet","Pendant la marche"],"r":[0,1,2],"e":"Il peut être supprimé au début d'une action et disparaît pendant le sommeil et le relâchement complet. Il augmente au contraire pendant la marche et en situation de stress.","s":5},{"q":"Sur quelles activités la bradykinésie a-t-elle un impact évident ?","o":["S'habiller","S'alimenter","L'hygiène personnelle","La lecture"],"r":[0,1,2],"e":"S'habiller, s'alimenter et l'hygiène personnelle sont les activités citées, avec aussi le ralentissement des réponses posturales et l'hypomimie.","s":5},{"q":"Comment s'objective la rigidité parkinsonienne ?","o":["Une résistance accrue au passif comme à l'actif","Une résistance qui dépend de la vitesse d'étirement","Une hypotonie généralisée, flasque","Une abolition des réflexes, ostéo-tendineux"],"r":0,"e":"La rigidité est une augmentation de la résistance au mouvement passif et actif dans tous les muscles, constante sur toute l'amplitude et touchant agonistes et antagonistes de la même façon. Elle touche tous les muscles, agonistes et antagonistes, sur toute l'amplitude.","s":5},{"q":"Quel est l'effet de la rigidité sur les voies descendantes ?","o":["Une contraction excessive des muscles posturaux","Une abolition de la commande volontaire, globale","Une suppression du tonus de repos","Une inversion des réflexes, à l'étirement"],"r":0,"e":"L'effet sur les voies descendantes produit une contraction excessive des muscles posturaux.","s":5},{"q":"Quelles caractéristiques définissent la marche parkinsonienne ?","o":["Bras près du corps, en semi-flexion","Pas courts, lents et traînants","Démarrage et virages difficiles","Base de sustentation très élargie"],"r":[0,1,2],"e":"Membres supérieurs en semi-flexion près du corps, pas courts et traînants, difficulté d'initiation et de changement de direction. La base très élargie caractérise le syndrome cérébelleux du lobe antérieur. La difficulté porte sur l'initiation et le changement de direction.","s":5},{"q":"À quoi le freezing est-il associé ?","o":["Aux obstacles","Aux passages étroits","Aux changements de direction","À la position allongée"],"r":[0,1,2],"e":"Le freezing — arrêt soudain ou difficulté à initier/poursuivre la marche, avec sensation de pieds collés au sol — survient face aux obstacles, dans les passages étroits et aux changements de direction.","s":5},{"q":"Qu'est-ce qui explique la rétropulsion de la tête dans la paralysie supranucléaire progressive ?","o":["L'incapacité d'élever les yeux volontairement","Une rigidité cervicale isolée, en extension forcée","Une ataxie axiale, du tronc et du cou","Une hypotonie des fléchisseurs du cou"],"r":0,"e":"La paralysie du regard vertical empêche l'élévation volontaire des yeux, ce qui entraîne une rétropulsion compensatoire de la tête.","s":5},{"q":"Quelle est l'atteinte du regard dans la paralysie supranucléaire progressive ?","o":["Le volontaire est atteint, le réflexe en partie préservé","Le réflexe est aboli, le volontaire reste entièrement préservé","Les deux sont totalement abolis, d'emblée","Seul le regard horizontal est atteint, à gauche"],"r":0,"e":"Difficulté avec les mouvements verticaux de l'œil, saccadiques et de poursuite : le regard volontaire est compromis, le regard réflexe garde une certaine préservation.","s":5},{"q":"Quel tableau de l'atrophie multisystématisée associe ataxie, hyperréflexie et dysarthrie ?","o":["L'atrophie olivo-ponto-cérébelleuse","La dégénérescence nigro-striée","Le syndrome de Shy-Drager","Le parkinsonisme vasculaire"],"r":0,"e":"Atrophie olivo-ponto-cérébelleuse : ataxie, hyperréflexie et dysarthrie. La dégénérescence nigro-striée donne rigidité, bradykinésie, instabilité posturale, hypotension posturale, incontinence et dysfonction érectile.","s":5},{"q":"Quelles caractéristiques définissent la dystonie ?","o":["Des mouvements involontaires ni répétitifs ni rythmiques, variables","Une hypertrophie habituelle des muscles affectés","Une augmentation pendant l'activité et le stress émotionnel","Une disparition pendant le sommeil","Des mouvements brefs et continus des mains, pieds et visage"],"r":[0,1,2,3],"e":"Les quatre premières caractérisent la dystonie. Les mouvements brefs et continus des mains, pieds et visage définissent la chorée.","s":5},{"q":"Quelles formes de dystonie existe-t-il ?","o":["Focale, la plus commune","Segmentaire ou multifocale","Généralisée, à tout le corps","Transitoire, la nuit"],"r":[0,1,2],"e":"Focale (une seule zone, la plus commune), segmentaire ou multifocale, et généralisée (tout le corps, maladie de Huntington). La forme généralisée se voit par exemple dans la maladie de Huntington.","s":5},{"q":"Qu'est-ce que l'athétose et avec quoi peut-elle coexister ?","o":["Des mouvements lents et sinueux, parfois avec une chorée","Des mouvements rapides des extrémités, subthalamiques","Des secousses de tout le corps, brutales","Une rigidité en roue dentée, au poignet et au coude"],"r":0,"e":"L'athétose est un flux continu de mouvements lents et sinueux, surtout aux mains et aux pieds, et peut coexister avec la chorée — on parle alors de choréoathétose. Ces mouvements de contorsion touchent surtout les mains et les pieds ; avec la chorée, on parle de choréoathétose.","s":5},{"q":"Pourquoi l'identification des mouvements choréiques est-elle difficile ?","o":["Ils peuvent se fondre dans des gestes intentionnels","Ils sont trop rapides pour être vus à l'œil nu","Ils ne surviennent que la nuit, au cours du sommeil","Ils sont strictement rythmés, comme un tremblement"],"r":0,"e":"Les mouvements choréiques, brefs et continus mais non rythmés, peuvent converger de façon imperceptible vers des mouvements intentionnels, ce qui complique leur identification.","s":5},{"q":"Jusqu'à quel niveau la moelle épinière s'étend-elle ?","o":["Du foramen magnum jusqu'à L2","Du foramen magnum jusqu'à S1","De C1 jusqu'à T12","Du foramen magnum jusqu'à L5"],"r":0,"e":"La moelle est la partie du SNC allant du foramen magnum jusqu'à L2.","s":6},{"q":"Entre quels niveaux se forme le cône médullaire ?","o":["Entre L2 et L4","Entre T12 et L1","Entre L4 et S1","Entre L1 et L2"],"r":0,"e":"Dans sa portion caudale la moelle forme le cône médullaire entre L2 et L4.","s":6},{"q":"Comment appelle-t-on l'ensemble des racines non neurales sous le cône médullaire ?","o":["La queue de cheval","Le filum terminale","Le plexus lombo-sacré","Le cône sacré"],"r":0,"e":"À partir de cette région se forment les racines non neurales qui, dans leur ensemble, se dénomment queue de cheval.","s":6},{"q":"Combien de paires de nerfs sortent de la moelle ?","o":["31","33","30","29"],"r":0,"e":"8 cervicaux, 12 dorsaux, 5 lombaires, 5 sacrés et 1 coccygien.","s":6},{"q":"Combien de paires de nerfs cervicaux existe-t-il ?","o":["8","7","12","5"],"r":0,"e":"Il y a 8 paires de nerfs cervicaux, pour 7 vertèbres cervicales.","s":6},{"q":"Quelle sensibilité est conservée dans le syndrome médullaire antérieur ?","o":["La sensibilité posturale et proprioceptive","La sensibilité thermique, au chaud","La sensibilité douloureuse, à la piqûre","La sensibilité tactile, au toucher léger"],"r":0,"e":"Le syndrome antérieur entraîne une paralysie sous le niveau et une perte des sensibilités tactile, thermique et douloureuse, mais conserve la proprioception.","s":6},{"q":"Quel est le mécanisme du syndrome médullaire antérieur ?","o":["Une luxation antérieure, avec un recul du disque","Une hyperextension sur un canal étroit, chez le sujet âgé","Une hémisection, par arme blanche","Une compression du cône sacré, basse"],"r":0,"e":"C'est le mécanisme décrit dans le cours. La luxation peut être une subluxation ; c'est le disque ou le corps vertébral qui fait protrusion en arrière.","s":6},{"q":"À quel niveau survient exclusivement le syndrome centro-médullaire ?","o":["Au niveau cervical","Au niveau thoracique","Au niveau lombaire","Au niveau sacré"],"r":0,"e":"Il résulte d'une lésion en hyperextension avec compression de la moelle dans un canal sténosé et survient exclusivement au niveau cervical.","s":6},{"q":"Quelle est la caractéristique motrice du syndrome centro-médullaire ?","o":["Une perte motrice plus marquée aux membres supérieurs","Une perte motrice plus marquée aux membres inférieurs","Une paralysie flasque totale","Une atteinte purement sensitive"],"r":0,"e":"Il s'accompagne aussi d'une dysfonction vésicale avec rétention urinaire fréquente.","s":6},{"q":"Que caractérise le syndrome de Brown-Séquard ?","o":["Une hémisection, qui atteint un côté de la moelle","Une compression circonférentielle de toute la moelle","Une atteinte de la seule substance grise","Une lésion du cône médullaire, basse"],"r":0,"e":"C'est un type de lésion fermée, par exemple par arme blanche.","s":6},{"q":"Dans le Brown-Séquard, que trouve-t-on sous le niveau lésionnel du côté opposé ?","o":["Une perte thermo-algique, avec une motricité conservée","Une paralysie complète, flasque puis spastique","Une perte proprioceptive isolée, en distal","Aucune anomalie, ni motrice ni sensitive, de ce côté-là"],"r":0,"e":"Au niveau de la lésion il y a perte totale de la sensibilité tactile et thermique ; sous le niveau, du côté opposé, perte thermo-algique avec motricité conservée.","s":6},{"q":"Quel syndrome donne une paralysie de type flasque par lésion sous L2 ?","o":["Le syndrome de la queue de cheval","Le syndrome du cône médullaire","Le syndrome centro-médullaire","Le syndrome antérieur"],"r":0,"e":"Le syndrome de la queue de cheval touche les nerfs lombaires et sacrés et donne une paralysie flasque.","s":6},{"q":"Quelle est la conséquence du syndrome du cône médullaire ?","o":["Une aréflexie de la vessie, de l'intestin et des jambes","Une atteinte motrice des membres supérieurs","Une hyperréflexie généralisée, des quatre membres et du tronc","Une perte de la seule proprioception, distale"],"r":0,"e":"Il correspond à la lésion du cône sacré et des racines lombaires à l'intérieur du canal neural.","s":6},{"q":"Quelle cause n'est PAS traumatique ?","o":["La syringomyélie","Le plongeon","La chute d'objet sur la colonne","L'agression par arme blanche"],"r":0,"e":"La syringomyélie est une cause non traumatique idiopathique.","s":6},{"q":"Quelle cause non traumatique est classée comme inflammatoire ?","o":["La myélite transverse","La hernie discale","Le spina bifida","Le spondylolisthésis"],"r":0,"e":"Inflammatoires : myélite transverse, poliomyélite, tuberculose.","s":6},{"q":"Où débute le processus de destruction secondaire ?","o":["Dans la substance grise, puis dans la blanche","Dans la substance blanche, puis dans la grise","Dans les méninges, puis dans la moelle","Dans le corps vertébral, puis le disque"],"r":0,"e":"Il débute normalement dans la substance grise puis s'étend à la substance blanche.","s":6},{"q":"Quelle est la durée maximale du processus de destruction secondaire ?","o":["4 semaines","48 heures","6 mois","1 an"],"r":0,"e":"Il dure quelques jours et peut atteindre 4 semaines.","s":6},{"q":"De quoi dépend l'étendue de la destruction secondaire ?","o":["De la sévérité du trauma et du traitement administré","De l'âge seul, quel que soit le trauma","Du niveau lésionnel seul, cervical ou dorsal","Du sexe du patient, et de son poids au moment de l'accident"],"r":0,"e":"Ce sont les deux facteurs cités dans le cours.","s":6},{"q":"Quel mouvement ionique caractérise l'altération de l'homéostasie après le trauma ?","o":["Le potassium sort des cellules et le sodium y entre","Le sodium sort des cellules et le potassium y entre","Le calcium quitte les cellules, en masse","Le chlore s'accumule à l'extérieur des cellules"],"r":0,"e":"Cela entraîne une perte d'excitabilité neuronale ; en parallèle le calcium s'accumule dans la cellule.","s":6},{"q":"Quelles cellules phagocytent les débris lors de la réaction inflammatoire médullaire ?","o":["Les neutrophiles et les macrophages","Les astrocytes, uniquement","Les oligodendrocytes, myélinisants","Les cellules de Schwann, en périphérie"],"r":0,"e":"Neutrophiles et macrophages phagocytent les débris.","s":6},{"q":"Comment définit-on une lésion médullaire ?","o":["Une compression de la moelle, osseuse ou non","Une fracture vertébrale isolée, stable","Une compression purement osseuse, sans atteinte nerveuse","Une lésion des nerfs périphériques, distale"],"r":0,"e":"Elle entraîne une interruption complète ou partielle des aires sensorielles et/ou motrices, et le SNA est aussi affecté. La structure osseuse peut être atteinte ou non.","s":6},{"q":"Que signifie ASIA ?","o":["American Spinal Injury Association","Assessment of Spinal Injury and Ability","American Spine Impairment Assessment","Association for Spinal Injury Assessment"],"r":0,"e":"Ce sont les standards internationaux de classification neurologique et fonctionnelle des lésions médullaires.","s":6},{"q":"Quel segment détermine le caractère complet ou incomplet d'une lésion ?","o":["S4-S5","L1-L2","T12","C8"],"r":0,"e":"Complète = absence de fonction sensorielle et motrice en S4-S5 ; incomplète = préservation partielle incluant S4-S5.","s":6},{"q":"Que comprend la sensation sacrée à évaluer ?","o":["La jonction muco-cutanée et l'anus en profondeur","La sensibilité plantaire et dorsale du pied","Le réflexe rotulien et le réflexe achilléen","La sensibilité périnéale superficielle, seule"],"r":0,"e":"C'est ce qui définit la préservation sacrée dans une lésion incomplète.","s":6},{"q":"Comment définit-on la tétraplégie ?","o":["Une perte de fonction du segment cervical de la moelle","Toute perte des quatre membres, quelle qu'en soit l'origine","Une lésion du plexus brachial, bilatérale","Une lésion thoracique haute, de T1 à T6"],"r":0,"e":"Elle n'inclut ni les lésions du plexus brachial ni les lésions des nerfs périphériques hors du canal médullaire. La perte peut être motrice et/ou sensorielle.","s":6},{"q":"La paraplégie concerne quels segments ?","o":["Thoraciques, lombaires ou sacrés","Cervicaux uniquement, hauts et bas","Cervicaux et thoraciques, hauts","Lombaires uniquement, sous la ceinture"],"r":0,"e":"Dans la paraplégie les membres supérieurs fonctionnent normalement ; le terme couvre aussi la queue de cheval et le cône médullaire.","s":6},{"q":"Quel grade ASIA correspond à une fonction sensorielle préservée mais non motrice ?","o":["B","A","C","D"],"r":0,"e":"ASIA B : fonction sensorielle préservée, motrice absente sous le niveau neurologique, incluant S4-S5.","s":6},{"q":"Quel grade ASIA correspond à une motricité préservée avec plus de la moitié des muscles clés de grade < 3 ?","o":["C","B","D","E"],"r":0,"e":"ASIA C : motricité préservée sous le niveau, plus de la moitié des muscles clés cotés en dessous de 3.","s":6},{"q":"Quel grade ASIA correspond à plus de la moitié des muscles clés de grade ≥ 3 ?","o":["D","C","B","A"],"r":0,"e":"ASIA D : fonction motrice préservée sous le niveau neurologique avec plus de la moitié des muscles de grade ≥ 3.","s":6},{"q":"Quels sont les trois niveaux précisés par la classification ASIA ?","o":["Niveaux moteur, sensoriel et neurologique","Niveaux osseux, discal et médullaire","Niveaux vertébral, radiculaire et tronculaire","Niveaux proximal, moyen et distal, de chaque membre"],"r":0,"e":"La classification précise le niveau moteur, le niveau sensoriel et le niveau neurologique.","s":6},{"q":"Combien de paires de nerfs rachidiens compte chaque étage ?","o":["12 dorsaux","5 lombaires","5 sacrés","1 coccygien","10 cervicaux"],"r":[0,1,2,3],"e":"8 cervicaux, 12 dorsaux, 5 lombaires, 5 sacrés et 1 coccygien, soit 31 paires.","s":6},{"q":"Quel syndrome médullaire préserve la sensibilité posturale et proprioceptive ?","o":["Le syndrome antérieur","Le syndrome centro-médullaire","Le Brown-Séquard","Le syndrome de la queue de cheval"],"r":0,"e":"Le syndrome antérieur donne une paralysie sous le niveau avec perte de la sensibilité tactile, thermique et douloureuse, mais conserve la sensibilité posturale et proprioceptive.","s":6},{"q":"Quel est le mécanisme du syndrome centro-médullaire ?","o":["Une hyperextension, dans un canal rétréci","Une luxation antérieure, avec recul du disque","Une hémisection de la moelle, latérale","Une lésion des racines sous L2, en queue de cheval"],"r":0,"e":"Lésion en hyperextension avec compression dans un canal sténosé, survenant exclusivement au niveau cervical et affectant surtout la substance blanche des cordons latéraux. La moelle est comprimée dans un canal sténosé.","s":6},{"q":"Quelle dysfonction vésicale accompagne le syndrome centro-médullaire ?","o":["Une rétention urinaire fréquente","Une incontinence par regorgement isolée","Aucune atteinte vésicale","Une vessie flasque définitive"],"r":0,"e":"Le syndrome centro-médullaire associe une perte motrice prédominant aux membres supérieurs, une dysfonction vésicale avec rétention urinaire fréquente et des degrés variables de perte sensitive.","s":6},{"q":"Quel mécanisme produit un syndrome de Brown-Séquard ?","o":["Une hémisection, comme par arme blanche","Une compression circonférentielle de la moelle","Une ischémie de l'artère spinale antérieure","Une hernie discale médiane, cervicale"],"r":0,"e":"Le Brown-Séquard résulte d'une hémisection médullaire n'affectant qu'un côté de la moelle, typiquement par arme blanche. C'est une lésion fermée qui n'atteint qu'un côté de la moelle.","s":6},{"q":"Quelles causes non traumatiques de lésion médullaire sont congénitales ?","o":["Le spina bifida","La scoliose","La myélite transverse","La syringomyélie"],"r":[0,1],"e":"Spina bifida et scoliose sont congénitales. La myélite transverse est inflammatoire, la syringomyélie idiopathique.","s":6},{"q":"Quelles causes non traumatiques sont classées comme dégénératives ?","o":["Les hernies discales","Le canal sténosé","L'arthrose","La poliomyélite"],"r":[0,1,2],"e":"Hernies discales, canal sténosé et arthrose sont dégénératifs. La poliomyélite est inflammatoire.","s":6},{"q":"Quelles causes iatrogènes de lésion médullaire sont citées ?","o":["La radiation","L'infection médullaire","Les chirurgies","L'infarctus médullaire"],"r":[0,1,2],"e":"Radiation, infection médullaire et chirurgies sont iatrogènes. L'AVM est vasculaire.","s":6},{"q":"Quelle est la conséquence de l'altération de l'homéostasie ionique après le trauma médullaire ?","o":["Une perte d'excitabilité, sans potentiel d'action","Une hyperexcitabilité durable, des neurones","Une régénération axonale, rapide et complète","Une augmentation de la conduction nerveuse"],"r":0,"e":"Le potassium sort, le sodium entre, le calcium s'accumule : il en résulte une perte d'excitabilité neuronale et la disparition des potentiels d'action.","s":6},{"q":"Quelles étapes composent la cascade de la lésion secondaire ?","o":["Ischémie, par arrêt de l'apport sanguin","Homéostasie ionique altérée","Excitotoxicité et oxygène réactif","Inflammation locale","Nécrose et apoptose","Régénération axonale spontanée"],"r":[0,1,2,3,4],"e":"Les cinq étapes s'enchaînent, aboutissant à la dégradation des protéines et phospholipides, à la démyélinisation et à la destruction membranaire. L'excitotoxicité vient de l'accumulation d'acides aminés excitateurs ; la mort cellulaire passe par nécrose et apoptose.","s":6},{"q":"Quel système, en plus du sensitif et du moteur, est affecté par une lésion médullaire ?","o":["Le système nerveux autonome","Le système endocrinien hypophysaire","Le système lymphatique","Le système immunitaire adaptatif"],"r":0,"e":"La fiche précise explicitement que le SNA est aussi affecté, en plus des aires sensorielles et motrices.","s":6},{"q":"À quoi sert une classification précise de la lésion médullaire ?","o":["À déterminer la sévérité de la lésion","À établir le pronostic","À définir le plan d'intervention","À évaluer les résultats dans le cadre de la CIF","À déterminer la responsabilité médico-légale"],"r":[0,1,2,3],"e":"Les quatre finalités sont citées, dans le cadre de la CIF.","s":6},{"q":"Qu'apporte la classification ASIA en tant que standard international ?","o":["La standardisation de l'évaluation et des termes","Un protocole chirurgical unique, pour tous les centres","Un barème d'indemnisation, national","Une échelle de douleur, numérique"],"r":0,"e":"L'ASIA fournit des standards internationaux de classification neurologique et fonctionnelle, permettant de standardiser l'évaluation et la nomenclature.","s":6},{"q":"Quelles structures la tétraplégie exclut-elle explicitement ?","o":["Les lésions du plexus brachial","Les nerfs hors du canal médullaire","Les lésions du segment cervical","Les lésions du cône médullaire"],"r":[0,1],"e":"La tétraplégie concerne la destruction des éléments neuraux à l'intérieur du canal médullaire au niveau cervical : elle n'inclut ni le plexus brachial ni les nerfs périphériques hors du canal. Il s'agit des nerfs périphériques.","s":6},{"q":"Quelles lésions le terme paraplégie recouvre-t-il ?","o":["Les lésions de la queue de cheval","Les lésions du cône médullaire","Les lésions du plexus lombo-sacré","Les lésions des nerfs périphériques hors du canal"],"r":[0,1],"e":"Le terme s'applique aux lésions de la queue de cheval et du cône médullaire, mais pas au plexus lombo-sacré ni aux nerfs périphériques hors du canal.","s":6},{"q":"Que comprend l'évaluation de la sensation sacrée pour classer une lésion d'incomplète ?","o":["La sensation à la jonction muco-cutanée","La sensation anale profonde","Le réflexe rotulien","Le tonus des membres inférieurs"],"r":[0,1],"e":"La sensation sacrée inclut la sensation à la jonction muco-cutanée ainsi que la sensation anale profonde.","s":6},{"q":"Quel grade ASIA correspond à une fonction motrice et sensitive normale ?","o":["E","D","A","B"],"r":0,"e":"A : complète. B : sensitive préservée seule. C : motrice préservée, plus de la moitié des muscles clés < 3. D : plus de la moitié ≥ 3. E : normale.","s":6},{"q":"Quel syndrome médullaire donne une perte des réflexes de la vessie, des intestins et des membres inférieurs ?","o":["Le syndrome du cône médullaire","Le syndrome antérieur","Le syndrome centro-médullaire","Le Brown-Séquard"],"r":0,"e":"Le syndrome du cône médullaire, par lésion du cône sacré et des racines lombaires dans le canal neural, entraîne la perte des réflexes vésicaux, intestinaux et des membres inférieurs.","s":6},{"q":"Pourquoi parle-t-on de « racines non neurales » pour la queue de cheval ?","o":["Elles naissent sous le cône, hors de la moelle","Elles ne conduisent aucun influx nerveux","Elles n'ont pas de gaine de myéline, du tout","Elles sont situées hors du canal vertébral"],"r":0,"e":"La moelle s'arrête en L2 et forme le cône médullaire entre L2 et L4 ; au-delà, l'ensemble des racines constitue la queue de cheval. La moelle s'arrête en L2, le cône médullaire va de L2 à L4.","s":6},{"q":"Quelles structures faut-il réviser en complément de l'anatomie médullaire ?","o":["Les vertèbres, le sacrum et le coccyx","Les ligaments vertébraux","Les méninges spinales","La vascularisation médullaire","Le système lymphatique abdominal"],"r":[0,1,2,3],"e":"Structure vertébrale complète, ligaments, méninges et vascularisation sont les structures à réviser. Les vertèbres sont cervicales, dorsales et lombaires.","s":6},{"q":"Où commence le traitement adéquat d'une personne avec lésion médullaire ?","o":["Sur les lieux de l'accident","À l'arrivée aux urgences","Au bloc opératoire","En centre de rééducation"],"r":0,"e":"La phase aiguë commence à l'instant de la lésion et le traitement adéquat commence sur les lieux de l'accident.","s":7},{"q":"Quel traitement conservateur est utilisé dans une lésion cervicale avec subluxation ?","o":["La traction squelettique","L'orthèse de tronc","Le positionnement au lit seul","La laminectomie"],"r":0,"e":"Quand la RX révèle une angulation vertébrale ou une subluxation cervicale, on recourt à la traction squelettique.","s":7},{"q":"Quelle situation indique un traitement chirurgical ?","o":["Une évidence de compression médullaire","Une lésion stable","Des lésions vertébrales multiples stables","Une absence de déficit neurologique"],"r":0,"e":"Indications : fractures instables, réductibles seulement chirurgicalement, mauvais alignement, compression médullaire, détérioration neurologique, instabilité persistante.","s":7},{"q":"Qu'est-ce qu'une corporectomie ?","o":["L'ablation du corps de la vertèbre","La résection d'une lame vertébrale","Le blocage définitif de l'articulation","L'extraction d'un disque hernié"],"r":0,"e":"Corporectomie = ablation du corps vertébral ; laminectomie = résection des lames ; arthrodèse = blocage articulaire ; discectomie = extraction discale.","s":7},{"q":"Quel est le grand avantage du traitement chirurgical ?","o":["Un alitement plus court, quelques semaines d'hôpital","La suppression de toute orthèse, après l'opération","La guérison neurologique complète, en quelques semaines","L'absence de rééducation, par la suite"],"r":0,"e":"Si nécessaire, la colonne est ensuite immobilisée par orthèse pendant 6 semaines à 3 mois. L'hospitalisation dure 2 à 4 semaines.","s":7},{"q":"Quelle est la cause du choc médullaire ?","o":["Elle est inconnue","Une hémorragie systématique","Une infection","Une compression osseuse directe"],"r":0,"e":"C'est un phénomène transitoire survenant après un trauma médullaire, de cause inconnue.","s":7},{"q":"Quelle est la caractéristique vésicale pendant le choc médullaire ?","o":["Une vessie flasque, sans action du détrusor","Une vessie spastique, qui se vide seule","Un détrusor hyperréflexe, instable","Une continence normale, préservée"],"r":0,"e":"Pendant le choc médullaire, vessie et intestins sont non réflexes ; un sondage est nécessaire. La vessie est non réflexe.","s":7},{"q":"Que se passe-t-il au retour des réflexes pour une lésion au-dessus de L1 ?","o":["Spasticité, hyperréflexie, vessie et intestins réflexes","Hypotonie, réflexes diminués, vessie flasque","Paralysie flasque définitive, sans aucun retour des réflexes","Récupération complète, sans aucune séquelle motrice"],"r":0,"e":"Sous L1 au contraire : hypotonie et réflexes diminués.","s":7},{"q":"Quelle est la cause directe d'une escarre de pression ?","o":["La pression","L'humidité","Le tabac","Le poids corporel"],"r":0,"e":"Les autres éléments sont des facteurs contributifs ; la cause directe est la pression prolongée provoquant ischémie ou anoxie tissulaire.","s":7},{"q":"À quelle fréquence faut-il retourner le patient au lit ?","o":["Toutes les 2 heures, jour et nuit","Toutes les 6 heures, le jour seulement","Une fois par jour, le matin","Toutes les 30 minutes, la nuit"],"r":0,"e":"Le retournement toutes les 2 heures jour et nuit est la règle de prévention au lit.","s":7},{"q":"À quelle fréquence et pendant combien de temps réaliser le soulagement de pression au fauteuil ?","o":["Toutes les demi-heures pendant 1'30'' à 2'","Toutes les 2 heures pendant 30 secondes","Une fois par heure pendant 10 secondes","Uniquement en cas de rougeur"],"r":0,"e":"C'est la seule façon d'obtenir une circulation sanguine adéquate dans les zones de pression maximale, indépendamment du coussin utilisé.","s":7},{"q":"Quelle est la principale cause de décès après une lésion médullaire ?","o":["Les complications respiratoires","Les escarres","L'embolie pulmonaire","Les fractures pathologiques"],"r":0,"e":"Les complications respiratoires sont la principale cause de décès après une lésion médullaire.","s":7},{"q":"Quelle conséquence découle d'une toux inefficace ?","o":["Encombrement, atélectasies, pneumonies","Hypertension artérielle de repos","Bradycardie sévère, avec malaise","Hyperthermie prolongée"],"r":0,"e":"C'est la conséquence de la réduction de la capacité expiratoire. L'insuffisance respiratoire peut suivre.","s":7},{"q":"À quels niveaux médullaires correspond l'innervation du diaphragme ?","o":["C3-C4-C5","C1-C2","T1-T7","T6-T12"],"r":0,"e":"Diaphragme C3-C4-C5, accessoires C1-C8, intercostaux T1-T7, abdominaux T6-T12.","s":7},{"q":"Où la perte de masse osseuse est-elle la plus sévère après une lésion médullaire ?","o":["Aux membres inférieurs, sous la lésion","Aux membres supérieurs, au-dessus","Au rachis cervical, au niveau de la lésion","Au crâne, de façon diffuse"],"r":0,"e":"Elle se produit plus rapidement dans les premiers mois, sous la lésion, et est plus sévère aux membres inférieurs et dans les lésions complètes et flasques. Elle est plus sévère dans les lésions complètes et flasques.","s":7},{"q":"Quel profil est plus à risque de fractures pathologiques ?","o":["ASIA A et B, paraplégie, sexe féminin","ASIA D, tétraplégie, sexe masculin","ASIA E, lésion très récente","Lésion incomplète, récente"],"r":0,"e":"Les facteurs cités : ASIA A et B, paraplégie, origine caucasienne, temps plus long après la lésion, sexe féminin. L'origine caucasienne et l'ancienneté de la lésion augmentent aussi le risque.","s":7},{"q":"Qu'est-ce que l'ossification hétérotopique ?","o":["De l'os formé hors du squelette, près des articulations","Une fracture spontanée, sur os fragile","Une déminéralisation osseuse, diffuse","Une calcification tendineuse isolée, à l'épaule surtout"],"r":0,"e":"Elle peut devenir suffisamment massive pour provoquer une ankylose extra-articulaire. Elle est d'abord périarticulaire, puis intramusculaire.","s":7},{"q":"Quelle hypothèse est émise sur la cause de l'ossification hétérotopique ?","o":["Des microtraumatismes, par mobilisation excessive","Une carence en vitamine D, au long cours, sévère","Une infection bactérienne, articulaire","Un déficit hormonal, en testostérone"],"r":0,"e":"La cause reste inconnue mais cette hypothèse est celle avancée dans le cours.","s":7},{"q":"Quelles sont les causes de l'œdème après lésion médullaire ?","o":["La perte de la pompe musculaire et l'hypercoagulation","Une insuffisance cardiaque, droite","Une hypoprotidémie, par dénutrition et fonte musculaire","Une insuffisance rénale aiguë, oligurique"],"r":0,"e":"La stase veineuse et les altérations des propriétés sanguines expliquent l'œdème, qui peut évoluer vers une TVP. Sans contraction musculaire, le retour veineux ne se fait plus.","s":7},{"q":"Quel signe n'appartient PAS à l'embolie pulmonaire ?","o":["Une bradycardie","Une dyspnée","Une douleur thoracique","Une toux soudaine"],"r":0,"e":"L'embolie pulmonaire donne une tachycardie ; elle est potentiellement fatale. Elle donne au contraire une tachycardie, avec difficultés respiratoires, douleur thoracique ou dorsale et toux soudaine.","s":7},{"q":"Pourquoi l'hypothermie survient-elle après une lésion médullaire ?","o":["Par vasodilatation, avec perte de chaleur","Par vasoconstriction excessive, en périphérie","Par sudation excessive, profuse","Par hypermétabolisme, de repos"],"r":0,"e":"Elle est plus fréquente juste après la lésion ou chez les tétraplégiques et peut mener à la mort si elle n'est pas contrôlée.","s":7},{"q":"Quelle est la cause de l'hyperthermie après lésion médullaire ?","o":["La sudation est impossible sous le niveau lésionnel","Une infection, présente dans tous les cas","Une vasoconstriction périphérique, intense","Un excès de vêtements, à lui seul, chez un patient alité"],"r":0,"e":"Le patient peut se présenter dyspnéique et fatigué ; un refroidissement corporel peut être nécessaire.","s":7},{"q":"Quel déséquilibre explique l'hypotension orthostatique après lésion médullaire ?","o":["Le cœur perd le sympathique, garde le parasympathique","Le parasympathique est perdu, le sympathique reste actif","Les deux systèmes sont abolis, d'emblée","Le sympathique devient hyperactif, au repos"],"r":0,"e":"Cette rupture d'équilibre donne bradycardie, bradyarythmies et dilatation vasculaire périphérique sous le niveau.","s":7},{"q":"Au-dessus de quel niveau survient la dysréflexie autonome ?","o":["T6","T12","L1","C5"],"r":0,"e":"Elle survient chez 10 à 85 % de la population avec lésion au-dessus de T6, après résolution du choc médullaire.","s":7},{"q":"Quelle association de signes évoque une dysréflexie autonome ?","o":["Hypertension, bradycardie, céphalée pulsatile soudaine","Hypotension, tachycardie, pâleur et malaise","Hyperthermie, bradypnée, somnolence et confusion progressive","Hypoglycémie, sueurs froides, tremblements"],"r":0,"e":"On observe aussi une sudation et une vasodilatation au-dessus du niveau, et une vasoconstriction sous le niveau.","s":7},{"q":"Quel stimulus est le plus classiquement déclencheur d'une dysréflexie autonome ?","o":["Une distension vésicale ou intestinale","Une hypoglycémie, après le jeûne","Une hyperventilation, anxieuse","Un exercice aérobie léger, en fauteuil roulant"],"r":0,"e":"La distension vésicale, intestinale ou rectale figure en tête des stimuli déclenchants.","s":7},{"q":"Dans quel cas la spasticité peut-elle être avantageuse ?","o":["Pour maintenir le trophisme et la pompe musculaire","Pour améliorer la précision du geste","Pour diminuer la douleur neuropathique, chronique et diffuse","Pour faciliter les transferts, au lit"],"r":0,"e":"Elle diminue aussi le risque de lésions cutanées en regard des éminences osseuses.","s":7},{"q":"Quelle est la prévalence de la douleur après lésion médullaire ?","o":["77 % à 81 %","20 % à 30 %","45 % à 50 %","Moins de 10 %"],"r":0,"e":"Des études récentes estiment la prévalence à 77-81 %, avec un impact sur la qualité de vie, l'incapacité et la dépression.","s":7},{"q":"Quelle est la caractéristique vésicale d'une lésion au-dessus de T12 ?","o":["Un détrusor hyperréflexe, une vessie de petite capacité","Un détrusor aréflexique, une vessie de grande capacité","Une continence normale, avec des mictions volontaires complètes","Une absence complète de sphincter fonctionnel"],"r":0,"e":"Vessie réflexe au-dessus de T12 ; vessie flasque sous L1/L2 avec aréflexie du détrusor et augmentation de capacité et compliance. La compliance est aussi diminuée.","s":7},{"q":"Quel objectif n'est PAS attribué à la réadaptation à la position debout ?","o":["Augmenter la spasticité","Prévenir les contractures des membres inférieurs","Minimiser l'ostéoporose des os longs","Améliorer le retour veineux"],"r":0,"e":"Au contraire, la verticalisation vise à diminuer la spasticité, en plus de prévenir contractures, ostéoporose, déformations et escarres.","s":7},{"q":"Quelles indications relèvent d'un traitement conservateur de la lésion médullaire ?","o":["Une lésion stable","Des lésions vertébrales multiples","Une fracture instable","Une évidence de compression médullaire"],"r":[0,1],"e":"Lésion stable et lésions vertébrales multiples relèvent du conservateur, au prix d'un alitement de 6, 8 ou 12 semaines. Instabilité et compression imposent la chirurgie.","s":7},{"q":"Quelles procédures chirurgicales sont citées dans la lésion médullaire ?","o":["Arthrodèse","Corporectomie et discectomie","Laminectomie","Pose de matériel d'ostéosynthèse","Vertébroplastie percutanée"],"r":[0,1,2,3],"e":"Arthrodèse (blocage définitif de l'articulation), corporectomie (ablation du corps vertébral), discectomie, laminectomie (résection de lames) et ostéosynthèse.","s":7},{"q":"Combien de temps la colonne est-elle immobilisée par orthèse après chirurgie, si nécessaire ?","o":["De 6 semaines à 3 mois","De 2 à 4 semaines","De 6 mois à 1 an","Moins d'une semaine"],"r":0,"e":"L'immobilisation par orthèse dure de 6 semaines à 3 mois pour permettre la cicatrisation osseuse, après une hospitalisation ramenée à 2-4 semaines par la chirurgie.","s":7},{"q":"Quels sont les objectifs des orthèses après lésion médullaire ?","o":["Favoriser la cicatrisation","Prévenir les déformations","Réduire la douleur","Protéger le tissu nerveux","Permettre l'appui immédiat"],"r":[0,1,2,3],"e":"Les quatre objectifs sont cités, la sélection se faisant selon le degré de restriction requis. Il s'agit de le protéger de lésions supplémentaires.","s":7},{"q":"Quelles manifestations composent le choc médullaire ?","o":["Une aréflexie sous la lésion","Une flaccidité des muscles","Une vessie non réflexe","Des intestins non réflexes","Une spasticité d'emblée"],"r":[0,1,2,3],"e":"Le choc médullaire est aréflexique et flasque ; la spasticité n'apparaît qu'au retour des réflexes, pour les lésions au-dessus de L1. La flaccidité touche les muscles innervés par les segments détruits ; la vessie impose le sondage.","s":7},{"q":"Quelle est la durée possible du choc médullaire ?","o":["De quelques heures à 3 mois","Toujours moins de 24 heures","Exactement 4 semaines","Plus d'un an"],"r":0,"e":"Le choc médullaire dure des heures, des jours, des semaines, jusqu'à 3 mois.","s":7},{"q":"Quand passe-t-on à la phase de lever ?","o":["Quand la colonne est stable, sans contre-indication","Dès la 48ᵉ heure, de façon systématique, sans examen","Après la fin complète du choc médullaire","Après six mois de lit, au minimum"],"r":0,"e":"Le passage à la phase de lever exige une condition vertébrale stable et l'absence de facteurs cliniques contraires. Il ne doit pas exister de facteurs cliniques contraires.","s":7},{"q":"Quelle distinction la fiche établit-elle à propos de la réhabilitation ?","o":["Réhabiliter, c'est rendre capable, non guérir","Le succès, c'est mieux vivre avec l'incapacité","La qualité de vie est un processus","Réhabiliter, c'est restaurer l'état antérieur"],"r":[0,1,2],"e":"Réhabiliter ≠ guérir, succès ≠ guérir, et la qualité de vie est un processus et non un état qu'on possède ou reçoit. La qualité de vie n'est pas un état qu'on possède ou qu'on reçoit.","s":7},{"q":"Quels facteurs contribuent à la survenue d'escarres ?","o":["Sensibilité et motricité altérées","Contrôle vasomoteur altéré, position","Collagène cutané dégradé","Chaleur et humidité excessives","Petit poids et tabac","Hypertension non traitée"],"r":[0,1,2,3,4],"e":"Tous ces facteurs contribuent, mais la cause directe reste la pression. La cause directe reste la pression ; le poids est inférieur à la moyenne.","s":7},{"q":"Pendant combien de temps la vulnérabilité aux escarres persiste-t-elle ?","o":["Toute la vie, dès le moment de la lésion","Les six premiers mois, seulement","La seule phase aiguë, à l'hôpital","Jusqu'à la reprise de la marche, si elle survient un jour"],"r":0,"e":"La vulnérabilité commence au moment de la lésion et se poursuit pour le reste de la vie.","s":7},{"q":"Quelles conséquences découlent d'une réduction de la capacité inspiratoire ?","o":["Des atélectasies","Une fatigue ventilatoire","Un encombrement bronchique","Une pneumonie de stase"],"r":[0,1],"e":"La limitation des muscles inspiratoires diminue la ventilation (atélectasies) et la fatigue mène à la défaillance ventilatoire. L'accumulation de sécrétions et les pneumonies relèvent de la capacité expiratoire. La fatigue peut mener à une défaillance ventilatoire ; l'encombrement et la pneumonie relèvent de la capacité expiratoire.","s":7},{"q":"À quel niveau lésionnel les muscles abdominaux deviennent-ils pleinement fonctionnels ?","o":["T10","T6","C5","C4"],"r":0,"e":"À T10, diaphragme, accessoires, intercostaux et abdominaux sont tous fonctionnels. À T6, les abdominaux ne le sont que partiellement.","s":7},{"q":"Quels sont les trois mécanismes de l'ostéoporose après lésion médullaire ?","o":["Une perte d'action musculaire","Une perte de calcium et de collagène","L'absence de mise en charge","Une carence en vitamine D"],"r":[0,1,2],"e":"Perte d'action musculaire, perte de calcium et de collagène par stase veineuse, et absence de charge. L'immobilité supprime l'action musculaire ; la perte de calcium et de collagène vient de la stase veineuse.","s":7},{"q":"Quelles conséquences l'ostéoporose entraîne-t-elle après lésion médullaire ?","o":["Des calculs vésicaux et rénaux","Des fractures spontanées","Une ossification hétérotopique","Une dysréflexie autonome"],"r":[0,1],"e":"Calculs vésicaux et rénaux, et fractures pathologiques spontanées. L'ossification hétérotopique et la dysréflexie sont des complications distinctes. Les fractures sont pathologiques.","s":7},{"q":"Quelles conséquences fonctionnelles l'ossification hétérotopique peut-elle entraîner ?","o":["Une ankylose extra-articulaire","Une restriction de la mobilité","Une diminution de la fonctionnalité","L'apparition d'escarres","Une amélioration de la mobilité articulaire"],"r":[0,1,2,3],"e":"Bien que l'articulation elle-même ne soit pas atteinte, l'ossification peut devenir assez massive pour provoquer une ankylose extra-articulaire, avec restriction de mobilité, perte de fonction et risque d'escarres.","s":7},{"q":"Quels signes et symptômes évoquent une embolie pulmonaire ?","o":["Difficultés respiratoires","Tachycardie","Douleur thoracique ou dorsale","Toux d'apparition soudaine","Fièvre élevée avec frissons"],"r":[0,1,2,3],"e":"Les quatre signes sont cités ; l'embolie pulmonaire est potentiellement fatale.","s":7},{"q":"Par quel biais le système nerveux sympathique participe-t-il à la thermorégulation ?","o":["Par le tonus vasculaire périphérique","Par la transpiration","Par la commande du diaphragme","Par la régulation de la glycémie"],"r":[0,1],"e":"Le sympathique régule la température via le tonus vasculaire périphérique et la transpiration.","s":7},{"q":"Quels signes accompagnent l'hypotension orthostatique après lésion médullaire ?","o":["Pâleur et tachycardie","Nausées et malaises","Vision floue, acouphènes, vertiges","Pouls faible, perte de conscience","Céphalée pulsatile, brutale"],"r":[0,1,2,3],"e":"Tous ces signes sont cités, conséquence de la perte de l'input sympathique cardiaque et de l'absence de vasoconstriction sous la lésion en position verticale. La vision peut se perdre ; le pouls devient difficile à palper.","s":7},{"q":"Quels stimuli peuvent déclencher une dysréflexie autonome ?","o":["Distension de la vessie ou du rectum","Infection urinaire, escarre","Ongle incarné, fracture","Contractions utérines, règles","Stress psychologique","Hypoglycémie à jeun, légère"],"r":[0,1,2,3,4],"e":"Tous ces stimuli, inoffensifs chez un sujet sans lésion médullaire, peuvent déclencher une dysréflexie autonome. Elle peut aussi survenir sans symptomatologie. La distension peut aussi être intestinale ; l'éjaculation peut déclencher la crise.","s":7},{"q":"Quels effets potentiellement avantageux la spasticité peut-elle avoir ?","o":["Le maintien du trophisme musculaire","Le maintien de la pompe musculaire","Moins d'escarres, sur les reliefs osseux","La réduction de la douleur chronique"],"r":[0,1,2],"e":"Trois effets avantageux. Les effets délétères comprennent au contraire la douleur, les contractures, la fatigue, les limitations fonctionnelles, les altérations cutanées et le risque de chute.","s":7},{"q":"Quelle question-guide oriente la cible de l'intervention en neurologie ?","o":["Le schéma est-il plus faible, lent, incoordonné ou confus ?","Le patient est-il jeune ou âgé, actif ou sédentaire, entouré ?","La lésion est-elle à droite ou à gauche ?","Le traitement est-il médical ou chirurgical ?"],"r":0,"e":"La réponse à cette question oriente directement la cible de l'intervention.","s":8},{"q":"Quelle est la particularité sémiologique de la SLA ?","o":["Signes du 1ᵉʳ et du 2ᵉ neurone moteur, associés","Signes du 1ᵉʳ neurone moteur seuls, sans atrophie","Signes du 2ᵉ neurone moteur seuls","Une atteinte sensitive au premier plan"],"r":0,"e":"C'est une maladie du neurone moteur marquée par la combinaison de signes du 1ᵉʳ et du 2ᵉ neurone moteur.","s":8},{"q":"Quel est le statut de la sensibilité dans la SLA ?","o":["Elle tend à rester relativement préservée","Elle est abolie précocement","Elle est le premier signe","Elle est remplacée par des paresthésies"],"r":0,"e":"La dégénérescence touche le faisceau cortico-spinal, cortico-bulbaire et la corne antérieure ; la sensibilité est relativement préservée.","s":8},{"q":"Quel phénotype de SLA n'implique que les neurones moteurs inférieurs des bras et des jambes ?","o":["L'atrophie musculaire progressive","La sclérose latérale primaire","La SLA hémiplégique","La SLA à début bulbaire"],"r":0,"e":"La sclérose latérale primaire implique au contraire les NMS ; l'atrophie musculaire progressive implique les NMI, souvent en proximal.","s":8},{"q":"Quel phénotype de SLA implique principalement les neurones moteurs supérieurs ?","o":["La sclérose latérale primaire","L'atrophie musculaire progressive","La SLA pseudopolynévritique","Le flail arm syndrome"],"r":0,"e":"Dans la sclérose latérale primaire, une atteinte NMI discrète peut être détectée plus tard dans la maladie.","s":8},{"q":"Quel principe d'intervention est central dans la SLA ?","o":["Un exercice sous-maximal, dosé selon la fatigue","Un renforcement à charge maximale","Un entraînement pliométrique intensif, pour la puissance","Une immobilisation stricte, au lit"],"r":0,"e":"Éviter la surcharge est aussi important que stimuler l'activité ; l'évaluation respiratoire doit être continue. On surveille la fatigue post-effort.","s":8},{"q":"Dans la SLA, la fonction dépend surtout de :","o":["La compensation précoce, plus que le réapprentissage","Le réapprentissage moteur, intensif","La récupération neurale spontanée, au fil des longs mois","La chirurgie, réalisée tôt"],"r":0,"e":"L'intervention est progressivement compensatoire, avec économie d'énergie et prévention des complications.","s":8},{"q":"Quelle altération primaire caractérise la maladie de Parkinson ?","o":["La perte de neurones à dopamine, nigro-striataux","Une expansion de triplets CAG, sur le chromosome 4","Une atrophie de l'hippocampe, bilatérale","Une démyélinisation des nerfs périphériques"],"r":0,"e":"La perte dopaminergique nigro-striatale altère l'équilibre voie directe/indirecte et réduit le drive thalamo-cortical.","s":8},{"q":"Quelle structure est le siège de l'altération primaire dans le Parkinson ?","o":["La substance noire pars compacta","Le noyau caudé, dans le striatum dorsal","L'hippocampe, dans le lobe temporal","Le cervelet, au niveau du vermis"],"r":0,"e":"Substance noire pars compacta et voie dopaminergique nigro-striatale.","s":8},{"q":"Pourquoi les indices externes sont-ils si pertinents dans la maladie de Parkinson ?","o":["Le déficit touche le circuit automatique","La vision est atteinte, dès le début","La force est diminuée, surtout aux membres inférieurs","La sensibilité est abolie, en distal"],"r":0,"e":"Le déficit d'automaticité crée une plus grande dépendance aux indices externes, qui remplacent le contrôle automatique perdu. Les indices externes remplacent le contrôle automatique perdu.","s":8},{"q":"À quel moment planifier la séance de kinésithérapie dans la maladie de Parkinson ?","o":["En période ON","En période OFF","Juste avant la prise du traitement","Indifféremment"],"r":0,"e":"L'éducation porte aussi sur le lien avec les périodes on/off et l'autocontrôle du freezing.","s":8},{"q":"Quel symptôme non moteur est attendu aux phases avancées du Parkinson ?","o":["Un ralentissement cognitif, une double tâche moins bonne","Une aphasie de Wernicke, avec un discours fluent et incohérent","Une héminégligence gauche, spatiale","Une astéréognosie, des deux mains"],"r":0,"e":"On note aussi un déficit de perception de l'amplitude du mouvement et une proprioception moins efficiente.","s":8},{"q":"Quelle est la base génétique de la maladie de Huntington ?","o":["Une mutation du gène HTT avec expansion CAG","Une mutation du gène SOD1","Une trisomie 21","Une mutation du gène de la dystrophine"],"r":0,"e":"Elle entraîne une dégénérescence neuronale striatale d'origine génétique.","s":8},{"q":"Quelles structures dégénèrent en premier dans la maladie de Huntington ?","o":["Le noyau caudé et le putamen, voie indirecte surtout","L'hippocampe, puis le cortex temporal","La substance noire, puis le cortex frontal et pariétal","Le cervelet, puis le tronc cérébral"],"r":0,"e":"Puis survient une atteinte corticale plus diffuse, via les circuits cortico-striato-thalamo-corticaux.","s":8},{"q":"Quel signe peut apparaître aux phases avancées de la maladie de Huntington ?","o":["Une rigidité et une plus grande lenteur","Une chorée améliorée, avec récupération motrice","Une aréflexie, des quatre membres","Un nystagmus isolé, horizontal"],"r":0,"e":"La présentation évolue : la chorée initiale peut céder la place à une rigidité et à une lenteur.","s":8},{"q":"Quel principe guide l'intervention dans la maladie de Huntington ?","o":["Une intervention simple et sûre, sans double tâche","Des tâches de plus en plus complexes, en double tâche constante","Un travail en environnement bruyant, exclusivement","Une absence de supervision, pour l'autonomie"],"r":0,"e":"La charge cognitive de la tâche modifie fortement la performance motrice ; il faut simplifier les consignes et contrôler l'environnement. L'intervention est aussi spécifique ; la double tâche est réduite.","s":8},{"q":"Quelle structure est le siège de l'atrophie initiale dans la maladie d'Alzheimer ?","o":["L'hippocampe","Le putamen","Le cervelet","La corne antérieure"],"r":0,"e":"Atrophie hippocampique et déconnexion cortico-corticale progressive, avec contribution du déficit cholinergique du prosencéphale basal.","s":8},{"q":"Quelles protéines sont impliquées dans la perte synaptique de la maladie d'Alzheimer ?","o":["La bêta-amyloïde et la protéine tau","L'alpha-synucléine et la dopamine","La huntingtine et la SOD1","La myéline et la gaine de Schwann"],"r":0,"e":"La perte synaptique et neuronale est liée aux dépôts de bêta-amyloïde et de protéine tau.","s":8},{"q":"En phase initiale d'Alzheimer, la limitation fonctionnelle s'explique surtout par :","o":["Le déficit cognitif","La faiblesse musculaire","La spasticité","L'ataxie"],"r":0,"e":"Aux phases tardives, mobilité et équilibre se dégradent aussi.","s":8},{"q":"Quelle stratégie pratique est recommandée dans la maladie d'Alzheimer ?","o":["Indices visuels, consignes courtes, cadre prévisible","Consignes longues et détaillées, répétées plusieurs fois","Environnement changeant, à chaque séance","Travail exclusivement analytique, segmentaire"],"r":0,"e":"L'entraînement fonctionnel se fait sur des routines répétées en contexte réel, avec éducation de l'aidant. L'entraînement est contextualisé.","s":8},{"q":"Dans l'ataxie cérébelleuse, quel est le problème central ?","o":["Affiner le mouvement en timing, précision et équilibre","Initier le mouvement, à son démarrage","Générer assez de force, en distal","Percevoir le stimulus, de façon consciente et bien précise"],"r":0,"e":"Le problème n'est pas d'initier le mouvement mais de l'affiner.","s":8},{"q":"Quel module cérébelleux compare le mouvement planifié à celui exécuté ?","o":["Le spinocervelet","Le cérébrocervelet","Le vestibulocervelet","Le noyau denté"],"r":0,"e":"Le spinocervelet reçoit les informations proprioceptives inconscientes en temps réel et fait des corrections immédiates.","s":8},{"q":"Quelle perte cellulaire rompt l'ajustement fin du mouvement dans l'ataxie ?","o":["La perte de cellules de Purkinje","La perte de motoneurones alpha","La perte de cellules pyramidales","La perte de cellules gliales"],"r":0,"e":"La perte de cellules de Purkinje et la dysfonction des noyaux profonds rompent l'ajustement fin et la stabilité posturale.","s":8},{"q":"Quel signe appendiculaire est cité dans l'ataxie cérébelleuse ?","o":["Le phénomène de rebond","La festination","Le freezing de marche","L'aréflexie distale"],"r":0,"e":"Avec la dysmétrie, la décomposition du mouvement, la dysdiadococinésie, le tremblement d'intention et le ralentissement de l'ajustement on-line.","s":8},{"q":"Quel test n'est PAS cité pour l'évaluation de l'ataxie ?","o":["Le squeeze test","L'échelle SARA","Le test TUG","Le test 6MWT"],"r":0,"e":"Les tests cités sont SARA, ICARS, Berg, TUG, 10 m, 6MWT et l'analyse fonctionnelle des escaliers et transferts. Le squeeze test explore la syndesmose de la cheville.","s":8},{"q":"Comment le traitement de l'ataxie répond-il le mieux ?","o":["Intensif, spécifique, répété en contexte réel","Passif et analytique, segment par segment","Court et espacé, une fois par semaine","Sans aucune mise en situation, au cabinet"],"r":0,"e":"C'est le principe énoncé pour l'intervention dans les ataxies cérébelleuses. Il doit être spécifique à la tâche ; le contexte est fonctionnel.","s":8},{"q":"Le syndrome de Guillain-Barré est :","o":["Une neuropathie inflammatoire aiguë, non dégénérative","Une maladie neurodégénérative, lente et progressive","Une atteinte centrale du cortex moteur, des deux côtés","Une myopathie génétique, héréditaire"],"r":0,"e":"C'est une note conceptuelle explicite du cours. Elle est généralement post-infectieuse.","s":8},{"q":"Quelle est la sémiologie typique du Guillain-Barré ?","o":["Une faiblesse ascendante et symétrique, avec aréflexie","Une faiblesse descendante, asymétrique, avec hyperréflexie","Une chorée, avec impulsivité et apathie","Un tremblement de repos, avec rigidité"],"r":0,"e":"S'y ajoutent paresthésies distales, douleur neuropathique, dysautonomie et risque d'insuffisance respiratoire.","s":8},{"q":"De quelle atteinte découle la faiblesse respiratoire dans le Guillain-Barré ?","o":["De l'atteinte du phrénique et des muscles ventilatoires","D'une atteinte cérébelleuse, bilatérale","D'une compression de la moelle, haute, au niveau cervical","D'une atteinte du cortex moteur primaire"],"r":0,"e":"La polyradiculonévrite touche racines et nerfs périphériques, dont le nerf phrénique.","s":8},{"q":"Quelle est la logique principale de l'intervention dans le Guillain-Barré ?","o":["Protéger, puis restaurer, en dosant l'effort","Renforcer à charge maximale dès la phase aiguë","Immobiliser jusqu'à la récupération complète","Travailler seulement la marche, sur tapis roulant"],"r":0,"e":"En phase aiguë : positionnement, prévention, mobilisation passive/assistée, hygiène bronchique et entraînement ventilatoire. On protège en phase aiguë, on restaure en subaigu, et on dose l'effort pour éviter la faiblesse par excès de travail.","s":8},{"q":"Quel indice sémiologique correspond à une atteinte des noyaux gris centraux ?","o":["Lenteur, rigidité, tremblement de repos, freezing","Base élargie, dysmétrie, tremblement intentionnel","Faiblesse ascendante aiguë, aréflexie, paresthésies","Mémoire récente altérée, désorientation"],"r":0,"e":"Les noyaux gris centraux gèrent initiation, échelle et automaticité : leur atteinte donne lenteur, rigidité, tremblement de repos, freezing et instabilité posturale. L'instabilité posturale s'y ajoute.","s":8},{"q":"Quelle fonction le circuit fronto-striatal assure-t-il ?","o":["L'inhibition motrice et la fonction exécutive","Le timing du mouvement et la correction de l'erreur","La mémoire épisodique et les praxies","La conduction nerveuse périphérique"],"r":0,"e":"Le circuit fronto-striatal assure l'inhibition motrice et la fonction exécutive — d'où la chorée, l'impulsivité et le déficit exécutif de la maladie de Huntington.","s":8},{"q":"Quelles voies sont dégénérées dans la SLA ?","o":["Le faisceau cortico-spinal","Le faisceau cortico-bulbaire","Les neurones de la corne antérieure","Les cordons postérieurs"],"r":[0,1,2],"e":"Dégénérescence des faisceaux cortico-spinal et cortico-bulbaire et perte des neurones de la corne antérieure. La sensibilité, portée par les cordons postérieurs, reste relativement préservée.","s":8},{"q":"Quels signes coexistent dans la sémiologie de la SLA ?","o":["Faiblesse, atrophie, fasciculations","Spasticité et hyperréflexie","Dysarthrie et dysphagie","Dyspnée d'effort","Perte thermo-algique"],"r":[0,1,2,3],"e":"Signes du 2ᵉ neurone (atrophie, fasciculations) et du 1ᵉʳ (spasticité, hyperréflexie), avec atteinte bulbaire et respiratoire. La sensibilité est relativement préservée. La faiblesse est progressive ; la sensibilité est relativement préservée.","s":8},{"q":"Quel phénotype de SLA touche les neurones moteurs inférieurs restreints aux membres distaux ?","o":["La forme pseudopolynévritique","Le syndrome du bras ballant","La forme à début bulbaire","La sclérose latérale primaire, centrale"],"r":0,"e":"SLA pseudopolynévritique : NMI restreints aux membres distaux. Le flail arm/flail leg touche les NMI des membres supérieurs ou inférieurs, souvent de façon asymétrique. C'est la SLA pseudopolynévritique ; le flail arm est le bras ballant.","s":8},{"q":"Quel phénotype de SLA associe une atteinte unilatérale des NMS avec épargne du visage ?","o":["La forme hémiplégique","La forme à début spinal, des membres","L'atrophie musculaire progressive","La forme à début bulbaire"],"r":0,"e":"La SLA hémiplégique se définit par une atteinte NMS unilatérale avec épargne du visage. C'est la SLA hémiplégique : atteinte unilatérale du NMS, visage épargné.","s":8},{"q":"Quels objectifs guident l'intervention dans la SLA ?","o":["Préserver la fonction, le plus longtemps","Éviter la fatigue et les complications","Préparer les aides et soutenir l'aidant","Restaurer la force au niveau antérieur"],"r":[0,1,2],"e":"Préserver, éviter la fatigue et préparer les adaptations. Dans la SLA, la fonction dépend moins du réapprentissage et plus de la compensation précoce. On préserve aussi le confort et la participation ; on prépare les adaptations.","s":8},{"q":"Que faut-il évaluer et réviser en continu dans la SLA ?","o":["La force fonctionnelle et la fatigue","La ventilation et la toux","Les aides et le soutien de l'aidant","Le score de douleur, seul"],"r":[0,1,2],"e":"Force fonctionnelle et fatigue post-effort, schéma ventilatoire et toux, besoins en aides techniques et soutien de l'aidant. L'évaluation respiratoire doit être continue. La fatigue est post-effort ; on évalue le schéma ventilatoire et la capacité à tousser.","s":8},{"q":"Quels symptômes non moteurs accompagnent la maladie de Parkinson ?","o":["Amplitude et proprioception mal perçues","Douleur, fatigue, dysautonomie","Lenteur cognitive, double tâche difficile","Perte de la sensibilité thermique"],"r":[0,1,2],"e":"Perception de l'amplitude et proprioception, douleur, fatigue, dysautonomie, puis ralentissement cognitif et difficultés en double tâche. Le ralentissement cognitif apparaît aux phases avancées.","s":8},{"q":"Quelles pratiques composent l'intervention dans la maladie de Parkinson ?","o":["Indices auditifs et visuels pour la marche","Amplitude, transferts, retournements, marches","Équilibre, force et aérobie bien dosés","Éducation sur le freezing et les phases on/off","Attelle d'immobilisation, portée chaque nuit"],"r":[0,1,2,3],"e":"Les quatre axes sont cités, la spécificité de la tâche étant décisive. Les indices servent à initier et maintenir la marche ; l'éducation porte aussi sur la sécurité.","s":8},{"q":"Que faut-il évaluer et réviser dans la maladie de Parkinson ?","o":["La vitesse et la qualité de la marche","L'équilibre anticipatoire et réactif","L'impact des fluctuations motrices","La capacité vitale, à la spirométrie"],"r":[0,1,2],"e":"Marche, équilibre anticipatoire et réactif, impact des fluctuations motrices. La capacité vitale forcée s'évalue plutôt dans la SLA et le Guillain-Barré.","s":8},{"q":"Quels signes composent la sémiologie de la maladie de Huntington ?","o":["Une chorée","Saccades oculaires altérées","Instabilité, déficit exécutif","Impulsivité, apathie, dysphagie","Tremblement de repos à 3-5 Hz"],"r":[0,1,2,3],"e":"Chorée, saccades, instabilité, déficit exécutif, impulsivité/apathie et dysphagie tardive. Rigidité et lenteur peuvent apparaître aux phases avancées. La dysphagie apparaît aux phases tardives.","s":8},{"q":"Quels symptômes cognitivo-comportementaux accompagnent la maladie de Huntington ?","o":["Traitement ralenti, déficit exécutif","Attention instable","Dépression, irritabilité, apathie","Sécurité mal perçue en mobilité","Hallucinations visuelles précoces"],"r":[0,1,2,3],"e":"Les quatre éléments sont cités et expliquent que la charge cognitive de la tâche modifie fortement la performance motrice. L'anxiété en fait aussi partie.","s":8},{"q":"Quelles stratégies composent l'intervention dans la maladie de Huntington ?","o":["Marche et équilibre, en environnement contrôlé","Aérobie et force, selon tolérance","Postural set, transfert de poids, tronc","Éducation aux chutes et aux aides techniques","Double tâche systématique, pour la cognition"],"r":[0,1,2,3],"e":"Les quatre premières. Il faut au contraire réduire la double tâche, simplifier les consignes et prioriser la sécurité. Les tâches sont claires ; l'éducation porte aussi sur le positionnement.","s":8},{"q":"Quelles structures sont atteintes successivement dans la maladie d'Alzheimer ?","o":["L'hippocampe","Le cortex entorhinal et temporal médial","Les aires pariéto-temporales","Le noyau subthalamique"],"r":[0,1,2],"e":"Hippocampe, cortex entorhinal/temporal médial, puis aires pariéto-temporales, avec une contribution du déficit cholinergique du prosencéphale basal.","s":8},{"q":"Quels objectifs guident l'intervention dans la maladie d'Alzheimer ?","o":["Maintenir mobilité, autonomie, participation","Réduire chutes, immobilité et sédentarité","Faciliter des routines sûres, avec l'aidant","Restaurer la mémoire récente, à long terme"],"r":[0,1,2],"e":"Maintenir la mobilité et la participation, réduire les risques liés à la sédentarité et faciliter des routines sûres.","s":8},{"q":"Quels signes axiaux et de marche caractérisent l'ataxie cérébelleuse ?","o":["Base élargie, tronc qui oscille","Pas irréguliers, demi-tours difficiles","Aggravation en double tâche","Festination, pas accélérés"],"r":[0,1,2],"e":"Base élargie, oscillations du tronc, pas irréguliers, difficulté aux demi-tours et aggravation en double tâche. La festination est parkinsonienne. L'aggravation se voit aussi sur les surfaces difficiles.","s":8},{"q":"Quels autres signes accompagnent l'ataxie cérébelleuse ?","o":["Nystagmus","Dysarthrie scandée","Hypotonie","Coordination fine difficile","Aréflexie diffuse"],"r":[0,1,2,3],"e":"Nystagmus, dysarthrie scandée, hypotonie et difficultés de coordination fine. L'aréflexie évoque le Guillain-Barré. La coordination fine touche l'écriture et l'alimentation.","s":8},{"q":"Quelles précautions d'évaluation sont propres aux ataxies ?","o":["Classer la gravité et le phénotype","Évaluer avec et sans indices visuels","Explorer le contexte réel du patient","Orienter en cas de signe associé","Mesurer la pression intracrânienne"],"r":[0,1,2,3],"e":"Les quatre axes sont cités pour l'évaluation des ataxies. Phénotype vestibulaire, tronculaire, appendiculaire ou mixte ; on change aussi la base de support ; le contexte inclut fatigue, double tâche, domicile et chutes ; les signes associés sont dysphagie, dysarthrie, douleur, dépression ou déficit cognitif.","s":8},{"q":"Quelles formes le syndrome de Guillain-Barré peut-il prendre ?","o":["Une forme démyélinisante","Une forme axonale","Une forme centrale","Une forme musculaire"],"r":[0,1],"e":"C'est une polyradiculonévrite aiguë immunomédiée, démyélinisante ou axonale, touchant racines spinales et nerfs périphériques. La forme démyélinisante ralentit la conduction.","s":8},{"q":"Sur quoi l'étude des instruments doit-elle mettre l'accent ?","o":["La compréhension de l'utilité et de l'applicabilité","La mémorisation détaillée des procédures","L'apprentissage par cœur des seuils","La reproduction exacte des feuilles de cotation"],"r":0,"e":"Le document d'orientation demande explicitement de privilégier la compréhension de l'utilité et de l'applicabilité.","s":9},{"q":"Que doit-on savoir identifier pour chaque instrument ?","o":["Ses avantages, ses limites, sa pertinence","Son nom et son auteur, uniquement, par cœur","Son année de publication, et sa version","Sa durée de passation, en minutes"],"r":0,"e":"Les étudiants doivent aussi comprendre ce que l'outil mesure, à quelle population il s'adresse et ses conditions d'application. La pertinence dépend du contexte clinique.","s":9},{"q":"Combien de points les instruments de mesure représentent-ils à l'examen théorique ?","o":["2 points sur 20","4 points sur 20","10 points sur 20","Aucun point"],"r":0,"e":"Répartition : 10 pts SLNMS/sensoriel/cognitif/cérébelleux/hypo-hyperkinétique, 4 pts neurodégénératif, 4 pts lésions médullaires, 2 pts instruments.","s":9},{"q":"Que mesure le MMSE ?","o":["Un dépistage global du statut cognitif","L'équilibre dynamique, à la marche","La spasticité des fléchisseurs","La sensibilité tactile, aux mains et aux pieds"],"r":0,"e":"Le MMSE explore orientation, mémoire, attention et calcul, langage et praxie constructive.","s":9},{"q":"Quel est l'avantage du MoCA par rapport au MMSE ?","o":["Il est plus sensible aux troubles cognitifs légers","Il est plus rapide à faire passer","Il ne demande aucun matériel, ni crayon","Il évalue aussi l'équilibre et la marche, en même temps"],"r":0,"e":"Le MoCA explore davantage les fonctions exécutives, l'attention et l'abstraction. Il explore davantage les fonctions exécutives.","s":9},{"q":"Que mesure le Nottingham Sensory Assessment ?","o":["La sensibilité, territoire par territoire","La force musculaire, segment par segment, au testing","La qualité de la marche, observée","L'indépendance dans la vie quotidienne"],"r":0,"e":"C'est une évaluation standardisée de la sensibilité, très utilisée après AVC. Elle porte sur la sensibilité tactile, proprioceptive et discriminative.","s":9},{"q":"Que mesure l'échelle de Berg ?","o":["L'équilibre, à travers des tâches fonctionnelles","La spasticité, à l'étirement passif rapide des muscles","La coordination des membres supérieurs","La perception de l'effort, à l'exercice"],"r":0,"e":"Elle comprend des tâches comme se lever, se tourner, l'appui unipodal ou ramasser un objet. L'équilibre est statique et dynamique.","s":9},{"q":"Quelle est la particularité du BESTest ?","o":["Il décompose l'équilibre par systèmes posturaux","Il ne mesure que la marche, chronométrée","Il ne s'applique qu'aux patients parkinsoniens, en début","Il est purement auto-rapporté, par écrit"],"r":0,"e":"Il permet de cibler le système déficitaire : biomécanique, limites de stabilité, ajustements anticipatoires, réponses posturales, orientation sensorielle, stabilité à la marche. Les systèmes sont ceux du contrôle postural.","s":9},{"q":"Qu'est-ce qui distingue l'échelle de Tardieu de l'Ashworth modifiée ?","o":["Tardieu contrôle la vitesse et note l'angle de réaction","Tardieu est plus rapide à faire passer","Ashworth mesure aussi la coordination","Tardieu ne s'applique qu'aux enfants paralysés cérébraux"],"r":0,"e":"Tardieu évalue la spasticité au sens strict en contrôlant la vitesse ; l'Ashworth modifiée mesure plutôt l'hypertonie.","s":9},{"q":"Que mesure principalement l'Ashworth modifiée ?","o":["La résistance au mouvement passif","La force volontaire maximale","L'amplitude articulaire active","La sensibilité profonde, au gros orteil"],"r":0,"e":"Elle ne contrôle pas la vitesse d'étirement, ce qui limite son interprétation comme mesure de spasticité stricte. Elle mesure l'hypertonie.","s":9},{"q":"Que mesure la SARA ?","o":["La sévérité de l'ataxie","La spasticité","L'indépendance fonctionnelle","La qualité de vie"],"r":0,"e":"Elle comprend marche, station debout, position assise, parole, poursuite du doigt, doigt-nez, mouvements alternés rapides et talon-tibia.","s":9},{"q":"À quelle population s'adresse la Wisconsin Gait Scale ?","o":["Aux hémiparétiques, après un accident vasculaire","Aux patients ataxiques, cérébelleux","Aux patients parkinsoniens, en phase on","Aux enfants atteints de paralysie cérébrale, spastiques"],"r":0,"e":"C'est une analyse qualitative et observationnelle de la marche hémiparétique.","s":9},{"q":"Que mesure le Dynamic Gait Index ?","o":["L'adaptation de la marche aux exigences de la tâche","La vitesse sur 10 mètres, uniquement","L'endurance de marche sur 6 minutes","La force des membres inférieurs, au dynamomètre portatif"],"r":0,"e":"Changements de vitesse, rotations de tête, demi-tours, obstacles et escaliers.","s":9},{"q":"Que mesure la Reaching Performance Scale ?","o":["La qualité de l'atteinte, avec ses compensations","La force de préhension, au dynamomètre","La sensibilité de la main, aux filaments","L'équilibre assis, sans appui des mains ni des pieds"],"r":0,"e":"Elle est utilisée chez les patients post-AVC et documente trajectoire, compensations et préhension. Les compensations sont celles du tronc et de l'épaule.","s":9},{"q":"Quel instrument est construit sur les stades de récupération motrice après AVC ?","o":["Le Fugl-Meyer","Le TUG","Le MMSE","La Berg"],"r":0,"e":"Le Fugl-Meyer évalue fonction motrice, sensibilité, amplitude passive, douleur articulaire et équilibre ; c'est une référence en recherche.","s":9},{"q":"Que documente la MIF ?","o":["Le niveau d'aide dans les activités quotidiennes","La force musculaire, segment par segment, au testing","La spasticité, à l'étirement","La coordination fine, des doigts"],"r":0,"e":"Soins personnels, contrôle sphinctérien, transferts, locomotion, communication et conscience du monde extérieur.","s":9},{"q":"En quoi consiste le Timed Up and Go ?","o":["Se lever, marcher, faire demi-tour, revenir s'asseoir","Marcher six minutes, le plus loin possible, en couloir","Tenir en appui unipodal, yeux fermés","Monter et descendre un escalier, chronométré"],"r":0,"e":"C'est un test de mobilité fonctionnelle chronométrée, utilisé pour le dépistage du risque de chute. La distance de marche est définie ; on part d'une chaise.","s":9},{"q":"Dans quel domaine CIF classe-t-on le TUG et la MIF ?","o":["Activité et participation","Structures et fonctions","Affections spécifiques","Facteurs environnementaux"],"r":0,"e":"Berg, BESTest, Fugl-Meyer, SARA, MMSE et Nottingham relèvent des structures et fonctions.","s":9},{"q":"Quel instrument est spécifique de la lésion médullaire ?","o":["L'ASIA","Le MDS-UPDRS","L'ALSFRS-R","Le GMFM"],"r":0,"e":"ASIA = classification neurologique et fonctionnelle des lésions médullaires ; les autres concernent Parkinson, la SLA et la paralysie cérébrale.","s":9},{"q":"Quel instrument est spécifique de la maladie de Parkinson ?","o":["Le MDS-UPDRS","L'ASIA","Le GMFM","Le STREAM"],"r":0,"e":"Le MDS-UPDRS évalue expériences non motrices et motrices du quotidien, examen moteur et complications motrices.","s":9},{"q":"Quel instrument suit le statut fonctionnel dans la SLA ?","o":["L'ALSFRS-R","Le PDQ-39","La Berg","Le MoCA"],"r":0,"e":"L'ALSFRS-R inclut notamment une composante respiratoire.","s":9},{"q":"Quel instrument mesure la fonction motrice globale en paralysie cérébrale ?","o":["Le GMFM","Le MAS","Le STREAM","Le PASS"],"r":0,"e":"GMFM = Gross Motor Function Measure.","s":9},{"q":"Que mesure le Motor Activity Log ?","o":["L'usage réel du membre supérieur parétique au quotidien","La force de préhension, au dynamomètre","La sensibilité de la main, au toucher","L'amplitude de l'épaule, mesurée au goniomètre, en élévation"],"r":0,"e":"C'est un outil auto-rapporté qui documente l'usage réel, et non la capacité en situation de test. Il porte sur la quantité et la qualité de cet usage.","s":9},{"q":"Que mesure la Falls Efficacy Scale ?","o":["La confiance à réaliser des activités sans tomber","Le nombre de chutes survenues au cours de l'année écoulée","L'équilibre dynamique, à la marche","La vitesse de marche, sur 10 mètres"],"r":0,"e":"Elle documente la peur de tomber, dimension psychologique importante du risque de chute.","s":9},{"q":"Quelle est la différence entre le SF-36 et le PDQ-39 ?","o":["Le SF-36 est générique, le PDQ-39 propre au Parkinson","Le SF-36 est propre à l'AVC, le PDQ-39 générique","Le PDQ-39 est générique, le SF-36 propre au diabète","Ils mesurent tous deux l'équilibre, chez la personne âgée"],"r":0,"e":"SF-36 = qualité de vie générique ; PDQ-39 = qualité de vie spécifique au Parkinson.","s":9},{"q":"Que mesure le PASS ?","o":["L'évaluation posturale, après un accident vasculaire","La perception de l'effort et de l'essoufflement, à l'exercice","La sensibilité, tactile et profonde","La cognition globale, au dépistage"],"r":0,"e":"Le PASS est une échelle d'évaluation posturale développée pour les patients post-AVC.","s":9},{"q":"Que mesure l'échelle de Borg modifiée ?","o":["La perception de l'effort ou de la dyspnée","L'équilibre, statique et dynamique","La spasticité, à l'étirement","La coordination des membres, au test doigt-nez"],"r":0,"e":"C'est une échelle subjective d'auto-évaluation de l'effort perçu.","s":9},{"q":"Quelle question ne fait PAS partie du raisonnement de choix d'un instrument ?","o":["L'instrument est-il connu de mes collègues ?","Quel domaine CIF je veux documenter ?","L'outil est-il validé pour cette population ?","L'outil est-il sensible au changement attendu ?"],"r":0,"e":"Les critères pertinents sont le domaine CIF, la validation pour la population, le temps de passation et la sensibilité au changement.","s":9},{"q":"Que mesure le STREAM ?","o":["Le mouvement volontaire et la mobilité de base","La sensibilité discriminative, fine","La qualité de vie, générique et spécifique, à domicile","La spasticité, à l'étirement passif"],"r":0,"e":"STREAM = Stroke Rehabilitation Assessment of Movement. STREAM : Stroke Rehabilitation Assessment of Movement, après AVC.","s":9},{"q":"Quelle est la bonne attitude face aux valeurs de cotation et aux seuils d'un instrument ?","o":["Toujours les vérifier dans le document original","Les mémoriser sans jamais les vérifier","Les estimer selon le contexte clinique et l'expérience","Les ignorer complètement, en pratique"],"r":0,"e":"Les descriptions de révision servent de repère ; les cotations, consignes et seuils exacts doivent être vérifiés dans le document source.","s":9},{"q":"Quelles caractéristiques principales faut-il explorer pour chaque instrument ?","o":["Ce qu'il permet de mesurer","À quelle population il s'adresse","Ses conditions d'application","Le nom de ses auteurs et sa date"],"r":[0,1,2],"e":"Trois caractéristiques : ce qu'il mesure, sa population cible et ses conditions d'application — l'accent étant mis sur l'utilité et l'applicabilité.","s":9},{"q":"Quels domaines le MMSE explore-t-il ?","o":["Orientation","Mémoire immédiate et différée","Attention et calcul","Langage et praxie constructive","Fonctions exécutives"],"r":[0,1,2,3],"e":"Le MMSE couvre orientation, mémoire immédiate et différée, attention et calcul, langage et praxie constructive. C'est le MoCA qui explore davantage les fonctions exécutives et l'abstraction. Les fonctions exécutives et l'abstraction relèvent plutôt du MoCA.","s":9},{"q":"À quelles populations le MoCA s'adresse-t-il ?","o":["Troubles cognitifs légers","Maladies neurodégénératives","Post-AVC","Lésions médullaires isolées"],"r":[0,1,2],"e":"Troubles cognitifs légers, maladies neurodégénératives et post-AVC : le MoCA est plus sensible que le MMSE aux troubles légers.","s":9},{"q":"Quelles modalités sensorielles le Nottingham Sensory Assessment évalue-t-il ?","o":["La sensibilité tactile","La sensibilité proprioceptive","La discrimination, la stéréognosie","La seule sensibilité thermique"],"r":[0,1,2],"e":"Le Nottingham évalue la sensibilité tactile, proprioceptive et discriminative (stéréognosie), par territoire corporel. L'évaluation se fait par territoire corporel.","s":9},{"q":"Quelles tâches fonctionnelles composent l'échelle de Berg ?","o":["Se lever","Se tourner","Appui unipodal","Ramasser un objet","Monter des marches"],"r":[0,1,2,3],"e":"L'échelle de Berg évalue l'équilibre statique et dynamique à travers ces tâches fonctionnelles.","s":9},{"q":"Quels systèmes de contrôle postural le BESTest décompose-t-il ?","o":["Biomécanique, limites de stabilité","Ajustements anticipatoires, réponses posturales","Orientation sensorielle","Stabilité à la marche","Force isométrique des jambes"],"r":[0,1,2,3],"e":"Six systèmes, ce qui permet de cibler le système déficitaire. Le BESTest existe aussi en versions abrégées. Les ajustements sont posturaux anticipatoires.","s":9},{"q":"Que note-t-on précisément dans l'échelle de Tardieu ?","o":["La qualité de la réaction musculaire","L'angle d'apparition de la réaction","À différentes vitesses d'étirement","Le temps de maintien de la position"],"r":[0,1,2],"e":"Tardieu note la qualité de la réaction musculaire et l'angle d'apparition, à différentes vitesses — c'est ce contrôle de la vitesse qui la distingue de l'Ashworth.","s":9},{"q":"Quels items composent la SARA ?","o":["Marche, station debout et position assise","Troubles de la parole","Poursuite du doigt et doigt-nez","Mouvements alternés rapides et talon-tibia","Orientation spatio-temporelle"],"r":[0,1,2,3],"e":"Huit items couvrant marche, station debout, assise, parole, poursuite du doigt, doigt-nez, mouvements alternés rapides et talon-tibia.","s":9},{"q":"Quelles exigences de tâche le Dynamic Gait Index explore-t-il ?","o":["Changements de vitesse","Rotations de tête, demi-tours","Obstacles à franchir ou contourner","Montée d'escaliers","Plan incliné à 10°, en montée"],"r":[0,1,2,3],"e":"Le DGI mesure la capacité à adapter la marche à ces différentes exigences ; il s'adresse aux personnes à risque de chute et aux troubles vestibulaires et neurologiques.","s":9},{"q":"Quels aspects la Reaching Performance Scale évalue-t-elle ?","o":["La trajectoire du geste","Les compensations du tronc","La préhension finale","La force de serrage, en kg"],"r":[0,1,2],"e":"Elle évalue la qualité de l'atteinte : trajectoire, compensations du tronc et de l'épaule, et préhension. Les compensations de l'épaule sont aussi notées.","s":9},{"q":"Quels domaines le Fugl-Meyer évalue-t-il ?","o":["La motricité des membres","La sensibilité","L'amplitude passive et la douleur","L'équilibre","Le statut cognitif"],"r":[0,1,2,3],"e":"Le Fugl-Meyer, référence en recherche post-AVC, couvre motricité, sensibilité, amplitude passive, douleur articulaire et équilibre. La motricité concerne les membres supérieur et inférieur ; la douleur est articulaire.","s":9},{"q":"Quels domaines la MIF documente-t-elle ?","o":["Soins personnels et contrôle sphinctérien","Transferts et locomotion","Communication","Conscience du monde extérieur","Qualité de vie liée à la santé"],"r":[0,1,2,3],"e":"La MIF mesure le niveau d'aide nécessaire dans ces domaines et suit le fardeau de soins.","s":9},{"q":"Quelles étapes compose le Timed Up and Go ?","o":["Se lever d'une chaise","Marcher une distance définie","Faire demi-tour","Revenir et se rasseoir","Monter sur un tabouret"],"r":[0,1,2,3],"e":"Le TUG chronomètre cette séquence ; il sert au dépistage du risque de chute chez la personne âgée et le patient neurologique.","s":9},{"q":"Quels instruments relèvent du domaine CIF « structures et fonctions » ?","o":["Berg et BESTest","Fugl-Meyer et SARA","MMSE et Nottingham","TUG et MIF"],"r":[0,1,2],"e":"Structures et fonctions : Berg, BESTest, Fugl-Meyer, SARA, MMSE, Nottingham, MAS, PASS, STREAM et Borg modifiée. TUG et MIF relèvent de l'activité et de la participation.","s":9},{"q":"Quels instruments relèvent du domaine « activité et participation » ?","o":["Barthel modifiée, Motor Activity Log","Falls Efficacy Scale","SF-36, PDQ-39, impact AVC","ASIA et MDS-UPDRS, spécifiques"],"r":[0,1,2],"e":"Activité et participation : TUG, DGI, MIF, Barthel modifiée, Motor Activity Log, Reaching Performance Scale, Falls Efficacy Scale, SF-36, PDQ-39 et questionnaire d'impact AVC. ASIA et MDS-UPDRS relèvent des affections spécifiques. Le questionnaire d'impact concerne l'AVC.","s":9},{"q":"Quelles questions composent le réflexe de raisonnement clinique avant de choisir un outil ?","o":["Quel domaine CIF je veux documenter ?","L'outil est-il validé pour cette population ?","Combien de temps prend-il ?","Est-il sensible au changement que j'espère observer ?","Quel est le coût de l'instrument ?"],"r":[0,1,2,3],"e":"Les quatre questions constituent le réflexe de choix d'un instrument.","s":9},{"q":"Que mesure l'échelle de Barthel modifiée ?","o":["L'indépendance dans les activités de base","La peur de tomber, au quotidien","La qualité de vie générique, physique et mentale","La performance motrice, après un AVC"],"r":0,"e":"Barthel modifiée : indépendance dans les activités de base de la vie quotidienne. Il s'agit des activités de base de la vie quotidienne.","s":9},{"q":"Quelles dimensions le Motor Activity Log explore-t-il ?","o":["La quantité d'usage réel du bras","La qualité de cet usage au quotidien","Le caractère auto-rapporté","La force isométrique maximale"],"r":[0,1,2],"e":"Le Motor Activity Log est auto-rapporté et documente quantité et qualité d'usage réel du membre supérieur parétique au quotidien. Il s'agit du membre supérieur parétique.","s":9},{"q":"Que mesure le MAS (Motor Assessment Scale) ?","o":["La performance motrice fonctionnelle après l'accident","Le mouvement volontaire et la mobilité de base","La seule évaluation posturale, assis puis debout, au lit","La spasticité, à l'étirement passif"],"r":0,"e":"MAS : performance motrice fonctionnelle après AVC. STREAM : mouvement volontaire des membres et mobilité de base. PASS : évaluation posturale spécifique après AVC. MAS : Motor Assessment Scale, après AVC.","s":9},{"q":"Que couvre le MDS-UPDRS ?","o":["Les expériences non motrices du quotidien","Les expériences motrices du quotidien","L'examen moteur","Les complications motrices","La composante respiratoire"],"r":[0,1,2,3],"e":"Le MDS-UPDRS évalue globalement la maladie de Parkinson selon ces quatre parties. C'est l'ALSFRS-R qui inclut une composante respiratoire, dans la SLA.","s":9}]};
